                    text3Loc = string.Format("{0}: {1} güç, {2} can", value.DisplayedNameLocalized, value.Attack, value.Health) + text4Loc;
                }
                string text5 = string.Concat(new string[] { text2, " ", value.DisplayedName, " is created in your hand. ", text3 });
                string text5LocCardName = value.DisplayedNameLocalized;
                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, " kartı oluşur. ", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.Turkish);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", value.DisplayedNameLocalized + " oyun alanındayken dost Arazi ve Post kartlarını kaldırın ve kalanları rastgele Havarilere dönüştürün.", Language.Turkish);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]Saat[c:] ve [c:bR]" + value.DisplayedNameLocalized + "[c:] kartın o terk edilmiş zamanda kalacak.", Language.Turkish);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "Sahte " + value.DisplayedNameLocalized, Language.Turkish);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]" + value.DisplayedNameLocalized + " kartını oynamak için yeterli enerjin yok.[c:]", Language.Turkish);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Hâlâ anlamadın mı? Bedeli " + max.ToString() + " enerji, sende yeterince yok.[c:]", Language.Turkish);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Bedeli " + max.ToString() + " enerji, sende ise " + count.ToString() + " var.[c:]", Language.Turkish);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "[c:bG]Terazin[c:] çok fazla aleyhine eğilmiş; [c:bG]" + value.DisplayedNameLocalized + "[c:] oynanamaz.", Language.Turkish);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:] için can ödemen gerekiyor; bunu ölmeden yapamazsın.", Language.Turkish);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "[c:bG]" + value.DisplayedNameLocalized + "[c:] kartını oynamak seni öldürür. [c:bG]Terazin[c:] fazla eğilmiş.", Language.Turkish);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "[c:bG]Terazin[c:] çok fazla eğilmiş ve " + value.DisplayedNameLocalized + " oynamak için yeterli [c:gray]Parlak Kartın[c:] yok.", Language.Turkish);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:] kartını oynamak için yeterli Parlak Kartın yok.", Language.Turkish);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:] bedeli [c:gray]Parlak Kartla[c:] ödenir; sende [c:gray]" + count.ToString() + "[c:] tane var.", Language.Turkish);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:] bedeli [c:gray]" + count.ToString() + "[c:] Parlak Kart, sende yeterince yok.", Language.Turkish);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", value.DisplayedNameLocalized + " Koruyucusu", Language.Turkish);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

