            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the dll is placed in BepInEx/scripts, this will allow running certain commands that should only ever be ran to re-add abilities/cards back in the game correctly.", "DLL, BepInEx/scripts klasöründeyse yalnızca yetenekleri ve kartları oyuna doğru biçimde yeniden eklemek için kullanılması gereken belirli komutların çalıştırılmasını sağlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For players who want to continue playing with their deck after defeating Grimora.", "Grimora'yı yendikten sonra destesiyle oynamaya devam etmek isteyen oyuncular içindir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Use the mod's internal blueprint system.\n1 = Randomized. Encounters are completely randomized using the mod's internal card pool.\n2 = Custom. Encounters are from made and used from the JSON files.\n3 = Mixed. Encounters are from both default list and custom list.", "0 = Varsayılan. Modun kendi taslak sistemini kullanır.\n1 = Rastgele. Karşılaşmalar modun kendi kart havuzundan tamamen rastgele oluşturulur.\n2 = Özel. Karşılaşmalar JSON dosyalarından oluşturulur.\n3 = Karma. Karşılaşmalar hem varsayılan hem özel listeden alınır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = W for viewing deck, S for getting up from the table.\n1 = Up arrow for viewing deck, down arrow for getting up from the table.", "0 = Desteyi görmek için W, masadan kalkmak için S.\n1 = Desteyi görmek için yukarı ok, masadan kalkmak için aşağı ok.", Language.Turkish);
