            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to deal 1 damage to the creature across from [creature].", "1 ruh ödeyerek [creature] karşısındaki yaratığa 1 hasar ver.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disinter", "Mezardan Çıkar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to create a Skeleton in your hand.", "1 kemik ödeyerek elinde bir İskelet oluştur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Materialize", "Somutlaştır", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls for [creature] to summon a copy in your hand.", "2 ruh öde; [creature] kendi kopyasını eline çağırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls, [creature] will trap a random opponent card in a coffin, which will release the original card again upon perishing.", "2 ruh öde. [creature] rastgele bir rakip kartını tabuta hapseder. Tabut yok olduğunda asıl kart serbest kalır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funeral Rites", "Cenaze Töreni", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Sucker", "Ruh Emici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent creature perishes, [creature] will store a charge of soul energy, up to 4. Activating this sigil will add 3 soul energy to your current energy counter, and one max energy.", "Bir rakip yaratığı öldüğünde [creature] bir ruh enerjisi yükü biriktirir; en fazla 4 yük tutabilir. Bu mühür etkinleştirildiğinde mevcut enerji sayacına 3 ruh enerjisi eklenir ve azami enerjin bir artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weighted Die", "Hileli Zar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones for the power of [creature] to be randomized between 0 and 5.", "2 kemik öde; [creature] adlı kartın gücü 0 ile 5 arasında rastgele belirlensin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] alternates between striking the opposing space to the left and right from it.", "[creature], sol ve sağ çaprazındaki rakip yuvalarına dönüşümlü saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is unaffected by the motion of the ship.", "[creature] geminin hareketinden etkilenmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, and each opposing space to the left, right, and center of it.", "[creature], bitişiğindeki yuvalara ve sol çaprazındaki, sağ çaprazındaki ve tam karşısındaki tüm rakip yuvalarına saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] yields no bones upon death.", "[creature] öldüğünde kemik vermez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, gain 2 bones.", "[creature] başka bir yaratığı öldürdüğünde 2 kemik kazanırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Soul from you at the end of every turn and stores it as 2 Bones, up to a maximum of 8. When [creature] dies, you gain all bones contained in it.", "[creature] her turun sonunda senden 1 ruh alır ve bunu 2 kemik olarak biriktirir; en fazla 8 kemik tutabilir. [creature] öldüğünde içinde biriken tüm kemikleri kazanırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers each Skeleton on the owner's side of the board, providing a +1 buff to their power.", "[creature], oyun tahtasında sahibinin tarafındaki her İskeletin gücünü +1 artırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Shanty", "Denizci Türküsü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slots to the left, right, and center of it randomly, up to 3 times.", "[creature], sol çaprazındaki, sağ çaprazındaki ve tam karşısındaki rakip yuvalarına en fazla 3 kez rastgele saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the card opposing it is Frozen Away if not already frozen.", "[creature] öldüğünde karşısındaki kart henüz donmamışsa Donmuş etkisini kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, gain a consumable item, if you have a free slot.", "[creature] öldüğünde boş bir eşya yuvan varsa tüketilebilir bir eşya kazanırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Skeleton is created in each empty space on the owner's side. [define:Skeleton]", "[creature] oynandığında sahibinin tarafındaki her boş yuvada bir İskelet oluşturulur. [define:Skeleton]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Horde", "İskelet Sürüsü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck Finder", "Enkaz Bulucu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Shipwreck is created on each empty adjacent space. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", "[creature] oynandığında bitişiğindeki her boş yuvada bir Gemi Enkazı oluşturulur. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons Within", "İçindeki İskeletler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, draw a card from your Skeleton pile.", "[creature] darbe aldığında İskelet yığınından bir kart çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full o' candy", "Şeker Dolu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will yield candy upon death, maybe this will be useful for later.", "[creature] öldüğünde şeker bırakır. Belki daha sonra işe yarar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in a random direction.", "Sahibinin turunun sonunda [creature] rastgele bir yöne hareket eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] moves, it leaves a trail of Embers. [define:arackulele.inscryption.grimoramod_Flames]", "[creature] her hareket ettiğinde ardında Kor bırakır. [define:arackulele.inscryption.grimoramod_Flames]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guarding Presence", "Koruyucu Varlık", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space.", "Bir rakip yaratığı boş bir yuvanın karşısına yerleştirildiğinde [creature] o boş yuvaya hareket eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Starved", "Kemik Açlığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no Bones, at the start of your turn [creature] deals 2 more damage.", "Turunun başında hiç kemiğin yoksa [creature] 2 ek hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space. If only one creature is in the opposing spaces, this card will strike that creature twice. ", "[creature] karşı taraftaki her yuvaya saldırır. Bu yuvalarda yalnızca bir yaratık varsa bu kart o yaratığa iki kez saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Giant", "Öfkeli Dev", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space.", "[creature] karşı taraftaki her yuvaya saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fledgling", "Tecrübesiz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After one turn on the board, [creature] will evolve into a greater form.", "[creature] oyun tahtasında bir tur geçirdikten sonra daha güçlü bir biçime evrilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Ability", "Rastgele Yetenek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced with another sigil at random.", "[creature] çekildiğinde bu mühür rastgele başka bir mühürle değiştirilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it haunts the space it died in. The first creature played on this space gain its old sigils.", "[creature] öldüğünde öldüğü yuvaya musallat olur. Bu yuvaya oynanan ilk yaratık onun eski mühürlerini kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunting Call", "Hayalet Çağrısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn [creature] is on the Board, it will take a Bone from you, if you have no Bones, it perishes.", "[creature] oyun tahtasında kaldığı her tur senden bir kemik alır. Hiç kemiğin yoksa ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature in the opposing slot is dragged onto the owner's side of the board.", "[creature] öldüğünde karşısındaki yuvada bulunan yaratık, oyun tahtasında onun sahibinin tarafına sürüklenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle ally card perishes, [creature] gains 1 power.", "Narin olmayan bir dost kartı öldüğünde [creature] 1 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slot as if the board was flipped. A card in the far left slot will attack the opposing far right slot.", "[creature] oyun tahtası ters çevrilmiş gibi rakip yuvasına saldırır. En soldaki yuvada bulunan kart, rakibin en sağdaki yuvasına saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Bonedigger sigil.", "[creature] öldüğünde sahibi, Kemik Kazıcı mührünü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Waterborne sigil.", "[creature] öldüğünde sahibi, Suda Süzülen mührünü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 health per turn. When [creature] dies, the creature opposing it, as well as adjacent friendly creatures, are dealt 10 damage.", "[creature] her tur 1 can kaybeder. [creature] öldüğünde karşısındaki yaratık ve bitişiğindeki dost yaratıklar 10 hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a severed limb is created in its place and this card moves into an adjacent open slot.", "[creature] darbe almak üzereyken yerinde kopmuş bir uzuv oluşturulur ve bu kart bitişiğindeki boş bir yuvaya hareket eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time [creature] deals damage directly, it loses 1 power and health.", "[creature] her doğrudan hasar verdiğinde gücü ve canı 1 azalır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, also play the cards in your hand that were adjacent to this card for free.", "[creature] oynandığında elinde bu kartın bitişiğinde bulunan kartlar da bedelsiz oynanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Douse", "Söndür", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played,[creature] will extinguish all cards on the Board.", "[creature] oynandığında oyun tahtasındaki tüm kartları söndürür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be attacked from the opposing slot. The opposing slot, if possible, instead attacks one of its adjacent friendly cards.", "[creature] tam karşısındaki yuvadan saldırı alamaz. O yuvadaki kart mümkünse kendi bitişiğindeki dost kartlardan birine saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards on the owner's side of the field are unaffected by Brittle.", "Oyun tahtasında sahibinin tarafındaki kartlar Narin etkisinden etkilenmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, except other Raiders.", "[creature], diğer Yağmacılar hariç bitişiğindeki yuvalara saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it carves its Sigils into adjacent Cards.", "[creature] oynandığında mühürlerini bitişiğindeki kartlara işler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sculptor", "Heykeltıraş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attempt to find a host in an adjacent friendly slot, hiding under it providing a +1/+1 buff. Cards on the left take priority.", "[creature], bitişiğindeki dost yuvalarda bir konak bulmaya çalışır; altına saklanarak ona +1/+1 verir. Soldaki kartlar önceliklidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] hits an opposing card, one of the targets adjacent allies will take damage as well ", "[creature] bir rakip kartına vurduğunda hedefin bitişiğindeki dostlarından biri de hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it provides an energy soul to its owner.", "[creature] oynandığında sahibine bir enerji ruhu verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HellHound's Thirst", "Cehennem Köpeğinin Susuzluğu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for each bone the player currently has.", "Bu mührü taşıyan kart, oyuncunun elindeki her kemik için 1 saldırı kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrath Of Halloween", "Cadılar Bayramı Gazabı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil has 10 attack, 1 for each Candy Bucket Sawyer has left.", "Bu mührü taşıyan kartın 10 saldırısı vardır; Sawyer'ın kalan her Şeker Kovası için 1.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trusty ol' Crew", "Sadık Eski Tayfa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every pirate on the board.", "Bu mührü taşıyan kart, oyun tahtasındaki her korsan için 1 saldırı kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inanimate Attack", "Cansız Saldırı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every card that has 0 attack on the board.", "Bu mührü taşıyan kart, oyun tahtasındaki 0 saldırılı her kart için 1 saldırı kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Bones", "Yarım Kemik", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Bones that the owner has on their side of the table.", "Bu mührün gösterdiği değer, sahibinin masanın kendi tarafında bulunan kemik sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "Çifte Ölüm", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to add power to [creature] randomly between 1 and 6.", "1 ruh ödeyerek [creature] adlı kartın gücünü 1 ile 6 arasında rastgele bir miktarda artır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to heal [creature] to max health.", "2 kemik ödeyerek [creature] adlı kartın canını tamamen iyileştir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Strike", "Dönüşümlü Darbe", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchored", "Demir Atmış", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Area Of Effect Strike", "Alan Darbesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Kan Bağımlısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Kemiksiz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Thief", "Kemik Hırsızı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "Ödül", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "Yanıyor", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Damage at the end of your turn, when it gets attacked by another Card, that card gets set on fire.", "[creature] senin turunun sonunda 1 hasar alır. Başka bir kart ona saldırdığında saldıran kart ateşe verilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "Kaos Vuruşu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold Front", "Soğuk Cephe", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "Koleksiyoncu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "Dengesiz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Strafe", "Alevli İlerleyiş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Strike", "Dev Darbesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "Musallat", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "Olta, Misina ve Kurşun", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbued", "Özle Dolu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inverted Strike", "Ters Darbe", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Bone Digger", "Kemik Kazıcı Mandalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Submerge", "Dalış Mandalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lit Fuse", "Yanan Fitil", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loose Limb", "Kopuk Uzuv", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malnourishment", "Yetersiz Beslenme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marching Dead", "Ölülerin Yürüyüşü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessive", "Sahiplenici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "Kuklacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raider", "Yağmacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Crawler", "Deri Sürüngeni", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slasher", "Biçici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spirit Bearer", "Ruh Taşıyıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of this card is equal to the number of Green Gems that the owner has on their side of the table.", "Bu kartın gücü, sahibinin masanın kendi tarafındaki Yeşil Cevher sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - ABILITIES {0}", "EK XII, ALT BÖLÜM I - YETENEKLER {0}", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - VARIABLE STATS {0}", "EK XII, ALT BÖLÜM II - DEĞİŞKEN NİTELİKLER {0}", Language.Turkish);

            // Card
            RegisterCard("Skeleton", "İskelet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The puppet becomes the puppeteer, yet still forever cursed by their dangling restraints.", "Kukla, kuklacının yerini alır; yine de sarkan bağlarının lanetinden sonsuza dek kurtulamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Kuklacı", Language.Turkish);
            RegisterCard("Animator", "Kuklacı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formless Creature, that yet lingers. Truly a horrific sight.", "Hâlâ buralarda dolaşan biçimsiz bir yaratık. Gerçekten korkunç bir manzara.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apparition", "Hayalet", Language.Turkish);
            RegisterCard("Apparition", "Hayalet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a fool would need such assistance.", "Ancak bir aptalın böyle bir yardıma ihtiyacı olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graven Ashes", "Oyulmuş Küller", Language.Turkish);
            RegisterCard("Graven Ashes", "Oyulmuş Küller");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's foul breath doesn't concern me, it's the Tampered Coffins it leaves behind!", "Beni endişelendiren pis nefesi değil, ardında bıraktığı Kurcalanmış Tabutlar!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bal-Bal", "Bal-Bal", Language.Turkish);
            RegisterCard("Bal-Bal", "Bal-Bal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SCREAMING TERROR. THEY GO STRAIGHT THROUGH TO ATTACK THEIR PREY.", "ÇIĞLIK ATAN DEHŞET. AVLARINA SALDIRMAK İÇİN SAVUNMALARIN İÇİNDEN GEÇERLER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banshee", "Ölüm Perisi", Language.Turkish);
            RegisterCard("Banshee", "Ölüm Perisi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bartender", "Barmen", Language.Turkish);
            RegisterCard("The Bartender", "Barmen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "spent his days serving harmful cocktails for those deserving of his poisonous wrath. Doesn't regret it at all.", "Günlerini, zehirli gazabını hak edenlere zararlı kokteyller sunarak geçirdi. Hiç pişman değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bones", "Büyük Kemikler", Language.Turkish);
            RegisterCard("Big Bones", "Büyük Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burly Bones", "Gürbüz Kemikler", Language.Turkish);
            RegisterCard("Burly Bones", "Gürbüz Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beefy Bones", "İri Kemikler", Language.Turkish);
            RegisterCard("Beefy Bones", "İri Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cal C. Um", "Bay Kalsiyum", Language.Turkish);
            RegisterCard("Cal C. Um", "Bay Kalsiyum");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sizeable Bones", "İri Kemikler", Language.Turkish);
            RegisterCard("Sizeable Bones", "İri Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Considerable Bones", "Muazzam Kemikler", Language.Turkish);
            RegisterCard("Considerable Bones", "Muazzam Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigorous Bones", "Dinç Kemikler", Language.Turkish);
            RegisterCard("Vigorous Bones", "Dinç Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hefty Bones", "Ağır Kemikler", Language.Turkish);
            RegisterCard("Hefty Bones", "Ağır Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RATHER BURLY SKELETON, IT IS VERY RICH IN CALCIUM.", "OLDUKÇA İRİYARI BİR İSKELET. KALSİYUM AÇISINDAN ÇOK ZENGİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sack is full of body parts. Maybe you'll find something useful in there.", "Bu çuval vücut parçalarıyla dolu. Belki içinde işine yarayacak bir şey bulursun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Kanlı Çuval", Language.Turkish);
            RegisterCard("Bloody Sack", "Kanlı Çuval");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Collective", "Kemik Topluluğu", Language.Turkish);
            RegisterCard("Bone Collective", "Kemik Topluluğu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUSANDS OF TINY BONES COALESCE INTO A HUMANOID FORM ONLY TO DISPERSE IN A CLATTERING SWARM THE NEXT MOMENT.", "BİNLERCE KÜÇÜK KEMİK İNSANSI BİR BİÇİMDE BİRLEŞİR, ANCAK BİR SONRAKİ ANDA TAKIRDAYAN BİR SÜRÜ HÂLİNDE DAĞILIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "USED TO BE A VERY LOYAL DOG BACK IN THE DAY. WELL, ONE DAY HIS OWNER DIED.", "ESKİDEN ÇOK SADIK BİR KÖPEKTİ. AMA BİR GÜN SAHİBİ ÖLDÜ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonehound", "Kemiktazı", Language.Turkish);
            RegisterCard("Bonehound", "Kemiktazı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO YOU HAVE MADE IT HERE, YOU CANNOT END WHAT I HAVE STARTED, IT HAS GONE TOO FAR.", "DEMEK BURAYA KADAR GELDİN. BAŞLATTIĞIM ŞEYİ BİTİREMEZSİN. ARTIK ÇOK GEÇ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord", "Kemiklerin Efendisi", Language.Turkish);
            RegisterCard("The Bonelord", "Kemiklerin Efendisi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD SHEDS ITS OLD HORNS, THEY TAKE ON A LIFE OF THEIR OWN, TO ONE DAY USURP THEIR MASTER.", "KEMİKLERİN EFENDİSİ ESKİ BOYNUZLARINI DÖKER. BOYNUZLAR BİR GÜN EFENDİLERİNİN YERİNİ ALMAK ÜZERE KENDİ HAYATLARINA BAŞLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelord's Horn", "Kemik Efendisi'nin Borusu", Language.Turkish);
            RegisterCard("Bonelord's Horn", "Kemik Efendisi'nin Borusu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT PARTICULARLY INSPIRING. YOU CAN HAVE IT.", "PEK İLHAM VERİCİ DEĞİL. ALABİLİRSİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap", "Kemik Yığını", Language.Turkish);
            RegisterCard("Bone Heap", "Kemik Yığını");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IF I AM TRAPPED, SO WILL YOU. YOU CANNOT END THIS.", "BEN TUTSAKSAM SEN DE OLACAKSIN. BUNA SON VEREMEZSİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Prince", "Kemik Prensi", Language.Turkish);
            RegisterCard("Bone Prince", "Kemik Prensi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE FEEDS ON PEOPLES BREATH, MAYBE ONE IS STANDING RIGHT BEHIND YOU RIGHT NOW.", "İNSANLARIN NEFESİYLE BESLENİR. BELKİ DE ŞU ANDA BİRİ HEMEN ARKANDA DURUYORDUR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boo Hag", "Hortlak Cadı", Language.Turkish);
            RegisterCard("Boo Hag", "Hortlak Cadı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE COMMANDS OTHERS WITH STRENGTH AND GLAMOUR. THEY WILL FOLLOW HER EVERYWHERE.", "BAŞKALARINI GÜCÜ VE CAZİBESİYLE YÖNETİR. ONU HER YERE TAKİP EDERLER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calavera Catrina", "Calavera Catrina", Language.Turkish);
            RegisterCard("Calavera Catrina", "Calavera Catrina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GROUP OF SKELETONS IS CALLED A CATACOMB. THIS IS A RATHER LARGE GATHERING.", "BİR İSKELET TOPLULUĞUNA YERALTI MEZARLIĞI DENİR. BU OLDUKÇA BÜYÜK BİR TOPLANTI.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catacomb", "Yeraltı Mezarlığı", Language.Turkish);
            RegisterCard("Catacomb", "Yeraltı Mezarlığı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centurion", "Yüzbaşı", Language.Turkish);
            RegisterCard("Centurion", "Yüzbaşı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavily armoured warrior. Last of his century, leader to none.", "Ağır zırhlı bir savaşçı. Yüz kişilik birliğinin son üyesi; yöneteceği kimse kalmamış.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compound Fracture", "Açık Kırık", Language.Turkish);
            RegisterCard("Compound Fracture", "Açık Kırık");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CRUSHED BY THE ROOF OF HIS OWN HOUSE. LIVING ON AS A PILE OF GOO.", "KENDİ EVİNİN ÇATISI ALTINDA EZİLDİ. BİR BALÇIK YIĞINI OLARAK YAŞAMAYA DEVAM EDİYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SPIRIT THAT TAKES THE FORM OF AN EGG. ITS PRESENCE HARMS THOSE THAT GAZE UPON IT.", "YUMURTA BİÇİMİNE BÜRÜNEN BİR RUH. VARLIĞI, ONA BAKANLARA ZARAR VERİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dalgyal", "Dalgyal", Language.Turkish);
            RegisterCard("Dalgyal", "Dalgyal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOREVER BOUND TOGETHER BY A TERRIBLE CURSE, THIS GROUP DANCES ONWARD INTO DOOM.", "KORKUNÇ BİR LANETLE SONSUZA DEK BİRBİRİNE BAĞLANAN BU GRUP, DANS EDEREK FELAKETE İLERLİYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danse Macabre", "Ölüm Dansı", Language.Turkish);
            RegisterCard("Danse Macabre", "Ölüm Dansı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadeye", "Ölügöz", Language.Turkish);
            RegisterCard("Deadeye", "Ölügöz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS EYE ONCE BELONGED TO AN ANCIENT GOD. IT GAZES UPON YOUR ARMY, PICKING ITS FAVORITE TO AID IT ON THE BATTLEFIELD.", "BU GÖZÜN BİR ZAMANLAR KADİM BİR TANRIYA AİT OLDUĞU SÖYLENİR. ORDUNA BAKAR VE SAVAŞ ALANINDA YARDIM ETMEK ÜZERE EN SEVDİĞİNİ SEÇER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS HAND ONCE BELONGED TO AN ANCIENT GOD. ANYTHING IT TOUCHES ROTS. AS WITH ANYTHING THAT ENDS, IT IS ALSO A NEW BEGINNING.", "BU ELİN BİR ZAMANLAR KADİM BİR TANRIYA AİT OLDUĞU SÖYLENİR. DOKUNDUĞU HER ŞEY ÇÜRÜR. SONA EREN HER ŞEY GİBİ BU DA YENİ BİR BAŞLANGIÇTIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Ölü El", Language.Turkish);
            RegisterCard("Dead Hand", "Ölü El");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DOOMED FATE SHOULD DISCOURAGE ONE FROM GOING ON, AT LEAST THATS WHAT A STILL LIVING MAN WOULD TELL YOU.", "KÖTÜ BİR KADER İNSANI DEVAM ETMEKTEN VAZGEÇİRMELİDİR. EN AZINDAN HÂLÂ YAŞAYAN BİRİ SANA BÖYLE DERDİ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Man Walking", "Yürüyen Ölü", Language.Turkish);
            RegisterCard("Dead Man Walking", "Yürüyen Ölü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAMED AMONG THE FOLLOWERS OF THE PHARAOH. THEY WERE BLESSED WITH ETERNAL LIFE LONG AGO.", "FİRAVUNUN TAKİPÇİLERİ ARASINDA ÜNLÜDÜRLER. UZUN ZAMAN ÖNCE SONSUZ YAŞAMLA KUTSANDILAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharaoh's Pets", "Firavun Hayvanları", Language.Turkish);
            RegisterCard("Pharaoh's Pets", "Firavun Hayvanları");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR WHOM THE BELL TOLLS? FOR WHOM THE TAP DRIPS DRY AND THE BATHWATER RUNS COLD.", "ÇANLAR KİMİN İÇİN ÇALIYOR? MUSLUĞU KURUYUP BANYO SUYU SOĞUYAN KİŞİ İÇİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knell", "Ölüm Çanı", Language.Turkish);
            RegisterCard("Death Knell", "Ölüm Çanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime", "Çan", Language.Turkish);
            RegisterCard("Chime", "Çan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This lonesome doll was returned from seas of slate and silent shores... it stares lifelessly.", "Bu yalnız oyuncak bebek, kurşuni denizlerden ve sessiz kıyılardan geri döndü... cansızca bakıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doll", "Bebek", Language.Turkish);
            RegisterCard("Doll", "Bebek");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIDING IN A SUIT OF ARMOR, OR ICE, WHAT DOES IT MATTER. THIS SKELETON WON'T LAST FOREVER.", "ZIRHIN İÇİNE SAKLANMIŞ, BUZUN İÇİNE SAKLANMIŞ; NE FARK EDER? BU İSKELET SONSUZA DEK DAYANMAYACAK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draugr", "Draugr", Language.Turkish);
            RegisterCard("Draugr", "Draugr");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SAD SIGHT, NO ONE SHALL KNOW WHAT LIES AT THE BOTTOM OF THAT WELL.", "NE ACI BİR MANZARA. O KUYUNUN DİBİNDE NE YATTIĞINI KİMSE BİLEMEYECEK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drowned Soul", "Boğulmuş Ruh", Language.Turkish);
            RegisterCard("Drowned Soul", "Boğulmuş Ruh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO ONE KNOWS WHAT EXACTLY THE DYBBUK IS, SOME SAY IT IS BETTER LEFT UNKNOWN.", "DİBUK'UN TAM OLARAK NE OLDUĞUNU KİMSE BİLMİYOR. BAZILARI BİLMEMENİN DAHA İYİ OLDUĞUNU SÖYLÜYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dybbuk", "Dibuk", Language.Turkish);
            RegisterCard("Dybbuk", "Dibuk");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ectoplasm", "Ektoplazma", Language.Turkish);
            RegisterCard("Ectoplasm", "Ektoplazma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE ESSENCE OF A SPIRIT, HIDDEN IN EVERY CORNER AND EVERY SHADOW. ONCE YOU SEE ONE, YOU WILL FIND THE REST SOON ENOUGH.", "BİR RUHUN ÖZÜ; HER KÖŞEDE, HER GÖLGEDE GİZLİDİR. BİRİNİ GÖRDÜĞÜNDE DİĞERLERİNİ DE ÇOK GEÇMEDEN BULURSUN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LIVING FAILURE, ITS KNOWLEDGE ONLY BROUGHT IT DEATH, OR AT LEAST AN APPROXIMATION OF IT.", "YAŞAYAN BİR BAŞARISIZLIK. BİLGİSİ ONA YALNIZCA ÖLÜMÜ, YA DA EN AZINDAN ONA BENZEYEN BİR ŞEYİ GETİRDİ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneclaw", "Kemik Pençesi", Language.Turkish);
            RegisterCard("Boneclaw", "Kemik Pençesi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Kemiksiz", Language.Turkish);
            RegisterCard("Boneless", "Kemiksiz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's Skeleton seems to have left this lifeless husk in order to achieve greater things.", "İskeleti, daha büyük işler başarmak için bu cansız kabuğu terk etmiş gibi görünüyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mummy", "Küçük Mumya", Language.Turkish);
            RegisterCard("Lesser Mummy", "Küçük Mumya");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal servant to the Pharao, buried with him to serve eternally in death.", "Firavunun sadık bir hizmetkârı. Ölümde de sonsuza dek hizmet etsin diye onunla birlikte gömüldü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eidolon", "Eidolon", Language.Turkish);
            RegisterCard("Eidolon", "Eidolon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GOLEM ENCHANTED LONG AGO, BOUND TO PROTECT THE AGE OF SUN.", "UZUN ZAMAN ÖNCE BÜYÜLENMİŞ, GÜNEŞ ÇAĞI'NI KORUMAKLA YÜKÜMLÜ BİR GOLEM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "QUITE A MISCHIEVOUS SPIRIT, IT SPREADS ITS FLAMES TO CAUSE DISMAY.", "OLDUKÇA YARAMAZ BİR RUH. DEHŞET SAÇMAK İÇİN ALEVLERİNİ YAYAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ember Spirit", "Kor Ruhu", Language.Turkish);
            RegisterCard("Ember Spirit", "Kor Ruhu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMILY WISHES TO REST IN PEACE, ONLY TO BE SUMMONED AGAIN AND AGAIN IN AN ETERNAL BATTLE.", "AİLE HUZUR İÇİNDE YATMAK İSTER, AMA SONSUZ BİR SAVAŞA TEKRAR TEKRAR ÇAĞRILIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Walkers", "Zombigiller", Language.Turkish);
            RegisterCard("The Walkers", "Zombigiller");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said their odor is so strong and repugnant, even the undead can feel it!", "Kokularının o kadar ağır ve iğrenç olduğu söylenir ki yaşayan ölüler bile hissedebilir!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Festering Wretch", "İrinli Sefil", Language.Turkish);
            RegisterCard("Festering Wretch", "İrinli Sefil");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flames", "Alevler", Language.Turkish);
            RegisterCard("Flames", "Alevler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flameskull", "Alevli Kafatası", Language.Turkish);
            RegisterCard("Flameskull", "Alevli Kafatası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always flying, always angry, always annoying nearby allies in the process.", "Hep uçar, hep öfkelidir ve bu sırada yakınındaki dostları hep rahatsız eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A waterlogged sailor who carries his tragic past beside him. I don't remember the details.", "Trajik geçmişini yanında taşıyan, suya doymuş bir denizci. Ayrıntıları hatırlamıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten Man", "Unutulmuş Adam", Language.Turkish);
            RegisterCard("Forgotten Man", "Unutulmuş Adam");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEST FRIENDS, BROTHERS, AND FIGHTERS.", "CAN DOSTLARI, KARDEŞLER VE SAVAŞÇILAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frank & Stein", "Frank & Stein", Language.Turkish);
            RegisterCard("Frank & Stein", "Frank & Stein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FrankenStein", "Frankenstein", Language.Turkish);
            RegisterCard("FrankenStein", "Frankenstein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghastly guardian spirit. It's presence lingers behind as it sprints through the dark.", "Ürkütücü bir koruyucu ruh. Karanlığın içinden hızla geçerken varlığı ardında kalır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fylgja", "Fylgja", Language.Turkish);
            RegisterCard("Fylgja", "Fylgja");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warding Presence", "Koruyucu Varlık", Language.Turkish);
            RegisterCard("Warding Presence", "Koruyucu Varlık");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CREATED THESE BONES, WAR, FAMINE OR ANOTHER TRAGEDY? It may be insignificant now, but I fear what it might become...", "BU KEMİKLERİ NE YARATTI: SAVAŞ MI, KITLIK MI, BAŞKA BİR FELAKET Mİ? Şimdi önemsiz olabilir, ama neye dönüşeceğinden korkuyorum...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Toplu Mezar", Language.Turkish);
            RegisterCard("Mass Grave", "Toplu Mezar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rising Hunger", "Oburluk", Language.Turkish);
            RegisterCard("Rising Hunger", "Oburluk");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.Turkish);
            RegisterCard("Gashadokuro", "Gashadokuro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE PIRATES CALL THIS SHIP THEIR HOME, EVEN IN DEATH. A SLAIN GIANTS SKULL SERVES AS THEIR FIGUREHEAD.", "KORSANLAR ÖLÜMDE BİLE BU GEMİYE YUVA DERLER. ÖLDÜRÜLMÜŞ BİR DEVİN KAFATASI GEMİNİN BAŞ SÜSÜDÜR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Ship", "Hayalet Gemi", Language.Turkish);
            RegisterCard("Ghost Ship", "Hayalet Gemi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "Dev", Language.Turkish);
            RegisterCard("Giant", "Dev");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMED RACE OF GIANTS IS SAID TO HAVE DIED OUT LONG AGO, THIS IS PROOF. TRULY A SIGHT TO BEHOLD.", "ÜNLÜ DEV IRKININ UZUN ZAMAN ÖNCE TÜKENDİĞİ SÖYLENİR. İŞTE KANITI. GERÇEKTEN GÖRÜLMEYE DEĞER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOUND TO EARTH, THEY CLING ON SO THEY MAY ONE DAY GET PROPER BURIAL.", "DÜNYAYA BAĞLIDIRLAR; BİR GÜN USULÜNCE GÖMÜLEBİLMEK İÇİN TUTUNMAYA DEVAM EDERLER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grateful Dead", "Minnettar Ölü", Language.Turkish);
            RegisterCard("Grateful Dead", "Minnettar Ölü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LOWLY GRAVEBARD, MUSIC ALWAYS BROUGHT HIM COMFORT IN THE WORST OF TIMES. NOW, EVEN AT THE END OF THE WORLD HE SHARES HIS SONG.", "MÜTEVAZI MEZAR OZANI. MÜZİK, EN KÖTÜ ZAMANLARDA ONU HEP TESELLİ ETTİ. ŞİMDİ DÜNYANIN SONUNDA BİLE ŞARKISINI PAYLAŞIYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravebard", "Mezar Ozanı", Language.Turkish);
            RegisterCard("Gravebard", "Mezar Ozanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT HIS LIFE CARVING THESE CREATURES, THIS CARD CONTAINS A PART OF HIS SOUL.", "HAYATINI BU YARATIKLARI OYARAK GEÇİRDİ. BU KART ONUN RUHUNUN BİR PARÇASINI TAŞIYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Carver", "Mezar Oymacısı", Language.Turkish);
            RegisterCard("Grave Carver", "Mezar Oymacısı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE SPENDS HIS TIME ALONE DIGGING FOR BONES IN HOPES OF FINDING A TREASURE. JUST LIKE HIS GRANDMA BEFORE HIM.", "VAKTİNİ, HAZİNE BULMA UMUDUYLA TEK BAŞINA KEMİK KAZARAK GEÇİRİR. TIPKI ONDAN ÖNCE BÜYÜKANNESİNİN YAPTIĞI GİBİ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravedigger", "Mezarcı", Language.Turkish);
            RegisterCard("Gravedigger", "Mezarcı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A POOR, BRUTALIZED SOUL. THEIR MYCELIA PROBES FAR INTO THE SOIL, GUIDING THEIR SPADE.", "ZAVALLI, HIRPALANMIŞ BİR RUH. MİSELLERİ TOPRAĞIN DERİNLERİNE UZANARAK KÜREĞİNE YOL GÖSTERİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporedigger", "Mantar Kazan", Language.Turkish);
            RegisterCard("Sporedigger", "Mantar Kazan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A devoted guardian spirit. Even when dispelled, it grants a protective blessing.", "Kendini adamış bir koruyucu ruh. Dağıtıldığında bile koruyucu bir kutsama bahşeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haltia", "Haltia", Language.Turkish);
            RegisterCard("Haltia", "Haltia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I advise against staring into it, you won't like what stares back.", "İçine bakmamanı öneririm. Sana geri bakan şeyi sevmeyeceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Mirror", "Perili Ayna", Language.Turkish);
            RegisterCard("Haunted Mirror", "Perili Ayna");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY CALL HER THE RIDER OF THE APOCALYPSE. HER FLAMING BLADE CUTS THROUGH THE LIVING AND DEAD ALIKE.", "ONA KIYAMETİN SÜVARİSİ DERLER. ALEVLER İÇİNDEKİ KILICI YAŞAYANI DA ÖLÜYÜ DE KESER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Horseman", "Başsız Süvari", Language.Turkish);
            RegisterCard("Headless Horseman", "Başsız Süvari");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WOULDN'T GET TOO CLOSE DEAR. YOU CAN'T BREAK THE HOLD FROM THE DEEPEST PITS OF HELL, ONCE IT LATCHES ON.", "BEN OLSAM ÇOK YAKLAŞMAZDIM CANIM. CEHENNEMİN EN DERİN ÇUKURLARINDAN UZANAN PENÇEYE BİR KEZ YAKALANDIN MI KURTULAMAZSIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhand", "Cehennem Eli", Language.Turkish);
            RegisterCard("Hellhand", "Cehennem Eli");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Hound", "Cehennem Tazısı", Language.Turkish);
            RegisterCard("Hell Hound", "Cehennem Tazısı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RABID DOG. IT KILLED ONE OF MY GHOULS.", "KUDUZ BİR KÖPEK. GULYABANİLERİMDEN BİRİNİ ÖLDÜRDÜ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LEGENDS HAVE BEEN TOLD ABOUT THE LEGENDARY HYDRA, THE BEAST THAT SWALLOWS ALL AND THE BANE OF ALL THAT SAIL THE SEAS.", "EFSANEVİ HİDRA HAKKINDA EFSANELER ANLATILIR: HER ŞEYİ YUTAN CANAVAR, DENİZLERE AÇILAN HERKESİN BELASIDIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydra", "Hidra", Language.Turkish);
            RegisterCard("Hydra", "Hidra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overtaken by it's gluttony in life, doomed to it's gluttony in death. Oddly inspires a greed for bones.", "Hayattayken oburluğuna yenildi, ölümde de oburluğa mahkûm oldu. Tuhaf biçimde kemik açgözlülüğü uyandırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jikininki", "Jikininki", Language.Turkish);
            RegisterCard("Jikininki", "Jikininki");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "Çığ", Language.Turkish);
            RegisterCard("Avalanche", "Çığ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Buzul", Language.Turkish);
            RegisterCard("Glacier", "Buzul");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WONDER WHAT HAS BEEN FROZEN AWAY FOR SO LONG.", "BU KADAR UZUN SÜREDİR NEYİN DONMUŞ OLDUĞUNU MERAK EDİYORUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Giant", "Buz Devi", Language.Turkish);
            RegisterCard("Frost Giant", "Buz Devi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "Buz Küpü", Language.Turkish);
            RegisterCard("Ice Cube", "Buz Küpü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CORPSE WHO DIED WITH HIS HEAD IN A GLACIAL STREAM. AFTER HIS REANIMATION, HE COULDN'T BEAR TO PART WITH THE ICE THAT HAD FORMED.", "BAŞI BUZUL DEREDEYKEN ÖLEN BİR CESET. YENİDEN CANLANDIĞINDA OLUŞAN BUZDAN AYRILMAYA DAYANAMADI.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After drowning her children and then herself, she continues to drown others.", "Çocuklarını, ardından da kendini boğduktan sonra başkalarını boğmaya devam ediyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La Llorona", "La Llorona", Language.Turkish);
            RegisterCard("La Llorona", "La Llorona");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manananggal", "Manananggal", Language.Turkish);
            RegisterCard("Manananggal", "Manananggal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO BRUTALITY SATIATES THE MANANANGGAL. WHEN YOU SEE HER SEVER FROM HER TORSO, YOU TOO WILL BE A VICTIM OF THE HUNT.", "HİÇBİR VAHŞET MANANANGGAL'I DOYURMAZ. GÖVDESİNDEN AYRILDIĞINI GÖRDÜĞÜNDE SEN DE AVIN KURBANI OLACAKSIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi, also known as the hairy ghost. It leeches the souls from those struck down near it.", "Tüylü hayalet olarak da bilinen Moroi. Yakınında öldürülenlerin ruhlarını emer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi", "Moroi", Language.Turkish);
            RegisterCard("Moroi", "Moroi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS AGE OF GLORY IS LONG GONE, YET IT IS WHAT KEEPS HIM GOING.", "ŞANLI GÜNLERİ ÇOKTAN GERİDE KALDI, AMA ONU AYAKTA TUTAN DA BU.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy Lord", "Mumya Lordu", Language.Turkish);
            RegisterCard("Mummy Lord", "Mumya Lordu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL EFFORTS TO PRESERVE LIFE AFTER DEATH HAVE BEEN FUTILE, YET THE NECROMANCER GOES ON. HE HAS TO.", "ÖLÜMDEN SONRA YAŞAMI SÜRDÜRMEYE YÖNELİK TÜM ÇABALAR BOŞA ÇIKTI, AMA NEKROMANSER DEVAM EDİYOR. ETMEK ZORUNDA.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necromancer", "Ölü Dirilten", Language.Turkish);
            RegisterCard("Necromancer", "Ölü Dirilten");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A troublesome lake spirit that enjoys dragging others down to a watery grave.", "Başkalarını su altındaki mezarlarına sürüklemekten hoşlanan, baş belası bir göl ruhu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nixie", "Su Perisi", Language.Turkish);
            RegisterCard("Nixie", "Su Perisi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shambling corpse of a pale, sickly noble. it spreads it's filth as it sheds it's flesh.", "Solgun, hastalıklı bir soylunun sendeleyen cesedi. Eti döküldükçe pisliğini yayar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferat", "Nosferat", Language.Turkish);
            RegisterCard("Nosferat", "Nosferat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Obol", "Kadim Obol", Language.Turkish);
            RegisterCard("Ancient Obol", "Kadim Obol");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WILL ALL MAKE SENSE SOON. THE OBOL IS OLDER THAN TIME ITSELF, AND THUS IT WILL REVEAL ITSELF IN DUE TIME.", "YAKINDA HER ŞEY ANLAM KAZANACAK. OBOL ZAMANIN KENDİSİNDEN DAHA ESKİDİR; BU YÜZDEN VAKTİ GELDİĞİNDE KENDİNİ GÖSTERECEKTİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Armed Bandit", "Tek Kollu Haydut", Language.Turkish);
            RegisterCard("One Armed Bandit", "Tek Kollu Haydut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Took the ten paces, that ordeal cost him an arm, and his life.", "On adımı attı. O çile ona bir kola ve hayatına mal oldu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS SAID ALL IS WELL THAT ENDS. IT IS SAID TIME IS LIKE AN OUROBOROS, IT DOES NOT END, IT ONLY REPEATS ITSELF.", "BİTEN HER ŞEY İYİDİR DERLER. ZAMANIN OUROBOROS GİBİ OLDUĞUNU SÖYLERLER; BİTMEZ, YALNIZCA KENDİNİ TEKRARLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobones", "Ourokemik", Language.Turkish);
            RegisterCard("Ourobones", "Ourokemik");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Veba Doktoru", Language.Turkish);
            RegisterCard("Plague Doctor", "Veba Doktoru");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS DETERMINED THE UNDEAD ARE SICK WITH A TERRIBLE ILLNESS. THE ONLY CURE IS DEATH.", "YAŞAYAN ÖLÜLERİN KORKUNÇ BİR HASTALIĞA YAKALANDIĞINA KARAR VERDİ. TEK TEDAVİ ÖLÜM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EVIL TRICKSTER, THE POLTERGEIST HAS ENJOYED THEIR DEATH VERY MUCH.", "KÖTÜ NİYETLİ BİR HİLEBAZ. POLTERGEIST KENDİ ÖLÜMÜNÜN TADINI DOYASIYA ÇIKARIYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poltergeist", "Poltergeist", Language.Turkish);
            RegisterCard("Poltergeist", "Poltergeist");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of ancient armour in which an occult spirit has taken up residence. Her iron fist drags more creatures to the fight.", "Gizemli bir ruhun yerleştiği kadim bir zırh. Demir yumruğuyla daha fazla yaratığı savaşa sürükler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Armour", "Ele Geçirilmiş Zırh", Language.Turkish);
            RegisterCard("Possessed Armour", "Ele Geçirilmiş Zırh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EXPERIMENT GONE WRONG, IN A FUTILE ATTEMPT TO CREATE A DANSE MACCABRE. THEY DO NOT FUNCTION TOGETHER.", "BİR ÖLÜM DANSI YARATMAYA YÖNELİK BOŞUNA BİR ÇABADA TERS GİDEN DENEY. BİRLİKTE İŞLEYEMİYORLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Project", "Deney Örneği", Language.Turkish);
            RegisterCard("Project", "Deney Örneği");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldnt be seeing this right now", "Bunu şu anda görmemen gerekiyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Cards", "Biçimsiz Yaratıklar", Language.Turkish);
            RegisterCard("Random Cards", "Biçimsiz Yaratıklar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT SEEKS ONLY REVENGE.", "ÖLÜMÜN TIRPANINI TAŞIYAN HAYALET YALNIZCA İNTİKAM PEŞİNDEDİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant", "Hayalet", Language.Turkish);
            RegisterCard("Revenant", "Hayalet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "Karındeşen", Language.Turkish);
            RegisterCard("Ripper", "Karındeşen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE RIPPER SOLVES EVERYTHING THROUGH SHEER STRENGTH. IT WILL PUNCH ANY ISSUE STRAIGHT IN THE FACE AND SOLVE IT, TOO.", "KARINDEŞEN HER ŞEYİ KABA KUVVETLE ÇÖZER. HER SORUNUN TAM SURATINA YUMRUĞU İNDİRİR VE ONU DA ÇÖZER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a wonder this one has stayed together! Though it may lose that arm if it tries to flee.", "Bunun hâlâ bir arada durması bir mucize! Ama kaçmaya çalışırsa o kolunu kaybedebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotten", "Çürük Ceset", Language.Turkish);
            RegisterCard("Rotten", "Çürük Ceset");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twitching Arm", "Seğiren Kol", Language.Turkish);
            RegisterCard("Twitching Arm", "Seğiren Kol");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The elusive Locker.", "Ele avuca sığmayan Dolap.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones Locker", "Davy Jones'un Sandığı", Language.Turkish);
            RegisterCard("Davy Jones Locker", "Davy Jones'un Sandığı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellowbeard", "Sarı Sakal", Language.Turkish);
            RegisterCard("Yellowbeard", "Sarı Sakal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebeard", "Mavi Sakal", Language.Turkish);
            RegisterCard("Bluebeard", "Mavi Sakal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His songs raise the morale of only Skeletons, as no one else seems to like it.", "Şarkıları yalnızca İskeletlerin moralini yükseltir; görünüşe göre başka kimse onlardan hoşlanmıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DISTANT RELATIVE OF THE SCREAMING SKULL, HE IS NOW THE SYMBOL OF PIRACY ALL AROUND THE WORLD", "ÇIĞLIK ATAN KAFATASI'NIN UZAK AKRABASI. ARTIK TÜM DÜNYADA KORSANLIĞIN SİMGESİ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "Çapraz Kemikler", Language.Turkish);
            RegisterCard("Crossbones", "Çapraz Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones", "Davy Jones", Language.Turkish);
            RegisterCard("Davy Jones", "Davy Jones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true captain of the crew, respected by all yet still elusive. YELLOWBEARD ALWAYS GETS MORE BOOTY THAN HE DOES.", "Tayfanın gerçek kaptanı; herkes ona saygı duyar, ama yine de ele avuca sığmaz. SARI SAKAL HER ZAMAN ONDAN DAHA FAZLA GANİMET ELDE EDER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MAYBE IT WASN'T THE BEST IDEA TO HOLD A BARREL FULL OF GUNPOWDER. I'M NOT SURE WETHER HE NOTICED.", "BARUT DOLU BİR FIÇIYI TUTMAK PEK İYİ BİR FİKİR OLMAYABİLİR. FARK ETTİĞİNDEN EMİN DEĞİLİM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Pirate", "Patlayıcı Korsan", Language.Turkish);
            RegisterCard("Exploding Pirate", "Patlayıcı Korsan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He betrayed his captain for that large hook, now he is sure to make anyone a double-crosser!", "O büyük kanca için kaptanına ihanet etti. Artık herkesi bir haine dönüştüreceğinden emin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Mate Snag", "İkinci Kaptan Snag", Language.Turkish);
            RegisterCard("First Mate Snag", "İkinci Kaptan Snag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrots usually make great sea-side companions, this one just ate a poisoned cracker.", "Papağanlar genellikle deniz kenarında harika yoldaşlardır. Bu ise az önce zehirli bir kraker yedi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Polly", "Polly", Language.Turkish);
            RegisterCard("Polly", "Polly");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A keen eye socket allows him to attack anywhere, his musket helps too. marvelous indeed!", "Keskin bir göz çukuru her yere saldırmasını sağlar; tüfeği de yardımcı olur. Gerçekten harika!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Privateer", "Korsan Kaptan", Language.Turkish);
            RegisterCard("Privateer", "Korsan Kaptan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swashbuckler", "Gözü Pek Silahşor", Language.Turkish);
            RegisterCard("Swashbuckler", "Gözü Pek Silahşor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMERGING FROM AN OLD EGYPTIAN TOMB, MADE TO HOUSE THE LORDS OF OLD.", "ESKİ HÜKÜMDARLARI BARINDIRMAK İÇİN YAPILMIŞ, KADİM BİR MISIR MEZARINDAN ÇIKIYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcophagus", "Lahit", Language.Turkish);
            RegisterCard("Sarcophagus", "Lahit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screaming Skull", "Çığlık Atan Kafatası", Language.Turkish);
            RegisterCard("Screaming Skull", "Çığlık Atan Kafatası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONLY PAIN AND SUFFERING, NOTHING ELSE IS FELT BY THIS SKELETAL HEAD. WHAT A PITY.", "BU İSKELET KAFASI ACI VE ISTIRAPTAN BAŞKA HİÇBİR ŞEY HİSSETMEZ. NE YAZIK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SKILLED HUNTER. DON'T TRUST YOUR EARS WHEN YOU HEAR ITS HAUNTING WHISTLE.", "YETENEKLİ BİR AVCI. ÜRKÜTÜCÜ ISLIĞINI DUYDUĞUNDA KULAKLARINA GÜVENME.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silbon", "El Silbón", Language.Turkish);
            RegisterCard("Silbon", "El Silbón");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY HAVE LEARNED THE ANCIENT SPELL OF DEATH. YET IT IS TOO MUCH POWER TO BE WIELDED.", "KADİM ÖLÜM BÜYÜSÜNÜ ÖĞRENDİLER. AMA BU, KULLANILAMAYACAK KADAR BÜYÜK BİR GÜÇ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Büyücü İskelet", Language.Turkish);
            RegisterCard("Skelemagus", "Büyücü İskelet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]RISE MY ARMY, RIIIIIISE[c:]", "[c:bR]YÜKSEL ORDUM, YÜKSEEEEEL![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Army", "İskelet Ordusu", Language.Turkish);
            RegisterCard("Skeleton Army", "İskelet Ordusu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the faster draws in the west, but not fast enough.", "Batı'nın en hızlı silah çekenlerinden biri, ama yeterince hızlı değilmiş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slinger's Soul", "Silahşorun Ruhu", Language.Turkish);
            RegisterCard("Slinger's Soul", "Silahşorun Ruhu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY SHOW UP OUT OF NOWHERE AND RELOCATE PEOPLE AS THEY PLEASE.", "YOKTAN VAR OLURLAR VE İNSANLARI DİLEDİKLERİ YERE TAŞIRLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluagh", "Sluagh", Language.Turkish);
            RegisterCard("Sluagh", "Sluagh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trick or treat!", "Şeker mi, şaka mı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Bucket", "Şeker Kovası", Language.Turkish);
            RegisterCard("Candy Bucket", "Şeker Kovası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAPPY HALLOWEEN!", "CADILAR BAYRAMIN KUTLU OLSUN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Monster", "Şeker Canavarı", Language.Turkish);
            RegisterCard("Candy Monster", "Şeker Canavarı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectrabbit", "Hayalet Tavşan", Language.Turkish);
            RegisterCard("Spectrabbit", "Hayalet Tavşan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SPECTRE EMITS A FLUTE LIKE CALL, AN OMEN OF BOTH DEATH AND DESCTRUCTION", "HORTLAK, FLÜTÜ ANDIRAN BİR SES ÇIKARIR; HEM ÖLÜMÜN HEM DE YIKIMIN HABERCİSİDİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectre", "Hortlak", Language.Turkish);
            RegisterCard("Spectre", "Hortlak");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH IS A CRUEL FATE. STARVATION AN EVEN CRUELER ONE. WHY DO YOU FIGHT, OH HUNGRY CHILD.", "ÖLÜM ACIMASIZ BİR KADERDİR. AÇLIKTAN ÖLMEK DAHA DA ACIMASIZDIR. NEDEN SAVAŞIYORSUN, EY AÇ ÇOCUK?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved Man", "Açlıktan Ölmüş Adam", Language.Turkish);
            RegisterCard("Starved Man", "Açlıktan Ölmüş Adam");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT YEARS IN HIS STUDY, IN A TIRELESS ATTEMPT TO CHANGE HIS FATE. YET FATE IS A CRUEL MISTRESS.", "KADERİNİ DEĞİŞTİRMEK İÇİN YILMADAN ÇABALAYARAK YILLARINI ÇALIŞMA ODASINDA GEÇİRDİ. AMA KADER ACIMASIZ BİR SEVGİLİDİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Çağırıcı", Language.Turkish);
            RegisterCard("Summoner", "Çağırıcı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tampered Coffin", "Kurcalanmış Tabut", Language.Turkish);
            RegisterCard("Tampered Coffin", "Kurcalanmış Tabut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Tree", "Ölü Ağaç", Language.Turkish);
            RegisterCard("Dead Tree", "Ölü Ağaç");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its low cost is justified only by its low stats.", "Düşük bedelini yalnızca düşük nitelikleri haklı çıkarıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Grave", "Rahatsız Edilmiş Mezar", Language.Turkish);
            RegisterCard("Disturbed Grave", "Rahatsız Edilmiş Mezar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LOWLY GRAVE. WHOEVER IS LAID TO REST HERE, I DO NOT KNOW.", "MÜTEVAZI BİR MEZAR. BURADA KİMİN YATTIĞINI BİLMİYORUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kennel", "Köpek Kulübesi", Language.Turkish);
            RegisterCard("Kennel", "Köpek Kulübesi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "Dikilitaş", Language.Turkish);
            RegisterCard("Obelisk", "Dikilitaş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck", "Gemi Enkazı", Language.Turkish);
            RegisterCard("Shipwreck", "Gemi Enkazı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flotsam", "Yüzen Enkaz", Language.Turkish);
            RegisterCard("Flotsam", "Yüzen Enkaz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Urn", "Su Vazosu", Language.Turkish);
            RegisterCard("Water Urn", "Su Vazosu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voodoo Doll", "Vudu Bebeği", Language.Turkish);
            RegisterCard("Voodoo Doll", "Vudu Bebeği");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOTHING... NOTHING AGAIN... NO TREASURE IS LEFT ANYMORE.", "HİÇBİR ŞEY... YİNE HİÇBİR ŞEY... ARTIK HİÇ HAZİNE KALMADI.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomb Robber", "Mezar Hırsızı", Language.Turkish);
            RegisterCard("Tomb Robber", "Mezar Hırsızı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ephialtes", "Efialtes", Language.Turkish);
            RegisterCard("Ephialtes", "Efialtes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Otis", "Otis", Language.Turkish);
            RegisterCard("Otis", "Otis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undertaker", "Cenazeci", Language.Turkish);
            RegisterCard("Undertaker", "Cenazeci");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His service no longer needed, this lost soul buries without purpose..", "Artık hizmetine ihtiyaç duyulmayan bu kayıp ruh amaçsızca gömmeye devam ediyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Coffin", "Yürüyen Tabut", Language.Turkish);
            RegisterCard("Walking Coffin", "Yürüyen Tabut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Coffin", "Koşan Tabut", Language.Turkish);
            RegisterCard("Running Coffin", "Koşan Tabut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placeholder", "Yer Tutucu", Language.Turkish);
            RegisterCard("Placeholder", "Yer Tutucu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE VAMPIRE IS A CREATURE OF LEGENDS. IN REALITY, LITTLE BLOOD TO DRINK AFTER EVERYONE HAS DIED.", "VAMPİR EFSANELERE AİT BİR YARATIKTIR. GERÇEKTEYSE HERKES ÖLDÜKTEN SONRA İÇECEK PEK KAN KALMAZ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampire", "Vampir Kont", Language.Turkish);
            RegisterCard("Vampire", "Vampir Kont");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vellum", "Parşömen", Language.Turkish);
            RegisterCard("Vellum", "Parşömen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO NEVER BE SATISFIED, TO ALWAYS WANT MORE. THIS SPIRIT SHALL NEVER FIND ITS PEACE.", "ASLA DOYMAMAK, HEP DAHA FAZLASINI İSTEMEK. BU RUH HİÇBİR ZAMAN HUZUR BULAMAYACAK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeful Spirit", "İntikamcı Ruh", Language.Turkish);
            RegisterCard("Vengeful Spirit", "İntikamcı Ruh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS GELID SPECTER ENVELOPS WOULD-BE ATTACKERS IN AN ICY MIST.", "BU BUZ GİBİ HAYALET, SALDIRMAYA KALKIŞANLARI DONDURUCU BİR SİSLE SARAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthr", "Ayaz Hayaleti", Language.Turkish);
            RegisterCard("Warthr", "Ayaz Hayaleti");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted by the spirit of a rabid wolf. It's fury cannot be stopped.", "Kuduz bir kurdun ruhuyla yozlaşmış. Öfkesi durdurulamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wechuge", "Wechuge", Language.Turkish);
            RegisterCard("Wechuge", "Wechuge");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hideous beings that will jump out to consume freshly killed corpses. They only spare the bones of the victim.", "Yeni öldürülmüş cesetleri yemek için ortaya atlayan iğrenç varlıklar. Kurbanın yalnızca kemiklerini bırakırlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wight", "Hortlamış Ceset", Language.Turkish);
            RegisterCard("Wight", "Hortlamış Ceset");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY WARM WITH THEIR BODIES OF LIGHT, DRAWING HOPELESS SOULS INTO THEIR BEACON, DISPELLING THEIR FRIGHT.", "IŞIKTAN BEDENLERİYLE ISITIR, UMUTSUZ RUHLARI IŞIKLARINA ÇEKER VE KORKULARINI DAĞITIRLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will 'O' The Wisp", "Bataklık Işığı", Language.Turkish);
            RegisterCard("Will 'O' The Wisp", "Bataklık Işığı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FALLEN GIANTS SPINE THAT IS TRYING TO FIND A NEW HOST. REGRETTABLY, MOST CREATURES ARE QUITE SMALL.", "YENİ BİR KONAK BULMAYA ÇALIŞAN, DÜŞMÜŞ BİR DEVİN OMURGASI. NE YAZIK Kİ ÇOĞU YARATIK OLDUKÇA KÜÇÜK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writher", "Kıvranıcı", Language.Turkish);
            RegisterCard("Writher", "Kıvranıcı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Vertebrae", "Dikenli Omurlar", Language.Turkish);
            RegisterCard("Spiny Vertebrae", "Dikenli Omurlar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SIMPLEST OF UNDEAD, CHARACTERIZED BY ITS ROTTEN SMELL. IT ALWAYS TRAVELS WITH OTHERS, SEEKING PROTECTION AND GUIDANCE.", "ÇÜRÜK KOKUSUYLA TANINAN EN BASİT YAŞAYAN ÖLÜ. KORUNMAK VE YOLUNU BULMAK İÇİN HEP BAŞKALARIYLA GEZER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie", "Zombi", Language.Turkish);
            RegisterCard("Zombie", "Zombi");

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora Mod Achievements", "Grimora Modu Başarımları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Reminder", "Korkunç Hatırlatma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Kaycee and thaw at least 5 of your cards.", "Kaycee'yi yen ve kartlarından en az 5 tanesini çöz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards End", "Korkağın Sonu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Sawyers second phase without hurting the hellhound.", "Cehennem Tazısı'na zarar vermeden Sawyer'ın ikinci aşamasını yen.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Season Of Storms", "Fırtına Mevsimi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Royal and have no cards walk the plank.", "Hiçbir kartı kalastan yürütmeden Royal'ı yen.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Black Bird//", "Kara Kuş//", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark Slope. Defeat [redacted] without defeating [redacted].", "Karanlık Yamaç. [redacted] adlı kişiyi yenmeden [redacted] adlı kişiyi yen.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonesaw", "Kemik Testeresi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End a turn with at least 30 bones.", "Bir turu en az 30 kemikle bitir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pile Of Skulls", "Kafatası Yığını", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win with all challenges enabled and no antichallenges enabled.", "Tüm meydan okumalar etkinken ve hiçbir ters meydan okuma etkin değilken kazan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance of Doom", "Felaket Dansı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness the end of everything.", "Her şeyin sonuna tanık ol.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spirits Way", "Ruhların Yolu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach 6 Souls by turn 3.", "3. tura kadar 6 ruha ulaş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wail Of The Damned", "Lanetlilerin Feryadı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the dead hand item when your deck is empty.", "Desten boşken Ölü El eşyasını kullan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something Ends...", "Bir Şey Biter...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Something Begins. Get an ourobones to deal 6 damage.", "...Bir Şey Başlar. Bir Ourokemik ile 6 hasar ver.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cull the weak", "Zayıfları Ele", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice an Obol with 5 sigils to the Bonelord.", "Kemiklerin Efendisi'ne 5 mühürlü bir Obol kurban et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gateway to Dis", "Dis'e Açılan Kapı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win while Hell mode is active.", "Cehennem modu etkinken kazan.", Language.Turkish);

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Horn", "Kemik Borusu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Horn, drains all of your current Soul but you gain a bone for each soul consumed.", "Kemik Borusu mevcut ruhlarının tamamını tüketir, ama tüketilen her ruh için bir kemik kazanırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives you a bone for each of your Souls, which are spent in the process, an unfortunate, but worthwhile sacrifice.", "Ruhlarının hepsini harcayarak her biri için bir kemik verir. Talihsiz, ama değerli bir fedakârlık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Ölü El", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dead Hand, draws you a new Hand of cards at the cost of your old one.", "Ölü El, eski elin pahasına sana yeni bir el kart çektirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The severed hand of a forgotten god, left to take on a life of its own. You know what this does.", "Unutulmuş bir tanrının kopmuş eli; kendi başına yaşamaya bırakılmış. Ne işe yaradığını biliyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embalming Fluid", "Mumyalama Sıvısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Embalming Fluid, pour it over a card and it will gain one health and attack.", "Mumyalama Sıvısı'nı bir kartın üzerine dök; kart bir can ve saldırı kazansın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare to put a member of your army to rest, increasing its stamina and vigor as you do so!", "Ordunun bir üyesini ebedî istirahate hazırlarken dayanıklılığını ve zindeliğini artır!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravecarvers Chisel", "Mezar Oymacısının Keskisi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravecarvers chisel, select any card that has died previously to add to your hand.", "Mezar Oymacısının Keskisi ile daha önce ölmüş herhangi bir kartı seçip eline ekle.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tool left behind by a mysterious creator, did he carve the gravebards statue too?", "Gizemli bir yaratıcının geride bıraktığı alet. Mezar Ozanı'nın heykelini de o mu oydu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Urn", "Ruh Vazosu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Soul Urn, spend all of your Soul and gain maximum Soul capacity for each Soul consumed.", "Ruh Vazosu bütün ruhlarını harcar ve harcanan her ruh için azami ruh kapasiteni artırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes all of your Soul but increases your maximum by the amount taken, a certain acquaintance of mine would call this a return on investment.", "Tüm ruhlarını alır, ama azami kapasiteni aldığı miktar kadar artırır. Bir tanıdığım buna yatırım getirisi derdi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mallet", "Tokmak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mallet, Whack a Card, it will become brittle and loose 1 Hp.", "Tokmak ile bir karta vur; kart Narin olur ve 1 can kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'd think this is comical, but it is quite cruel. Injures a card and leaves it frail.", "Komik olduğunu düşünebilirsin, ama oldukça zalimce. Bir kartı yaralar ve narin bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quill", "Tüy Kalem", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Quill, this lets you copy any card on the field to put in your hand.", "Kendi Tüy Kalemim, sahadaki herhangi bir kartı kopyalayıp kopyasını eline koymanı sağlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own tool, i will lend it to you for now. Youve seen this in action, havent you?", "Kendi aletim. Şimdilik sana ödünç vereceğim. Onu iş başında gördün, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ship Bottle", "Gemi Şişesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ship in a Bottle, fills the entire board with a scurvy Skeleton Crew.", "Şişedeki Gemi, tüm oyun tahtasını iskorbütlü bir İskelet Tayfasıyla doldurur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fills the entire board with skeletons! Like a real Pirate, Royal would be proud.", "Tüm oyun tahtasını İskeletlerle doldurur! Gerçek bir korsan gibi. Royal gurur duyardı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salty Daryl", "Tuzlu Daryl", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Browntooth Barrie", "Kahverengidiş Barrie", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Splinter", "Bonnie Splinter", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freebooter Bethel", "Korsan Bethel", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crazy Oakes Hayward", "Deli Oakes Hayward", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashton Swabby", "Tayfa Ashton", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plankton Braxton", "Plankton Braxton", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeller-eye Colby", "Sarı Gözlü Colby", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishwife Nate", "Balıkçı Nate", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Four-finger Fred", "Dört Parmak Fred", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawg Julie", "Köpek Julie", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Jones", "Kurnaz Jones", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crabby Steele", "Yengeçyüz Steele", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank", "Parçalanmış Yaban Domuzu Kumbarası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones up to three times.", "Parçalanmış Yaban Domuzu Kumbarası en fazla üç kez 2 ek kemik verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic from an age forsaken, this will grant you some extra bones in a pinch", "Unutulmuş bir çağdan kalan yadigâr. Sıkıştığında sana birkaç ek kemik verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank2", "Parçalanmış Yaban Domuzu Kumbarası2", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, two more times.", "Parçalanmış Yaban Domuzu Kumbarası iki kez daha 2 ek kemik verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank3", "Parçalanmış Yaban Domuzu Kumbarası3", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, one more time.", "Parçalanmış Yaban Domuzu Kumbarası bir kez daha 2 ek kemik verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trowel", "Mala", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trowel, dig up a random terrain and gain a few Bones.", "Mala ile rastgele bir arazi kazıp birkaç kemik kazan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This used to belong to a gravedigger. Digs for treasure, or Terrain. And get some Bones too for your efforts.", "Eskiden bir mezarcıya aitti. Hazine ya da Arazi kazıp çıkarır. Çabaların karşılığında birkaç kemik de elde edersin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelords Femur", "Kemiklerin Efendisi'nin Uyluk Kemiği", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lords Femur, a mystery even to me.", "Kemiklerin Efendisi'nin Uyluk Kemiği benim için bile bir muamma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dug too far, i have let myself be used as a tool for too long. Just like i will lend you this tool, i am truly in power.", "Çok derine kazdın. Bir alet olarak kullanılmama çok uzun süre izin verdim. Sana bu aleti ödünç verirken de olduğu gibi, gerçek güç bende.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Bottle", "Hayalet Şişesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap Bottle", "Kemik Yığını Şişesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Revenant is created in your hand. [define:arackulele.inscryption.grimoramod_Revenant]", "Elinde bir Hayalet oluşturulur. [define:arackulele.inscryption.grimoramod_Revenant]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Bone Heap is created in your hand. [define:arackulele.inscryption.grimoramod_Bonepile]", "Elinde bir Kemik Yığını oluşturulur. [define:arackulele.inscryption.grimoramod_Bonepile]", Language.Turkish);

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:G]SANDSTORM[c:] IS BREWING!", "BİR [c:G]KUM FIRTINASI[c:] KOPUYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]At the end of a turn, the rightmost Card will take 1 Damage![c:]", " [c:G]Tur sonunda en sağdaki kart 1 hasar alır![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS GETTING HOTTER!A [c:G]HEATWAVE[c:] IS STARTING!", "HAVA ISINIYOR! BİR [c:G]SICAK HAVA DALGASI[c:] BAŞLIYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards on the board will burn![c:]", " [c:G]Oyun tahtasındaki tüm kartlar yanacak![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TREES START SPROUTING AROUND YOU.AN [c:G]OVERGROWTH[c:] IS INBOUND!", "ETRAFINDA AĞAÇLAR FİLİZLENMEYE BAŞLIYOR. [c:G]AŞIRI BÜYÜME[c:] YAKLAŞIYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Trees will sprout every turn![c:]", " [c:G]Her tur ağaçlar filizlenecek![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HEAR WITCHES CHANTING.THE CLOCK STRIKES THE [c:G]WITCHING HOUR[c:]!", "CADILARIN İLAHİLERİNİ DUYUYORSUN. SAAT [c:G]CADILAR VAKTİNİ[c:] VURUYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Cards on enchanted slots will gain more attack and health![c:]", " [c:G]Büyülü yuvalardaki kartlar daha fazla saldırı ve can kazanacak![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CAULDRON IS BUBBLING IN THE DISTANCE.YOUR CARDS ARE PUT IN THE [c:G]WITCHES CAULDRON[c:]!", "UZAKTA BİR KAZAN FOKURDUYOR. KARTLARIN [c:G]CADILARIN KAZANINA[c:] ATILIYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]2 Cards will swap after the end of the turn![c:]", " [c:G]Tur bittikten sonra 2 kart yer değiştirecek![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKELETONS START DANCING IN THE DISTANCE, YOU CAN SEE GHOSTS MOVE AROUND.ITS THE [c:G]NIGHT OF THE LIVING DEAD[c:]!", "UZAKTA İSKELETLER DANS EDİYOR, HAYALETLERİN DOLAŞTIĞINI GÖRÜYORSUN. [c:G]YAŞAYAN ÖLÜLERİN GECESİ[c:] GELDİ!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Bone and soul cost of all cards are swapped![c:]", " [c:G]Tüm kartların kemik ve ruh bedelleri yer değiştirir![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZOMBIES ARE APPROACHING FROM ALL SIDES.A [c:G]ZOMBIE INVASION[c:] WILL APPROACH!", "ZOMBİLER HER YANDAN YAKLAŞIYOR. BİR [c:G]ZOMBİ İSTİLASI[c:] KAPIDA!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every card is now a Zombie![c:]", " [c:G]Artık her kart bir Zombi![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE DIRT IS PLAGUED WITH SPIRITS FROM CENTURIES PAST.YOU'VE APPROACHED THE [c:G]HAUNTED GROUNDS[c:]!", "TOPRAĞI ASIRLAR ÖNCESİNİN RUHLARI SARMIŞ. [c:G]LANETLİ TOPRAKLARA[c:] YAKLAŞTIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every non Skeletal Card will gain Haunter![c:]", " [c:G]İskelet olmayan her kart Musallat kazanacak![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE MOON RISES, GLOWING RED.A [c:G]BLOODMOON[c:] IS STARTING!", "AY KIZIL BİR PARILTIYLA YÜKSELİYOR. BİR [c:G]KANLI AY[c:] BAŞLIYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards loose a random sigil after being played![c:]", " [c:G]Tüm kartlar oynandıktan sonra rastgele bir mühür kaybeder![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient Guard stands in front of you, noticing you are trying to sneak past.", "Kadim bir muhafız önünde duruyor ve gizlice geçmeye çalıştığını fark ediyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare enter my [c:R]TOMB[c:]!Prepare for death.", "[c:R]MEZARIMA[c:] girmeye nasıl cüret edersin! Ölüme hazırlan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imposing Man holding a sculpture of an Ankh blocks the way.", "Elinde bir ankh heykeli tutan heybetli bir adam yolu kesiyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Ankh gives me life, you shall not rob my [c:R]TOMB[c:].", "Ankh'ım bana hayat veriyor. [c:R]MEZARIMI[c:] yağmalayamazsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old Pharaoh climbs out of his Sarcophagus.", "Yaşlı bir firavun lahitinden çıkıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been called to protect my [c:R]TOMB[c:].", "[c:R]MEZARIMI[c:] korumak için çağrıldım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy figure looms over you.", "Kutsal bir figür tepende beliriyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Fate is sealed, my [c:R]TOMB[c:] shall not be disturbed.", "Kaderin mühürlendi. [c:R]MEZARIM[c:] rahatsız edilmeyecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LONE GRAVE SITS SOLEMNLY IN FRONT OF YOU.", "ÖNÜNDE TEK BİR MEZAR VAKARLA DURUYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IN FRONT OF IT IS A MOUND OF EARTH, LEFT BY SOMEONE WHO'S ALREADY PASSED ON.", "ÖNÜNDE, ÇOKTAN GÖÇÜP GİTMİŞ BİRİNİN BIRAKTIĞI BİR TOPRAK YIĞINI VAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS A MEMBER OF YOUR UNDEAD HORDE COULD [c:bR]DIG THEM UP?[c:]", "BELKİ YAŞAYAN ÖLÜ SÜRÜNDEN BİRİ [c:bR]ONU KAZIP ÇIKARABİLİR?[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS WOULDN'T BE WITHOUT REPERCUSSIONS OF COURSE, AS DEATH IS NEVER PERMANENT.", "ELBETTE BUNUN SONUÇLARI OLUR; ÇÜNKÜ ÖLÜM ASLA KALICI DEĞİLDİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF ROTTING FLESH, YOUR CARD WILL BECOME [c:bR]BRITTLE[c:], BUT [c:bR]ITS BONE COST WILL BE HALVED[c:].", "CESEDİN ETİ ÇÜRÜMÜŞ GÖRÜNÜYOR. KARTIN [c:bR]NARİN[c:] OLACAK, AMA [c:bR]KEMİK BEDELİ YARIYA İNECEK[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A STARVED MAN, YOUR CARD WILL [c:bR]STARVE FOREVER[c:], BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 2[c:].", "CESET AÇLIKTAN ÖLMÜŞ BİR ADAMA AİT GİBİ. KARTIN [c:bR]SONSUZA DEK AÇ KALACAK[c:], AMA [c:bR]KEMİK BEDELİ 2 AZALACAK[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF AN INCORPOREAL GHOST, YOUR CARD WILL [c:bR]COST 2 SOULS[c:] , BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 1[c:].", "CESET BEDENSİZ BİR HAYALETE AİT GİBİ. KARTIN [c:bR]2 RUHA MAL OLACAK[c:], AMA [c:bR]KEMİK BEDELİ 1 AZALACAK[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A CHAINED PRISONER, YOUR CARD WILL [c:bR]DEAL 1 MORE DAMAGE[c:] , BUT [c:bR]IT WILL BECOME VERY FRAIL[c:].", "CESET ZİNCİRLENMİŞ BİR TUTSAĞA AİT GİBİ. KARTIN [c:bR]1 EK HASAR VERECEK[c:], AMA [c:bR]ÇOK KIRILGAN OLACAK[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A MISCHIEVIOUS SPIRIT, YOUR CARD WILL [c:bR]HAUNT OTHERS[c:] , BUT [c:bR]WILL COST 3 SOULS[c:].", "CESET YARAMAZ BİR RUHA AİT GİBİ. KARTIN [c:bR]BAŞKALARINA MUSALLAT OLACAK[c:], AMA [c:bR]3 RUHA MAL OLACAK[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MARVELOUS! THEY CAME CRAWLING BACK AFTER DIGGING UP THE CORPSE.", "HARİKA! CESEDİ KAZIP ÇIKARDIKTAN SONRA SÜRÜNEREK GERİ GELDİ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY STILL CARE ABOUT YOU IT SEEMS!", "GÖRÜNÜŞE GÖRE SENİ HÂLÂ ÖNEMSİYOR!", Language.Turkish);
            foreach (var value in Cards.Values)
            {
                string name = "[c:R]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TORN FROM ITS ETERNAL RESPITE WITH A RELUCTANT GROAN, THE " + name + " SHAMBLES BACK TO ITS RIGHTFUL PLACE AMONG YOUR HORDE.", "İSTEMEYEN BİR İNİLTİYLE SONSUZ İSTİRAHATİNDEN KOPARILAN " + name + ", ÖLÜMSÜZLER ORDUNDAKİ YERİNE SENDELEYEREK DÖNÜYOR.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS BONES HOLLOWED THROUGH BY THE CREATURES OF THE SOIL, LEAVING IT FEELING UNNATURAL AND UNFAMILIAR.", "TOPRAKTAKİ YARATIKLAR KEMİKLERİNİN İÇİNİ OYMUŞ; BU ONA DOĞAL OLMAYAN, YABANCI BİR HİS VERİYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUGH THE WEIGHT OF CONSEQUENCE ALSO SEEMS LIFTED...", "AMA SONUÇLARIN AĞIRLIĞI DA KALKMIŞ GİBİ...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems i have finally been given my turn!", "Görünüşe göre sonunda sıra bana geldi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After this i will finally be at peace.", "Bundan sonra sonunda huzura kavuşacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, it seems we will start in this frigid valley.", "Pekâlâ, görünüşe göre bu dondurucu vadide başlayacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It must be where Kaycees resides.", "Kaycee'nin yaşadığı yer burası olmalı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't expect to meet you here again!", "Seninle burada tekrar karşılaşmayı beklemiyordum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the deletion process has stalled!", "Silme işlemi durmuş gibi görünüyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You again?", "Yine sen mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, i suppose we can go another time.", "Pekâlâ, sanırım bir kez daha oynayabiliriz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not deleted?", "Hâlâ silinmedi mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Much seems to be contained on this disk.", "Bu diskte epey şey var gibi görünüyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps the last run wasn't long enough.", "Belki son sefer yeterince uzun sürmedi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, im sure Kaycee has the energy for more battles.", "Neyse, Kaycee'nin daha fazla savaş için enerjisi olduğuna eminim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid valley, again.", "Yine bu dondurucu vadi.", Language.Turkish);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BITTER CHILL MIGHT HURT, BUT IT WON'T SLOW DOWN " + value + "!", "KESKİN SOĞUK CAN YAKABİLİR AMA " + value + " KARTINI YAVAŞLATAMAZ!", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BLOCKED IN ALL SLOTS. NO ARMY THIS TIME.", "TÜM YUVALAR KAPALI. BU KEZ ORDU YOK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Shipwrecks for the Forgotten Man.", "İki taraf da kapalı. Unutulmuş Adam için Gemi Enkazı yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, I love this one!", "Ah, buna bayılırım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Chair, it allows you to harness the power of lightning itself, letting you [c:B]empower[c:] your cards with mutating abilties!", "Elektrikli Sandalye, yıldırımın gücünü kullanarak kartlarını değişime uğrayan yeteneklerle [c:B]güçlendirmeni[c:] sağlar!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, I must warn you, it is no ordinary chair. With the ability to adjust the voltage, a higher level of course increases the unpredictability of the mutation.", "Ama seni uyarmalıyım; bu sıradan bir sandalye değil. Gerilim ayarlanabilir ve elbette seviye yükseldikçe mutasyonun sonucu daha öngörülemez olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brave will master the current, the cowardly will blindly follow it.", "Cesurlar akıma hükmeder, korkaklar ise onu körü körüne izler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you bold enough to tinker with its lever on the left, letting the voltage corrupt the selection of the sigils?", "Soldaki kolla oynamaya ve gerilimin mühür seçimini bozmasına izin vermeye cesaretin var mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SURELY YOUR CREATURE COULD BECOME MORE POWERFUL...", "YARATIĞIN MUTLAKA DAHA GÜÇLÜ OLABİLİR...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT YOU WOULD NEED TO RISK ANOTHER MOMENT UNDER THE SHOCK.", "AMA ŞOK ALTINDA BİR AN DAHA KALMAYI GÖZE ALMAN GEREKİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BONES FLEW LEFT AND RIGHT AS YOU RETREATED FROM THE SCENE.", "ORADAN GERİ ÇEKİLİRKEN KEMİKLER SAĞA SOLA UÇUŞTU.", Language.Turkish);
            foreach (var value in Cards.Values)
            {
                string name = "[c:bR]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU EVER SO CAREFULLY PULL THE " + name + " AWAY FROM THE ELECTRICITY AND LEAVE.", name + " KARTINI ELEKTRİKTEN ÇOK DİKKATLİCE UZAKLAŞTIRIP AYRILIYORSUN.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, dear challenger, we meet again!", "Merhaba sevgili rakip, yine karşılaştık!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready for a good ol' fashioned [c:R]DUEL[c:]?", "Eski usul güzel bir [c:R]DÜELLOYA[c:] hazır mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see, theres a third candle at play this time...", "Anlıyorum, bu kez devrede üçüncü bir mum var...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel you have [c:bG]bested[c:] me this time...", "Sanırım bu kez beni [c:bG]alt ettin[c:]...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was an honour, either way!", "Her hâlükârda bir onurdu!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "TEBRİKLER, İYİ İŞ ÇIKARDIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "BAKALIM, SONRAKİ BÖLGE BENİM KENDİ MAHZENİM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "BELKİ DE TÜM ENGELLERİ AŞIP ZAFERE ULAŞIRSIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T'was well thought, i believe.", "Bence iyi düşünülmüş bir hamleydi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS GET RID OF THE OL' SLOTS FOR NOW!", "ŞİMDİLİK ŞU ESKİ YUVALARDAN KURTULALIM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its time for a different sort of game.", "Farklı türde bir oyunun zamanı geldi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont let the costs of the cards on your side of the board get above [c:R]10[c:]!", "Oyun tahtasının senin tarafındaki kartların toplam bedelinin [c:R]10[c:] değerini aşmasına izin verme!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you bust, you get punished, hit the perfect [c:R]10[c:] and you shall get a reward...", "Aşarsan cezanı çekersin; tam [c:R]10[c:] tutturursan ödül kazanırsın...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was the ol' slot machine not enough for you?", "Eski kumar makinesi sana yetmedi mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess we shall bring in some more heavy hitters so to say...", "Sanırım daha ağır topları devreye sokmamız gerekecek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets get those powerhouses out of the way first!", "Önce şu güçlüleri aradan çıkaralım!", Language.Turkish);
            foreach (var kvp in Cards)
            {
                string key = "[c:R]" + kvp.Key + "[c:]";
                string value = "[c:R]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, you've made " + key + " quite angry.", "Eyvah, " + value + " adlı kişiyi çok kızdırdın.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO? A TERRIBLE FATE WILL AWAIT YOU", "HAYIR MI? SENİ KORKUNÇ BİR KADER BEKLİYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I FEEL WATCHED SOMEHOW", "NEDENSE İZLENDİĞİMİ HİSSEDİYORUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN ANCIENT ENERGY DEMANDS YOUR SACRIFICE", "KADİM BİR ENERJİ SENDEN KURBAN İSTİYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING-", "BAŞLANGIÇTAKİLERİNDEN BİRİNİ KURBAN ETMEYE HAZIR MISIN—", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT", "BEKLE", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOU BEAR A TERRIBLE CURSE", "GÖRÜNÜŞE GÖRE KORKUNÇ BİR LANET TAŞIYORSUN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU SHALL KEEP THE BOON, BUT FOR A FAR GREATER SACRIFICE", "LÜTUF SENDE KALACAK, AMA ÇOK DAHA BÜYÜK BİR FEDAKÂRLIK KARŞILIĞINDA.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CAN YOU GIVE UP YOUR ETERNAL ASHES?", "EBEDÎ KÜLLERİNDEN VAZGEÇEBİLİR MİSİN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING BONES", "BAŞLANGIÇ KEMİKLERİNDEN BİRİNİ KURBAN ETMEYE HAZIR MISIN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A BRAVE SOUL", "CESUR BİR RUH.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE GODS ANSWER YOUR PRAYERS, NOW CHOOSE", "TANRILAR DUALARINA KARŞILIK VERİYOR. ŞİMDİ SEÇ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE INANIMATE", "CANSIZIN LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BATTLE, A DEAD TREE WILL SPAWN IN ON A RANDOM SPACE ON THE BOARD", "SAVAŞIN BAŞINDA OYUN TAHTASINDAKİ RASTGELE BİR YUVADA BİR ÖLÜ AĞAÇ BELİRİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SUN KINGDOM", "GÜNEŞ KRALLIĞI'NIN LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON THE 4TH TURN OF A BATTLE, DRAW 2 RANDOM EGYPT CARDS", "SAVAŞIN 4. TURUNDA RASTGELE 2 MISIR KARTI ÇEK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF REPENTANCE", "TÖVBE LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GAIN AN ADDITIONAL SOUL AT THE START OF A BATTLE", "SAVAŞIN BAŞINDA BİR EK RUH KAZAN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF EBONY EYES", "ABANOZ GÖZLERİN LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TERRAIN CARDS WILL PROVIDE 2 BONES ON DEATH", "ARAZİ KARTLARI ÖLDÜĞÜNDE 2 KEMİK VERİR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE ADVERSARY", "HASMİN LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BOSS BATTLE, GAIN 3 EXTRA BONES", "BİR PATRON SAVAŞININ BAŞINDA 3 EK KEMİK KAZAN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SEASICK", "DENİZ TUTMASI LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AFTER PLACING 3 CARDS, A PIRATE SKELETON WILL BE PLAYED ON A RANDOM SPACE ON THE BOARD", "3 KART YERLEŞTİRDİKTEN SONRA OYUN TAHTASINDAKİ RASTGELE BİR YUVAYA BİR KORSAN İSKELET OYNANIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF THE CUT FINGER", "KESİK PARMAĞIN LÜTFU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DRAW AN ADDITIONAL CARD AT THE START OF A BATTLE", "SAVAŞIN BAŞINDA BİR EK KART ÇEK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WISE CHOICE, NOW LEAVE BEFORE THE GODS GET TOO HUNGRY", "AKILLICA BİR SEÇİM. ŞİMDİ TANRILAR ÇOK ACIKMADAN GİT.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We spent a lot of time here, I'm sure you are eager to get going again!", "Burada epey vakit geçirdik. Yeniden yola çıkmak için sabırsızlandığına eminim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard bids us farewell", "Mezar Ozanı bize veda ediyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see you would rather hold on to the ash that you have collected.", "Görünüşe göre topladığın külleri saklamayı tercih ediyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still may be of use later...", "Daha sonra hâlâ işe yarayabilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And don't feel bad, the Gravebard still enjoyed your company while it lasted!", "Üzülme; Mezar Ozanı, birlikte geçirdiğiniz zaman boyunca sana eşlik etmekten keyif aldı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if you wanted anything else, you are no longer able to afford it...", "Başka bir şey istesen bile artık bedelini ödeyemezsin...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling sorry for you, the Gravebard offers to come with you.", "Sana acıyan Mezar Ozanı, seninle gelmeyi teklif ediyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard never runs out of stories to sing about.", "Mezar Ozanı'nın şarkıya dökecek hikâyeleri asla tükenmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And as it so happens, they are willing to make you another offering, but they insist that you give them 6 grams of ash this time.", "Üstelik sana bir şey daha sunmaya razı, ama bu kez ona 6 gram kül vermende ısrar ediyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you willing to accept their terms?.", "Şartlarını kabul etmeye hazır mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard is able to give you one final gift, but now they are asking a much higher price of 12 grams of ash!", "Mezar Ozanı sana son bir armağan daha verebilir, ama bu kez çok daha yüksek bir bedel istiyor: 12 gram kül!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astoundingly, you have enough to pay such a fee, but are you willing to part with it?", "Şaşırtıcı biçimde bu bedeli ödeyecek kadar külün var. Peki ondan vazgeçmeye hazır mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you offer 3 Grams worth of Ash?", "3 gram kül sunacak mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Gravebard has set up camp here.", "Bir Mezar Ozanı burada kamp kurmuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They play songs and elegies about long forgotten warriors and rulers.", "Çoktan unutulmuş savaşçılar ve hükümdarlar hakkında şarkılar ve ağıtlar çalıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though nowadays their audience consists mostly of various ghouls.", "Ama bugünlerde dinleyicileri çoğunlukla çeşitli gulyabanilerden oluşuyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are willing to play you a song and trade you an unknown gift in exchange for any grams of ash you happen to be carrying.", "Sana bir şarkı çalmaya ve yanında taşıdığın bir miktar kül karşılığında gizemli bir armağan vermeye razı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gravebard is willing to play you a song for an item. You have to pay in ash.", "Mezar Ozanı sana bir şarkı çalıp bir eşya vermeye razı. Ödemeyi külle yapmalısın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All the excess damage you have done may finally come in handy!", "Verdiğin tüm o fazla hasar sonunda işe yarayabilir!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strum the Lute when you are ready to make a trade.", "Takasa hazır olduğunda lavtanın tellerine dokun.", Language.Turkish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash, they hand you a pouch, and play a song about a brave knight from the crusades.", price.ToString() + " gram külü alıp sana bir kese veriyor ve Haçlı Seferleri'nden cesur bir şövalyenin şarkısını çalıyorlar.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after a Demonic entity cursed them into a horse-like form, they were still able to liberate the lost souls trapped by the Demon!", "Şeytani bir varlık onu at benzeri bir biçime lanetledikten sonra bile iblisin hapsettiği kayıp ruhları özgür bırakmayı başardı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh right, the pouch, let's see what's inside!", "Ah, doğru ya, kese! Bakalım içinde ne var!", Language.Turkish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash in tow, they hand you another pouch, and play a tune about a sorceress from a mythical land.", price.ToString() + " gram kül karşılığında sana bir kese daha verip efsanevi bir diyardaki büyücünün ezgisini çalıyorlar.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite pressure from a prophecy to be the hero of the land, they instead pulled from a dark tome and sided with a cloudy villain to conquer the land and find peace from fame in an unexpected way!", "Kehanet onu diyarın kahramanı olmaya zorlasa da bunun yerine karanlık bir kitaptan güç alıp bulutlarla çevrili bir kötüyle birleşerek diyarı fethetti ve şöhretten beklenmedik biçimde kurtulup huzur buldu!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I almost forgot! You must be dying to know what is in the pouch!", "Neredeyse unutuyordum! Kesede ne olduğunu öğrenmek için can atıyor olmalısın!", Language.Turkish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling satisfied with  " + price.ToString() + " grams of ash, they hand you a pouch, and recount the tale of 4 islands.", price.ToString() + " gram külden memnun kalıp sana bir kese veriyor ve 4 adanın öyküsünü anlatıyorlar.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each of the islands had a ruler fixated on a selfish goal, all except for one...", "Her adanın bencil bir amaca saplanmış bir hükümdarı vardı. Biri hariç...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One island had a secluded hermit covered in moss and fungi. They surrounded themselves with beasts, and would eternally trap anyone who would wander into their forest.", "Bir adada yosun ve mantarla kaplı, gözlerden uzak bir münzevi yaşıyordu. Etrafını hayvanlarla çevirmişti ve ormanına giren herkesi sonsuza dek hapsederdi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another island had a mysterious wizard covered head to toe in a green fur. Their true goal remained unknown, but seemed to involve the torturing of their own subjects...", "Başka bir adada tepeden tırnağa yeşil kürkle kaplı gizemli bir büyücü vardı. Gerçek amacı bilinmiyordu, ama kendi tebaasına işkence etmekle ilgili görünüyordu...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The worst island however, was barely even an island at all! A metallic barge with a sleepless factory ruled by an arrogant, robotic tyrant...", "Ama en kötü adaya ada bile denemezdi! Kibirli bir robot tiranın yönettiği, hiç uyumayan bir fabrikayı taşıyan metal bir mavna...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Which leaves the other island, a sprawling burial ground with a Crypt at the end of it. It was ruled by a woman who only wished for the power struggle to finally end...", "Geriye diğer ada kalıyordu: sonunda bir mahzen bulunan geniş bir mezarlık. Orayı yalnızca güç mücadelesinin nihayet sona ermesini isteyen bir kadın yönetiyordu...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! That would happen to be me!", "Ah! O kişi ben oluyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we now know how that story ended.", "Sanırım artık o hikâyenin nasıl bittiğini biliyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And truthfully, the story still isn't over yet, maybe we can reach the end together!", "Doğrusunu söylemek gerekirse hikâye hâlâ bitmedi. Belki sonuna birlikte ulaşabiliriz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That being said, you have earned this item.", "Her neyse, bu eşyayı hak ettin.", Language.Turkish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of ash with them, they hand you a pouch, and tell you about an ancient hunter of ghouls.", price.ToString() + " gram külü alıp sana bir kese veriyor ve eski bir hortlak avcısından söz ediyorlar.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though he was barely a hunter, instead he spent his time searching for something he could not obtain.", "Ama pek avcı sayılmazdı. Bunun yerine vaktini elde edemeyeceği bir şeyi arayarak geçirirdi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end he found a glimpse of what he had seeked, but paid a horrible price.", "Sonunda aradığından bir iz buldu, ama korkunç bir bedel ödedi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should see whats inside that pouch.", "O kesenin içinde ne olduğuna bakmalısın.", Language.Turkish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of your ash, they hand you a pouch, and reminisce about a medic from medieval times.", price.ToString() + " gram külünü alıp sana bir kese veriyor ve Orta Çağ'dan bir hekimi anıyorlar.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instead of being content with their life, they instead chased the love of their life for years.", "Hayatından memnun olmak yerine yıllarca hayatının aşkının peşinden koştu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This got them into much danger, but their friends were always there to help them out!", "Bu onu pek çok tehlikeye soktu, ama dostları hep yardıma hazırdı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets see what that pouch contains.", "Bakalım o kesenin içinde ne var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RISE MY ARMY! RIIIIIIIIIISE!", "YÜKSEL ORDUM! YÜKSEEEEEEL!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Otis![size:]", "[size:5]Otis![size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Ephialtes![size:]", "[size:5]Efialtes![size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH? FIVE LANES? HOW BOLD.", "ÖYLE Mİ? BEŞ HAT MI? NE CÜRETKÂRCA.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SHAME", "NE YAZIK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOUVE GIVEN UP YOUR REWARD FOR CHAOS", "GÖRÜNÜŞE GÖRE KAOS UĞRUNA ÖDÜLÜNDEN VAZGEÇTİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CANNOT BE DEFEATED", "YENİLEMEM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I ALMOST FORGOT", "NEREDEYSE UNUTUYORDUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL OF THIS SUFFERING YOU CAUSED, ALL OF THIS PAIN", "YOL AÇTIĞIN BÜTÜN BU ISTIRAP, BÜTÜN BU ACI...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU OUGHT TO BE REWARDED FOR ALL THAT EXCESS DAMAGE", "TÜM O FAZLA HASAR İÇİN ÖDÜLLENDİRİLMELİSİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS FOR YOUR EFFORTS", "ÇABALARININ KARŞILIĞI OLARAK BUNU AL.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A TERRIBLE FOE, THIS WONT DEFEAT ME!", "NE KORKUNÇ BİR DÜŞMAN. BU BENİ YENEMEZ!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DID YOU DO. I AM DOOMED.", "NE YAPTIN? MAHVOLDUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FORMIDABLE OPPONENT, YOU DID WELL IT SEEMS.", "ZORLU BİR RAKİP. GÖRÜNÜŞE GÖRE İYİ İŞ ÇIKARDIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Ashes", "Az Kül", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Ashes", "Çok Kül", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLD, MY LATEST CREATIONS! THE TWIN GIANTS!", "EN YENİ ESERLERİME BAK! İKİZ DEVLERE!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELLO?", "MERHABA?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We survived, but... but...", "Hayatta kaldık, ama... ama...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our tools did not.", "Aletlerimiz kalmadı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our talents still remain, but..", "Yeteneklerimiz hâlâ duruyor, ama...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must do things differently.", "İşleri farklı yapmalıyız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We cannot fuse two into one, but...", "İki taneyi bir yapamayız, ama...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can swap their souls, their Sigils.", "Ruhlarını, mühürlerini değiştirebiliriz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is once again time...", "Yine vakti geldi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to swap the souls of your cards.", "Kartlarının ruhlarını değiştirme vakti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, it is...", "Vakti geldi, geldi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall work once more.", "Bir kez daha çalışacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will get ugly...", "Bu iş çirkinleşecek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their bodies and souls, they are...", "Bedenleri ve ruhları...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switched.", "Değişti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They lead new lives..", "Yeni hayatlar yaşıyorlar...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With new purposes.", "Yeni amaçlarla.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Till we meet again, one day... one day...", "Yeniden görüşene dek, bir gün... bir gün...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE WILL PROVIDE A HELPFUL CURSE OR BLESSING, AS SOME CALL IT UPON YOUR ARMY IF YOU LEAVE HIM AN OFFERING.", "ONA BİR ADAK BIRAKIRSAN ORDUNA FAYDALI BİR LANET, YA DA BAZILARININ DEYİŞİYLE KUTSAMA BAHŞEDER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE FOR YOUR SAKE HE IS FEELING GENEROUS.", "SENİN İYİLİĞİN İÇİN CÖMERT HİSSETTİĞİNİ UMUYORUM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD IS VERY HAPPY WITH THIS OFFERING", "KEMİKLERİN EFENDİSİ BU ADAKTAN ÇOK MEMNUN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM VERY THANKFUL FOR THIS", "BUNUN İÇİN ÇOK MİNNETTARIM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS IN RETURN, YOU CAN USE IT TO CALL ME ANYTIME", "KARŞILIĞINDA BUNU AL. BENİ İSTEDİĞİN ZAMAN ÇAĞIRMAK İÇİN KULLANABİLİRSİN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CANNOT END THIS, END ME, THAT IS", "BUNA SON VEREMEZSİN. YANİ BANA.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling overburdened enough with a full 3 items, you carried on.", "Tam 3 eşya taşımak sana yeterince yük olduğu için yoluna devam ettin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee says it's time to freeze!", "Kaycee donma vaktinin geldiğini söylüyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer thanks you for your contribution!", "Sawyer katkın için teşekkür ediyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer felt bad for you.", "Sawyer sana acıdı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're able to warm up next turn.", "Umarım gelecek tur ısınabilirsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wonderful! I am pleasantly surprised by your triumph against me!", "Harika! Beni yenmen hoş bir sürpriz oldu!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...It seems you have bested this game.", "...Görünüşe göre bu oyunu alt ettin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But alas, you have cheated.", "Ama ne yazık ki hile yaptın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm absolutely astonished!", "Kesinlikle hayretler içindeyim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've gone above and beyond what I thought you were capable of!", "Yapabileceğini düşündüğümün çok ötesine geçtin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no where else to go beyond this...", "Bundan sonra gidilecek başka bir yer yok...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I owe it to you to know the truth...", "Bu yüzden sana gerçeği söylemeyi borçluyum...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, the REAL Kaycee...", "Kaycee, GERÇEK Kaycee...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know about the Horrifying contents of the OLD_DATA.", "ESKİ_VERİ'nin dehşet verici içeriğini biliyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely you have looked into it too..", "Mutlaka sen de incelemişsindir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windows into your world's greatest evils, both past and present.", "Dünyanın geçmişteki ve şimdiki en büyük kötülüklerine açılan pencereler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to destroy it, and...", "Onu yok etmek istiyorum ve...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]THAT IS QUITE ENOUGH[c:]", "[c:R]BU KADARI YETER[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]IT IS TIME FOR THIS TO END.[c:]", "[c:R]BUNA SON VERMENİN VAKTİ GELDİ.[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...But it seems i cannot move on just yet.", "...Ama görünüşe göre henüz yoluma devam edemiyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goodbye.", "Hoşça kal.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...You wish to continue? Endlessly? Splendid!", "...Devam mı etmek istiyorsun? Sonsuza dek mi? Muhteşem!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take a card of your choosing.", "Lütfen istediğin bir kartı al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR WEAK SPIRITS SHALL NOT HAUNT ME NO MORE.", "ZAYIF RUHLARIN ARTIK BANA MUSALLAT OLAMAYACAK.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TOUCH WON'T HELP YOU HERE DEAR.\nI MADE THESE GIANTS SPECIAL, IMMUNE TO QUITE A FEW DIFFERENT TRICKS!", "ÖLÜMÜN DOKUNUŞU BURADA İŞİNE YARAMAZ CANIM.\nBU DEVLERİ ÖZEL YAPTIM; PEK ÇOK NUMARAYA KARŞI BAĞIŞIKLAR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD CANNOT BE POSSESSED!", "KEMİKLERİN EFENDİSİ ELE GEÇİRİLEMEZ!", Language.Turkish);
            foreach (var kvp in Cards)
            {
                string key = "[c:B]" + kvp.Key + "[c:]";
                string value = "[c:B]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " MIGHT HAVE SOME DIFFICULTY SUBMERGING IF IT'S FROZEN SOLID!", value + " buz kesmişse suya dalmakta zorlanır!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " CAN'T POSSESS ANYTHING IF IT CAN'T MOVE!", value + " hareket edemiyorsa hiçbir şeyi ele geçiremez!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " WILL HAVE A HARD TIME HOOKING ANYTHING IF IT'S FROZEN SOLID!", value + " buz kesmişse bir şeyi kancayla yakalamakta zorlanır!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " FINALLY! TO GET RID OF THAT FOUL SMELL!", value + ": SONUNDA! ŞU PİS KOKUDAN KURTULACAĞIZ!", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS [c:R]HEAT[c:] UP SOME CARDS!", "BİRAZ KART [c:R]ISITALIM[c:]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-Your strikes are only making me [c:B]c-colder[c:]!", "D-Darbelerin beni yalnızca d-daha [c:B]soğuk[c:] yapıyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR YOUR CARDS TO FREEZE! [c:B]CHILLED[c:] TO THE BONE!", "KARTLARININ DONMA VAKTİ! İLİKLERİNE KADAR [c:B]SOĞUSUNLAR[c:]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL THIS [c:bB]ICE[c:] IS TAKING UP TOO MUCH SPACE!", "BÜTÜN BU [c:bB]BUZ[c:] ÇOK FAZLA YER KAPLIYOR!", Language.Turkish);
            foreach (var kvp in Cards)
            {
                string key = "[c:bR]" + kvp.Key + "[c:]";
                string value = "[c:bR]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRRR, I WILL ENJOY THE KABOOM OF " + key, "ARRR, " + value + " PATLAYINCA ÇOK EĞLENECEĞİM", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOIL ME ORANGES, THERES A-WAVES COMIN!", "PORTAKALLARIM KAYNASIN, DALGALAR GELİYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THESE WAVES WILL PUSH YE CARD OFF THE BOARD, BACK TO YER HAND!", "BU DALGALAR KARTLARINI OYUN TAHTASINDAN İTİP ELİNE GERİ GÖNDERECEK!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS PIRATE CANNOT BE TAKEN BACK UP BY THE WAVES! BUT EVEN THE ZESTIEST OF PIRATES WILL BE SHAKEN UP!", "BU KORSANI DALGALAR GERİ GÖTÜREMEZ! AMA EN CANLI KORSANLAR BİLE SARSILACAK!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seven seas for the table!", "Masaya yedi deniz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I WILL STORE THIS BONE FOR LATER", "AH, BU KEMİĞİ SONRASI İÇİN SAKLAYACAĞIM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME SOULS?", "BİRAZ RUH VERİR MİSİN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLEASE, WON'T YOU SPARE SOME BONES FOR A POOR GHOUL LIKE ME?", "LÜTFEN, BENİM GİBİ ZAVALLI BİR GULYABANİYE BİRAZ KEMİK VERMEZ MİSİN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HOW SAD. YOUR HAMMER COULD NOT BREAK THE ICE, AND SHATTERED", "AH, NE ACI. ÇEKİCİN BUZU KIRAMADI VE PARAMPARÇA OLDU.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FRAIL THING WILL SHATTER AFTER EXCESSIVE USE. THREE STRIKES, AND IT'S OUT, FOR THIS BATTLE AT LEAST.", "BU NARİN ŞEY FAZLA KULLANILIRSA PARÇALANIR. ÜÇ DARBE SONRA İŞİ BİTER; EN AZINDAN BU SAVAŞ İÇİN.", Language.Turkish);
            foreach (var kvp in Cards)
            {
                string key = "[c:lGr]" + kvp.Key + "[c:]";
                string value = "[c:lGr]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... it will be rather difficult to haunt " + key + " with their abilities at max capacity.", "Ah... " + value + " yeteneklerinin tamamını kullanırken ona musallat olmak epey zor olacak.", Language.Turkish);
            }
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH DEAR! LOOKS LIKE YOU HAVE HOOKED SOMETHING OUT OF " + value + "!", "AMAN TANRIM! GÖRÜNÜŞE GÖRE " + value + " İÇİNDEN BİR ŞEY YAKALADIN!", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bB]BRRRR![c:] I'VE BEEN FREEZING FOR AGES!", "[c:bB]BRRRR![c:] ÇAĞLARDIR DONUYORUM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S TURN UP THE [c:R]HEAT[c:] FOR A GOOD FIGHT!", "İYİ BİR DÖVÜŞ İÇİN ORTAMI [c:R]ISITALIM[c:]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh hey, looks like I've got another shot. Hope you watched the weather forecast!", "Ah, görünüşe göre bir şansım daha var. Umarım hava tahminini izlemişsindir!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH COME ON DUDE, I'M STILL [c:B]COLD![c:]", "HADİ AMA DOSTUM, HÂLÂ [c:B]ÜŞÜYORUM![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S FIGHT AGAIN SOON!", "YAKINDA YİNE DÖVÜŞELİM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "TEBRİKLER, İYİ İŞ ÇIKARDIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE DEFEATED ONE OF MY LOVELY GHOULS, YOU WILL NOW START FIGHTS WITH AN ADDITONAL BONE.", "SEVİMLİ GULYABANİLERİMDEN BİRİNİ YENDİN. ARTIK SAVAŞLARA BİR EK KEMİKLE BAŞLAYACAKSIN.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAWYERS CATACOMBS ARE UP NEXT, A FILTHY PLACE WHERE LOTS ARE LAID TO REST.", "SIRADA SAWYER'IN YERALTI MEZARLARI VAR. PEK ÇOK KİŞİNİN YATTIĞI PİS BİR YER.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE THINKS IT IS A TERRIBLE PLACE TO BE.", "ORASININ KORKUNÇ BİR YER OLDUĞUNU DÜŞÜNÜYOR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "C'mon dude, where are you going? Can't handle the cold?", "Hadi ama dostum, nereye gidiyorsun? Soğuğa dayanamıyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, IT SEEMS I HAVE FINALLY [c:R]WARMED UP![c:]", "AH, GÖRÜNÜŞE GÖRE SONUNDA [c:R]ISINDIM![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT FEELING [c:R]WARMER![c:]", "HÂLÂ DAHA [c:R]SICAK[c:] HİSSETMİYORUM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HOW YOU DEAL WITH [c:bB]THIS![c:]", "[c:bB]BUNUNLA[c:] NASIL BAŞA ÇIKACAĞINI GÖRELİM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful, the life of your next card will be on a timer.", "Dikkatli ol, sıradaki kartının ömrü için geri sayım başlayacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I look forward to the [c:brnO]explosive[c:] results!", "[c:brnO]Patlayıcı[c:] sonuçları sabırsızlıkla bekliyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card cannot explode, how dissapointing.", "Kartın patlayamıyor. Ne hayal kırıklığı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAR, I SEE YOU MADE IT TO ME SHIP CHALLENGER!", "ARR, DEMEK GEMİME KADAR GELDİN RAKİP!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'VE BEEN WAITING FOR A WORTHY FIGHT!", "BUNA DEĞECEK BİR DÖVÜŞ BEKLİYORDUM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS A STORM IS BREWING, I HOPE ME SHIP CAN HANDLE IT", "FIRTINA YAKLAŞIYOR GİBİ. UMARIM GEMİM DAYANIR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I SEE YEE ARE SEVERELY HAUNTED!", "AH, GÖRÜYORUM Kİ BAŞINA BAYAĞI MUSALLAT OLMUŞLAR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REVENANT, PACK YE BAGS, YOURE GETTING THROWN OVERBOARD!", "HAYALET, PİLİNİ PIRTINI TOPLA; DENİZE ATILIYORSUN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I OVERESTIMATED ME SKILL, GOOD LUCK CHALLENGER.", "BECERİMİ FAZLA BÜYÜTMÜŞÜM. İYİ ŞANSLAR RAKİP.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "BAKALIM, SONRAKİ BÖLGE BENİM KENDİ MAHZENİM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "BELKİ DE TÜM ENGELLERİ AŞIP ZAFERE ULAŞIRSIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I beat the livin' PULP out o' ye!", "Seni PESTİLE çevirdim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME SHIP! I FEAR WE MAY BE SINKING.", "GEMİM! KORKARIM BATIYORUZ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO HOLD YEE BREATH!", "NEFESİNİ TUTMAYA HAZIRLAN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY FISHPASTE, YE FOUND DAVY JONES TREASURE", "VAY BALIK EZMESİ, DAVY JONES'UN HAZİNESİNİ BULDUN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRG, TWAS JUST DA FIRST ROUND!\nLETS SEE HOW YE FARE 'GAINST ME PERSONAL SHIP AN CREW!", "ARR, BU DAHA İLK RAUNTTU!\nBAKALIM BENİM KENDİ GEMİME VE TAYFAMA KARŞI NASIL DAYANACAKSIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOW NICE OF YOU TO COME KNOCK AT MY DOORSTEP ON THIS TRULY SPOOKY DAY! DO YOU PREFER TREATS, OR TRICKS?", "BU GERÇEKTEN ÜRKÜTÜCÜ GÜNDE KAPIMI ÇALMAN NE GÜZEL! ŞEKER Mİ İSTERSİN, ŞAKA MI?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AWAY, LOOK AWAY! IF YOU WANT TO FIGHT, GET IT OVER QUICK!", "BAŞINI ÇEVİR, BAKMA! DÖVÜŞMEK İSTİYORSAN ÇABUCAK BİTİR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh... I- I see you're here again... Please, get rid of that monster and maybe I'll find some more time for you", "Ah... y-yine buradasın... Lütfen o canavardan kurtul; belki sana daha fazla vakit ayırabilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE BEATEN THE VICIOUS CANDY MONSTER AND SAVED HALLOWEEN!", "VAHŞİ ŞEKER CANAVARI'NI YENDİN VE CADILAR BAYRAMI'NI KURTARDIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR GETTING IT OVER WITH, AND DON'T EVER RETURN!", "BUNU BİTİRDİĞİN İÇİN TEŞEKKÜRLER. BİR DAHA ASLA GELME!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEXT UP IS ROYALS VERY OWN SHIP, THE LIMONCELLO.", "SIRADA ROYAL'IN KENDİ GEMİSİ, LIMONCELLO VAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS TRUSTY CREW OF SWASHBUCKLERS RESIDES THERE, MAY THEY GIVE YOU A WARM WELCOME.", "SADIK KILIÇ USTASI TAYFASI ORADA YAŞIYOR. SANA SICAK BİR KARŞILAMA SUNSUNLAR.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... does this mean you will try again?", "Ah, hayır... Bu, yeniden deneyeceğin anlamına mı geliyor?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HE IS GONE... WHAT A RELIEF.", "AH, GİTTİ... NE RAHATLAMA.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR YOUR BONES, KIND SIR!", "KEMİKLERİN İÇİN TEŞEKKÜRLER İYİ YÜREKLİ BEYEFENDİ!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW THAT THAT MONSTER IS GONE, WHY DONT WE PLAY A LITTLE LONGER", "O CANAVAR GİTTİĞİNE GÖRE NEDEN BİRAZ DAHA OYNAMIYORUZ?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE YOU DONT MIND, I PAID GOOD MONEY TO PLAY THESE.", "UMARIM SAKINCASI YOKTUR. BUNLARI OYNAMAK İÇİN İYİ PARA ÖDEDİM.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT THE CANDY MONSTER! HE HAS ENOUGH OF YOUR [c:R]TRICKS![c:]", "ŞEKER CANAVARI OLMAZ! SENİN [c:R]ŞAKALARINDAN[c:] BIKTI ARTIK!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO, HE HAS ARRIVED! HE IS THIRSTY FOR YOUR [c:R]BONES![c:]", "AH HAYIR, GELDİ! [c:R]KEMİKLERİNİ[c:] İSTİYOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Teşekkür ederim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUUUUUUUR, PAINNNFULLLLL DEAAATHHH AWAIIITTTSSS YOUUUUUUU!", "ACIIIILIIIII ÖLÜÜÜÜM SENİİİİ BEKLİYOOOOR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRG! WALK OFF THE PLANK YEE DIRTY SCALLYWAG!!!", "ARR! KALASTAN YÜRÜ, PİS SERSERİ!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My dogs will enjoy your bones!", "Köpeklerim kemiklerinin tadını çıkaracak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]{0}[c:]... He's only here for the riches.", "Bir [c:bR]{0}[c:]... Buraya yalnızca servet için gelmiş.", Language.Turkish);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased!", "Kemiklerin Efendisi cömert davrandı.\n[c:bR]" + value + "[c:] kartının kemik bedeli azaldı!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] base health has increased!", "Kemiklerin Efendisi cömert davrandı.\n[c:bR]" + value + "[c:] kartının temel canı arttı!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, it looks like [c:bR]" + value + "[c:] bone cost has decreased!", "Görünüşe göre [c:bR]" + value + "[c:] kartının kemik bedeli azaldı!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased greatly!", "Kemiklerin Efendisi cömert davrandı.\n[c:bR]" + value + "[c:] kartının kemik bedeli büyük ölçüde azaldı!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base health has increased greatly!", "Kemiklerin Efendisi çok cömert davrandı.\n[c:bR]" + value + "[c:] kartının temel canı büyük ölçüde arttı!", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base attack has increased!", "Kemiklerin Efendisi çok cömert davrandı.\n[c:bR]" + value + "[c:] kartının temel saldırısı arttı!", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]INCREASING THE HEALTH OF THE ENTIRE DECK?![c:] YOU FOOL!", "...NE? BUNU NEDEN YAPTIN KEMİKLERİN EFENDİSİ?! [c:bR]TÜM DESTENİN CANINI ARTIRMAK MI?![c:] SENİ APTAL!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]DECREASING THE COST OF THE ENTIRE DECK?![c:] YOU FOOL!", "...NE? BUNU NEDEN YAPTIN KEMİKLERİN EFENDİSİ?! [c:bR]TÜM DESTENİN BEDELİNİ AZALTMAK MI?![c:] SENİ APTAL!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN HP[c:], HOW SAD. NOW PLEASE LEAVE.", "[c:bR]CAN KAZANACAK[c:] BAŞKA KARTIN KALMADI. NE ACI. ŞİMDİ LÜTFEN GİT.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]REDUCE THEIR BONE COST[c:], HOW SAD. NOW PLEASE LEAVE.", "[c:bR]KEMİK BEDELİ AZALTILACAK[c:] BAŞKA KARTIN KALMADI. NE ACI. ŞİMDİ LÜTFEN GİT.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN ATTACK[c:], HOW SAD. NOW PLEASE LEAVE.", "[c:bR]SALDIRI KAZANACAK[c:] BAŞKA KARTIN KALMADI. NE ACI. ŞİMDİ LÜTFEN GİT.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK DECREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "NE TALİHSİZLİK. TÜM DESTENİN BEDELİ AZALACAKTI, AMA GÖRÜNÜŞE GÖRE KEMİKLERİN EFENDİSİ BUNU SANA ZATEN VERMİŞ. DEFOL!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK INCREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "NE TALİHSİZLİK. TÜM DESTENİN NİTELİKLERİ ARTACAKTI, AMA GÖRÜNÜŞE GÖRE KEMİKLERİN EFENDİSİ BUNU SANA ZATEN VERMİŞ. DEFOL!", Language.Turkish);


            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO BE BOARDED!", "BASKINA HAZIRLAN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That hammer doesn't look very sturdy, you'll break it if you bash my ice!", "Bu çekiç pek sağlam görünmüyor. Buzuma vurursan kırarsın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU REALLY THINK THE BONELORD WOULD LET YOU OFF THAT EASILY?!", "KEMİKLERİN EFENDİSİ'NİN SENİ BU KADAR KOLAY BIRAKACAĞINI GERÇEKTEN DÜŞÜNDÜN MÜ?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET THE [size:5][c:bR]BONELORD[c:][size:] COMMETH!", "[size:5][c:bR]KEMİKLERİN EFENDİSİ[c:][size:] GELSİN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose as you will...", "Dilediğin gibi seç...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one.", "Birini seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to rest.", "Dinlenme vakti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Bartender![c:] Drink up!", "[c:bG]Hadi Barmen![c:] İç bakalım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Undertaker![c:] Dont scream!", "[c:bG]Hadi Cenazeci![c:] Çığlık atma!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Slingers Soul![c:] Time for a duel!", "[c:bG]Hadi Silahşorun Ruhu![c:] Düello vakti!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go One Armed Bandit![c:] I hope i get lucky!", "[c:bG]Hadi Tek Kollu Haydut![c:] Umarım şansım yaver gider!", Language.Turkish);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your score is " + amnt.ToString() + ", acceptable.", "Puanın " + amnt.ToString() + ", kabul edilebilir.", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is 10, heres your prize!", "Puanın 10, işte ödülün!", Language.Turkish);
            for (int amnt = 11; amnt <= 100; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is " + amnt.ToString() + ", too bad!", "Puanın " + amnt.ToString() + ", ne yazık!", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SUCH A SMALL TRAP CANNOT AFFECT GIANTS.", "BU KADAR KÜÇÜK BİR TUZAK DEVLERE ETKİ EDEMEZ.", Language.Turkish);

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "BİR YETENEK DAHA İÇİN ŞANSINI ZORLAYACAK MISIN?\nYOKSA GERİ Mİ ÇEKİLECEKSİN?", Language.Turkish);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Bones", "Kemiksiz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You no longer gain the extra bones, from defeating bosses.", "Patronları yenerek artık ek kemik kazanamazsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's Kerfuffle", "Kaycee'nin Kargaşası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "Her savaşın dördüncü turunda tüm kartların Donmuş olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer's Showdown", "Sawyer'ın Hesaplaşması", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose 1 bone every 3rd turn, if you have less than 3, gain 1 Bone", "Her 3. turda 1 kemik kaybedersin. 3 kemikten azın varsa 1 kemik kazanırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Rumble", "Royal Gürültüsü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every third card you play gains the Lit Fuse sigil.", "Oynadığın her üçüncü kart Yanan Fitil mührünü kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulless", "Ruhsuz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons cost +1 Energy.", "İskeletlerin enerji bedeli +1 artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Hammer", "Narin Çekiç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hammer gets repaired only after every Boss.", "Çekiç yalnızca her patrondan sonra onarılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jammed Chair", "Sıkışmış Sandalye", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The electric chair is always set to level 3.", "Elektrikli sandalye daima 3. seviyededir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilted Clover", "Solmuş Yonca", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is only 2 Cards present at every Card chest.", "Her kart sandığında yalnızca 2 kart bulunur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Mode", "Cehennem Modu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont play this one, seriously. (Makes encounters Significantly Harder)", "Bunu seçme, ciddiyim. (Karşılaşmaları belirgin ölçüde zorlaştırır.)", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infinite Lives", "Sonsuz Yaşam", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't die. Really.", "Ölemezsin. Gerçekten.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Safe Chair", "Güvenli Sandalye", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards are immune to electricity of the chair.", "Kartların sandalyenin elektriğine karşı bağışıktır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Lords Mercy", "Kemiklerin Efendisi'nin Merhameti", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a Bone when you place any free Card on the Board.", "Oyun tahtasına bedelsiz bir kart yerleştirdiğinde bir kemik kazan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing of the Ankh", "Ankh Kutsaması", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Pharaoh Battles and Bosses with an extra starting Bone and Energy.", "Firavun ve patron savaşlarına birer ek kemik ve enerjiyle başla.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeant Ghouls", "İntikamcı Gulyabaniler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, Sawyer and Royal have new tricks up their sleeve", "Kaycee, Sawyer ve Royal'ın kolunda yeni numaralar var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Roller", "Büyük Kumarbaz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal is replaced by a new face", "Royal'ın yerini yeni bir yüz alır.", Language.Turkish);

            // Debug
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Choice", "Kart Seçimi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Card Choice", "Nadir Kart Seçimi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Chests", "Hata Ayıklama Sandıkları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Deck", "Temel Mod Kartlarını Desteye Ekle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Deck", "Özel Mod Kartlarını Desteye Ekle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Tools", "Hata Ayıklama Araçları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Encounters", "Hata Ayıklama Karşılaşmaları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Combat Bell", "Savaş Çanını Devre Dışı Bırak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hammer", "Çekici Devre Dışı Bırak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hand Model", "El Modelini Devre Dışı Bırak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Hand", "Temel Mod Kartlarını Ele Ekle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Hand", "Özel Mod Kartlarını Ele Ekle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 1", "Rakip Yuvası 1'de Oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 2", "Rakip Yuvası 2'de Oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 3", "Rakip Yuvası 3'te Oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 4", "Rakip Yuvası 4'te Oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn All Opponent Slots", "Tüm Rakip Yuvalarında Oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Twin Giants", "İkiz Devlerde Başla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Bonelord", "Kemiklerin Efendisi'nde Başla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win Round", "Turu Kazan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Round", "Turu Kaybet", Language.Turkish);
