    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "MAGNIFICUS İLE YENİ TUR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "MAGNIFICUS İLE YENİ TUR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Desteyi Gör", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "BÜYÜ KULESİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "BALÇIK ZİNDANI", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "LAV ZİNDANI", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "BOŞLUK ZİNDANI", Language.Turkish);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Magnificus'un Kaycee Modu'ndaki tüm meydan okumaları ve başlangıç destelerini otomatik açar. Bu, Magnificus meydan okuma puanını DEĞİŞTİRMEZ. Fikrini değiştirip meydan okumaları adil biçimde açmaya karar verirsen puanın aynı kalır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "2. Bölüm'deki temel büyücü kartları özgün niteliklerini korur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Yeni 3D modeller yerine eski 2D düz kart tasarımlarını kullanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Özgün Magnificus finalindeki gibi her kartın arka planına boya sıçramaları ekler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Magnificus'un oyunu için üçüncü şahıs bakış açısı. Klasik birinci şahıs deneyimini istiyorsan kapat.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Masaüstü modunda oyuncunun etrafında bir ızgara gösterir.", Language.Turkish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Boş Güç Taşı", Language.Turkish);
            RegisterAbility("Blank Mox", "Boş Güç Taşı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Bu mührü taşıyan kart çekildiğinde rastgele bir Güç Taşı Kristaline dönüşür.\n Başka bir kartın üzerindeyken o kart rastgele bir Güç Taşı Kristali oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Belirsiz Güç Taşı", Language.Turkish);
            RegisterAbility("Undecided Mox", "Belirsiz Güç Taşı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Bu mührü taşıyan kart oynandığında onun sağlayacağı güç taşı türünü seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Yakut Yürek", Language.Turkish);
            RegisterAbility("Ruby Heart", "Yakut Yürek");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Bu mührü taşıyan kart öldüğünde yerinde bir Yakut Güç Taşı oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Safir Kalbi", Language.Turkish);
            RegisterAbility("Sapphire Heart", "Safir Kalbi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Bu mührü taşıyan kart öldüğünde yerinde bir Safir Güç Taşı oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Kemik İliği", Language.Turkish);
            RegisterAbility("Bone Marrow", "Kemik İliği");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Cevher olmayan kartlarından biri öldüğünde bu mührü taşıyan kart 1 güç kazanır; en fazla 5 güce ulaşabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Uyarım", Language.Turkish);
            RegisterAbility("Stimulation", "Uyarım");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "Her turun sonunda bu mührü taşıyan kart 1 güç kazanır; en fazla 4 güce ulaşabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Uyarım (Can)", Language.Turkish);
            RegisterAbility("Stimulation (Health)", "Uyarım (Can)");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "Her turun sonunda bu mührü taşıyan kart 2 can kazanır; en fazla 10 cana ulaşabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Ölüm Çekişi", Language.Turkish);
            RegisterAbility("Dead Draw", "Ölüm Çekişi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Cevher olmayan bir kart öldüğünde destenden bir kart çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Zümrüt Kalp", Language.Turkish);
            RegisterAbility("Emerald Heart", "Zümrüt Kalp");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Bu mührü taşıyan kart öldüğünde yerinde bir Zümrüt Güç Taşı oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Balçıklı", Language.Turkish);
            RegisterAbility("Gooey", "Balçıklı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Bu mührü taşıyan kart darbe aldığında vuran kart 1 saldırı kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Cevherli Zihinler", Language.Turkish);
            RegisterAbility("Mental Gemnastics", "Cevherli Zihinler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Bu mührü taşıyan kart oynandığında oyun tahtasındaki cevher sayısı kadar kartı destenden çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Ganimetçi", Language.Turkish);
            RegisterAbility("Loot", "Ganimetçi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Bu mührü taşıyan kart doğrudan hasar verdiğinde verilen hasar kadar kartı destenden çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Can Çalma", Language.Turkish);
            RegisterAbility("Life Steal", "Can Çalma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Bu mührü taşıyan kart doğrudan hasar verdiğinde sahibinin canı, verilen hasar kadar iyileşir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Geri İtme Vuruşu", Language.Turkish);
            RegisterAbility("Knockback Hit", "Geri İtme Vuruşu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Bu mührü taşıyan kart bir rakip kartına vurduğunda hedef, mühürde gösterilen yöne itilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Kazığa Geçirilmiş", Language.Turkish);
            RegisterAbility("Impaled", "Kazığa Geçirilmiş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Bu mührü taşıyan kart öldüğünde yerinde bir Mızrak oluşturur. Mızrak: Keskin Oklar, 0 güç, 3 can.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Kadim Güç Taşı", Language.Turkish);
            RegisterAbility("Magnus Mox", "Kadim Güç Taşı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Bu mührü taşıyan kart oyun tahtasındayken sahibine bir Turuncu, bir Mavi ve bir Yeşil Cevher sağlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Diriliş", Language.Turkish);
            RegisterAbility("Resurrection", "Diriliş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Cevher olmayan bir kart öldüğünde ölen kart hayata döner, ama bu kart 3 can kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Zar Gücü", Language.Turkish);
            RegisterAbility("Rerolls", "Zar Gücü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "Her turun sonunda bu mührü taşıyan kartın temel gücü, 0 ile 3 arasında rastgele bir değer olarak yeniden belirlenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Çelik Tuzak", Language.Turkish);
            RegisterAbility("Steel Trap", "Çelik Tuzak");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Bu mührü taşıyan kart öldüğünde karşısındaki kart da ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Cevher Kalkanı", Language.Turkish);
            RegisterAbility("Gem Shield", "Cevher Kalkanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Bu mührü taşıyan kart oynandığında oyun tahtasındaki tüm cevherler bir kalkan kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Kaplama İşi", Language.Turkish);
            RegisterAbility("Plating Work", "Kaplama İşi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Bu mührü taşıyan kart oyun tahtasındayken senin tarafındaki tüm cevherler Keskin Oklar mührünü ve 2 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Kuklacı", Language.Turkish);
            RegisterAbility("Animator", "Kuklacı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Bu mührü taşıyan kart oyun tahtasındayken güç taşı olmayan 0 güçlü tüm kartlar 2 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Cevher Soğurucu", Language.Turkish);
            RegisterAbility("Gem Absorber", "Cevher Soğurucu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Bu mührü taşıyan kart oynandığında senin tarafındaki tüm cevherler ölür. Emilen her cevher için bu kart 1 güç ve 2 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Suya Dal", Language.Turkish);
            RegisterAbility("Submerge", "Suya Dal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "Tur sonunda bu mührü taşıyan kart suya dalar. Yeniden su yüzüne çıktığında rastgele bir Dokunaç Kartına dönüşür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Büyü Yoldaşı", Language.Turkish);
            RegisterAbility("Familiar", "Büyü Yoldaşı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Oyun tahtasında cevher olmayan hiçbir kart yoksa bu mührü taşıyan kart ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Solma", Language.Turkish);
            RegisterAbility("Fading", "Solma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Bu mührü taşıyan kart tur sonunda ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Biçim Değiştiren", Language.Turkish);
            RegisterAbility("Morph", "Biçim Değiştiren");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Bu mührü taşıyan kart oynandığında karşısındaki kartı taklit eder. Karşısında kart yoksa bu kart ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Çarpım", Language.Turkish);
            RegisterAbility("Multiplication", "Çarpım");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Bu mührü taşıyan kart oynandığında aynı karttan bir tane daha çek; ancak cevher bedeli farklı olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Güç Taşı Döngüsü", Language.Turkish);
            RegisterAbility("Mox Cycle", "Güç Taşı Döngüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "Her turun sonunda oyun tahtasındaki tüm güç taşları sırayla farklı cevher türlerine dönüşür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Güç Taşı Kayması", Language.Turkish);
            RegisterAbility("Mox Strafe", "Güç Taşı Kayması");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "Tur sonunda bu kart mühürde gösterilen yöne hareket eder ve ardında bir güç taşı bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Safçılık", Language.Turkish);
            RegisterAbility("Purist", "Safçılık");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Bu kartın tam karşısındaki her kartın tüm mühürleri kaldırılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Mayalama Atölyesi", Language.Turkish);
            RegisterAbility("Brewery", "Mayalama Atölyesi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "Her turun sonunda yan destenden otomatik olarak bir güç taşı kartı çekersin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Tutuşturma", Language.Turkish);
            RegisterAbility("Ignite", "Tutuşturma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Bu mührü taşıyan kart oynandığında karşı taraftaki tüm boş yuvalar alevle dolar. Alev: 0/1, Sinir Bozucu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Yıldız İzdüşümü", Language.Turkish);
            RegisterAbility("Projection", "Yıldız İzdüşümü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Bu mührü taşıyan kart darbe aldığında hareket eder ve ardında kendi astral izdüşümünü bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Büyü Kitabı", Language.Turkish);
            RegisterAbility("Spell Book", "Büyü Kitabı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Bu mührü taşıyan kart oynandığında rastgele bir büyü kartı çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Büyü Âlimi", Language.Turkish);
            RegisterAbility("Scholar", "Büyü Âlimi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Bu mührü taşıyan kart oynandığında Mavşil'in Kitaplarından rastgele birini çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Midas'ın Dokunuşu", Language.Turkish);
            RegisterAbility("Midas' Touch", "Midas'ın Dokunuşu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Bu mührü taşıyan kart başka bir karta saldırdığında hedef tüm saldırısını kaybeder ve altına dönüşür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Altından Yapılmış", Language.Turkish);
            RegisterAbility("Made of Gold", "Altından Yapılmış");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Bu mührü taşıyan kart öldüğünde onu öldüren 2 kristal kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Patlayıcı Çağırma Rünleri", Language.Turkish);
            RegisterAbility("Summon Runes", "Patlayıcı Çağırma Rünleri");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Bu mührü taşıyan kart oynandığında yanına iki rün çağırır. Rün: 0 güç, 1 can, Fünye.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Can Büyüsü", Language.Turkish);
            RegisterAbility("Spell of Health", "Can Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Bu mührü taşıyan bir büyü oynandığında oyun tahtasının senin tarafındaki tüm kartlar +2 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Saldırı Büyüsü", Language.Turkish);
            RegisterAbility("Spell of Attack", "Saldırı Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Bu mührü taşıyan bir büyü oynandığında oyun tahtasının senin tarafındaki tüm kartlar +1 saldırı kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Kırağı Büyüsü", Language.Turkish);
            RegisterAbility("Frost Spell", "Kırağı Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Bu mührü taşıyan bir büyü oynandığında rakibin tüm kartlarının saldırısı 0 olur, ama kartlar +2 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Rüzgâr Büyüsü", Language.Turkish);
            RegisterAbility("Spell of Wind", "Rüzgâr Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Bu mührü taşıyan bir büyü oynandığında oyun tahtasının senin tarafındaki tüm kartlar Uçuşan olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Şamata", Language.Turkish);
            RegisterAbility("Ruckus", "Şamata");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Bu mührü taşıyan kart oynandığında oyun tahtasındaki tüm kartlar saat yönünde hareket eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Su Büyüsü", Language.Turkish);
            RegisterAbility("Spell of Water", "Su Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Bu mührü taşıyan bir büyü oynandığında oyun tahtasındaki her kartın mühürleri silinir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Alev Büyüsü", Language.Turkish);
            RegisterAbility("Spell of Flame", "Alev Büyüsü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Oyun tahtasının bir tarafını seç. O taraftaki her kart 2 can kaybeder (ama ölmez) ve saldırısı 1 artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Ateşe Ver", Language.Turkish);
            RegisterAbility("Set Ablaze", "Ateşe Ver");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Karşı taraftaki her kart 2 can kaybeder (ama ölmez) ve saldırısı 1 artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Tek Kullanımlık Büyü", Language.Turkish);
            RegisterAbility("One Time Spell", "Tek Kullanımlık Büyü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "Tur bittiğinde bu mührü taşıyan büyü ölür ve destenden kaldırılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Açgözlülük Vazosu", Language.Turkish);
            RegisterAbility("Vase of Greed", "Açgözlülük Vazosu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Bu mührü taşıyan bir büyü oynandığında mevcut elini at ve 4 yeni kart çek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Cüceleştirme", Language.Turkish);
            RegisterAbility("Gnomification", "Cüceleştirme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Bir Cüce kartı çağırmak için bir yuva seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Lanetli", Language.Turkish);
            RegisterAbility("Cursed", "Lanetli");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Bu mührü taşıyan bir büyü oynandığında hemen ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "İlham", Language.Turkish);
            RegisterAbility("Inspiration", "İlham");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Bir kart seç; 1 tur boyunca Uçuşan + Ganimetçi kazansın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Kalkülüs", Language.Turkish);
            RegisterAbility("Calculus", "Kalkülüs");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Niteliklerini yer değiştirmek için bir kart seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Hiddet", Language.Turkish);
            RegisterAbility("Rage", "Hiddet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Öldürülecek bir kart seç. O kartın rakibi, kartın sahip olduğu can kadar hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Ateş Topu", Language.Turkish);
            RegisterAbility("Fireball", "Ateş Topu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "2 hasar alacak bir kart seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Buz Gibi Dokunuş", Language.Turkish);
            RegisterAbility("Cold to the Touch", "Buz Gibi Dokunuş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Bu mührü taşıyan kart başka bir karta saldırdığında hedef 1 saldırı kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Donmuş", Language.Turkish);
            RegisterAbility("Frozen", "Donmuş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "Her turun sonunda bu kart donmuş canını kaybeder. Donmuş canın tamamı tükendiğinde veya bu kart darbe aldığında buzu çözülür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Güçlü Çekim", Language.Turkish);
            RegisterAbility("Strong Pull", "Güçlü Çekim");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Her rakip kartı, diğer kartlar yerine bu karta vurmaya yönelir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Yer Değiştirme", Language.Turkish);
            RegisterAbility("Displacement", "Yer Değiştirme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Bu mührü taşıyan kart çekildiğinde aynı karttan bir tane daha destene rastgele bir konumda eklenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Cevher Hesaplaşması", Language.Turkish);
            RegisterAbility("Gem Reckoning", "Cevher Hesaplaşması");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "Her turun sonunda bu kartın sahibi hiçbir cevheri kontrol etmiyorsa elindeki en soldaki kart atılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Güç Taşı Gücü", Language.Turkish);
            RegisterAbility("Mox Power", "Güç Taşı Gücü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Bu mührün gösterdiği değer, sahibinin masanın kendi tarafındaki Güç Taşı Kartlarının sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Güç Taşı Canı", Language.Turkish);
            RegisterAbility("Mox Health", "Güç Taşı Canı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Bu mührün gösterdiği değer, sahibinin masanın kendi tarafındaki Güç Taşı Kartlarının sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Muma Yakınlık", Language.Turkish);
            RegisterAbility("Candle Proximity", "Muma Yakınlık");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "Bu mührün gösterdiği değer, kartın masadaki muma ne kadar yakın olduğuna bağlıdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Katliam Gücü", Language.Turkish);
            RegisterAbility("Murder Power", "Katliam Gücü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "Bu mührün gösterdiği değer, rakibin oyun tahtasındaki toplam güce eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "Bu mührün gösterdiği değer, senin oyun tahtandaki toplam gücün yarısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Büyü Gücü", Language.Turkish);
            RegisterAbility("Spell Power", "Büyü Gücü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "Bu mührün gösterdiği değer, mevcut zindanda oynanan toplam büyü sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "Bu mührün gösterdiği değer, savaş boyunca oynanan toplam büyü sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Karşı Ateş Gücü", Language.Turkish);
            RegisterAbility("Counterbattery Power", "Karşı Ateş Gücü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "Bu mührün gösterdiği değer, bu savaşta aldığın hasarın ikiye bölünmüş hâline eşittir.", Language.Turkish);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, TurkishLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "güç taşı", Language.Turkish);
            RegisterCard("Mox", "güç taşı", "its a me moxio", "benim, moxio");
            RegisterCard("Ruby Mox", "Yakut Güç Taşı", "its a me moxio", "benim, moxio");
            RegisterCard("Emerald Mox", "Zümrüt Güç Taşı", "its a me moxio", "benim, moxio");
            RegisterCard("Sapphire Mox", "Safir Güç Taşı", "its a me moxio", "benim, moxio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "benim, moxio", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "Mızrak", Language.Turkish);
            RegisterCard("Spear", "Mızrak", "ayo", "hey");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "hey", Language.Turkish);
            RegisterCard("Mage Pupil", "Öğrenci Büyücü", "Though weak, it can always be useful in the right situation.", "Zayıf olsa da doğru durumda her zaman işe yarayabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "Zayıf olsa da doğru durumda her zaman işe yarayabilir.", Language.Turkish);
            RegisterCard("Junior Sage", "Genç Bilge", "Although simple, it can prove itself to be useful.", "Basit olsa da işe yaradığını gösterebilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "Basit olsa da işe yaradığını gösterebilir.", Language.Turkish);
            RegisterCard("Muscle Mage", "Kaslı Büyücü", "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Simyacının iksirlerinden çok fazla içerek gelişmiş kaslı bir ucube...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Simyacının iksirlerinden çok fazla içerek gelişmiş kaslı bir ucube...", Language.Turkish);
            RegisterCard("Green Mage", "Yeşil Büyücü", "It draws its power from the mana of the mox on the board.", "Gücünü oyun tahtasındaki güç taşlarının manasından alır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws its power from the mana of the mox on the board.", "Gücünü oyun tahtasındaki güç taşlarının manasından alır.", Language.Turkish);
            RegisterCard("Blue Mage", "Mavi Büyücü", "Never doubt its utility.", "İşe yararlığından asla şüphe etme.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never doubt its utility.", "İşe yararlığından asla şüphe etme.", Language.Turkish);
            RegisterCard("Blue Sporemage", "Mavi Mantarbaz", "", "");
            RegisterCard("Force Mage", "Güç Büyücüsü", "A mage, proficient in a martial stance which allows it block nearly anything..", "Neredeyse her şeyi engelleyebilen bir dövüş duruşunda ustalaşmış büyücü...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage, proficient in a martial stance which allows it block nearly anything..", "Neredeyse her şeyi engelleyebilen bir dövüş duruşunda ustalaşmış büyücü...", Language.Turkish);
            RegisterCard("Gem Fiend", "Cevherli İblis", "A wretched, unstable creature of gems. It can tear through anything.", "Sefil, dengesiz bir cevher yaratığı. Her şeyi parçalayabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wretched, unstable creature of gems. It can tear through anything.", "Sefil, dengesiz bir cevher yaratığı. Her şeyi parçalayabilir.", Language.Turkish);
            RegisterCard("Hover Mage", "Uçan Büyücü", "Using its spells it soars high to hit directly", "Büyülerini kullanarak yükseğe süzülür ve doğrudan vurur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells it soars high to hit directly", "Büyülerini kullanarak yükseğe süzülür ve doğrudan vurur.", Language.Turkish);
            RegisterCard("Mage Knight", "Büyücü Şövalye", "An intimidating and towering defense, however requiring gems to stay stable.", "Heybetli ve ürkütücü bir savunma, ancak dengesini korumak için cevherlere ihtiyaç duyar.");
