            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Çarpım Büyücüsü", Language.Turkish);
            RegisterCard("Multiplication mage", "Çarpım Büyücüsü", "This cycle can go on forever..", "Bu döngü sonsuza dek sürebilir...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Bu döngü sonsuza dek sürebilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Görünmez Büyücü", Language.Turkish);
            RegisterCard("Invisible mage", "Görünmez Büyücü", "It drank the wrong potion and ended up invisible. How clumsy.", "Yanlış iksiri içti ve görünmez oldu. Ne sakar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Yanlış iksiri içti ve görünmez oldu. Ne sakar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Kristal Bilgesi", Language.Turkish);
            RegisterCard("Crystal Sage", "Kristal Bilgesi", "A young scholar, profoundly studying mana crystals.", "Mana kristallerini derinlemesine inceleyen genç bir bilgin.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Mana kristallerini derinlemesine inceleyen genç bir bilgin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Cevher Muhafız", Language.Turkish);
            RegisterCard("Gem Guardian", "Cevher Muhafız", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Cevher Fünyesi'nin tersi; bu, tüm güç taşlarını korumaya çalışır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Cevher Fünyesi'nin tersi; bu, tüm güç taşlarını korumaya çalışır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Cevherli Deşici", Language.Turkish);
            RegisterCard("Gembound Ripper", "Cevherli Deşici", "It is unstable, but such is the price for unending power.", "Dengesizdir, ama bitmeyen gücün bedeli budur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "Dengesizdir, ama bitmeyen gücün bedeli budur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Cevher Yutucu", Language.Turkish);
            RegisterCard("Gem Absorber", "Cevher Yutucu", "It seeks out to consume all mana within Mox to grow stronger.", "Güçlenmek için Güç Taşlarındaki tüm manayı tüketmeye çalışır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Güçlenmek için Güç Taşlarındaki tüm manayı tüketmeye çalışır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Büyücü İskelet", Language.Turkish);
            RegisterCard("Skelemagus", "Büyücü İskelet", "Great power for a few, fleeting moments..", "Birkaç kısacık an boyunca muazzam güç...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Birkaç kısacık an boyunca muazzam güç...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Kemik Bilgesi", Language.Turkish);
            RegisterCard("Skelesage", "Kemik Bilgesi", "One of my own Junior Sages, lost and revived.", "Benim kendi Genç Bilgelerimden biri; kayboldu ve yeniden canlandı.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "Benim kendi Genç Bilgelerimden biri; kayboldu ve yeniden canlandı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Dengesiz Bilgin", Language.Turkish);
            RegisterCard("Erratic Scholar", "Dengesiz Bilgin", "A panicked scholar.. Always running from its problems..", "Panik içindeki bir bilgin... Hep sorunlarından kaçıyor...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Panik içindeki bir bilgin... Hep sorunlarından kaçıyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Güç Taşı Büyücüsü", Language.Turkish);
            RegisterCard("Mox Mage", "Güç Taşı Büyücüsü", "A Mox disguised as a mage.. It's not going to fool anyone.", "Büyücü kılığına girmiş bir Güç Taşı... Kimseyi kandıramayacak.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Büyücü kılığına girmiş bir Güç Taşı... Kimseyi kandıramayacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Altındokunuş", Language.Turkish);
            RegisterCard("Aurumtact", "Altındokunuş", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Açgözlülüğü yüzünden lanetlenmiş yaşlı bir bilgin; dokunduğu her şeyi saf altına gömer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Açgözlülüğü yüzünden lanetlenmiş yaşlı bir bilgin; dokunduğu her şeyi saf altına gömer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Zincirli Güç Taşı", Language.Turkish);
            RegisterCard("Chained Mox", "Zincirli Güç Taşı", "A collection of 3 moxen, tangled together, combining their mana energy.", "Birbirine dolanmış 3 güç taşından oluşan bir topluluk; mana enerjilerini birleştirirler.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Birbirine dolanmış 3 güç taşından oluşan bir topluluk; mana enerjilerini birleştirirler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Maux", Language.Turkish);
            RegisterCard("Maux", "Maux", "In all my years, I have NEVER seen an imitation cruder than this.", "Onca yıllık hayatımda bundan daha kaba bir taklidi ASLA görmedim.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "Onca yıllık hayatımda bundan daha kaba bir taklidi ASLA görmedim.", Language.Turkish);
            RegisterCard("Stim Mage", "Uyarılmış Büyücü", "It strives to grow stronger, disregarding its own wellbeing..", "Kendi iyiliğini hiçe sayarak güçlenmeye çalışır...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Kendi iyiliğini hiçe sayarak güçlenmeye çalışır...", Language.Turkish);
            RegisterCard("Gourmage", "İlik Büyücüsü", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Güçlenmek için senin düşmüşlerinin cesetlerini yiyen obur bir büyücü... İğrenç.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Güçlenmek için senin düşmüşlerinin cesetlerini yiyen obur bir büyücü... İğrenç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Budala Büyücü", Language.Turkish);
            RegisterCard("Dunce", "Budala Büyücü", "This one can never seem to hit its target..", "Bu, hedefini hiç vuramıyor gibi...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Bu, hedefini hiç vuramıyor gibi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Grootslang", Language.Turkish);
            RegisterCard("Grootslang", "Grootslang", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Dişlerinin hafifçe sıyırması bile her yaratığı öldürmeye yeter. Boyutu ne olursa olsun.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Dişlerinin hafifçe sıyırması bile her yaratığı öldürmeye yeter. Boyutu ne olursa olsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Kitap Kurdu", Language.Turkish);
            RegisterCard("Bookworm", "Kitap Kurdu", "A rare kind of insect that absorbs knowledge out of books.", "Kitaplardan bilgi emen nadir bir böcek türü.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Kitaplardan bilgi emen nadir bir böcek türü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Simyacı", Language.Turkish);
            RegisterCard("Alchemist", "Simyacı", "A supporting one. It brews potions to empower your cards.", "Bir destekçi. Kartlarını güçlendirmek için iksirler hazırlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Bir destekçi. Kartlarını güçlendirmek için iksirler hazırlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Çan Büyücüsü", Language.Turkish);
            RegisterCard("Chime Mage", "Çan Büyücüsü", "Its chime can prove to be quite annoying..", "Çınlaması oldukça sinir bozucu olabilir...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Çınlaması oldukça sinir bozucu olabilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Yeniden Dirilen", Language.Turkish);
            RegisterCard("Revivor", "Yeniden Dirilen", "It brings a mage back from the dead, at the cost of its own health.", "Kendi canı pahasına bir büyücüyü ölümden döndürür.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Kendi canı pahasına bir büyücüyü ölümden döndürür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Rün Büyücüsü", Language.Turkish);
            RegisterCard("Rune Mage", "Rün Büyücüsü", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Çağrıldığında yanına patlayıcı rünler yaratır. Söylemeliyim ki pek iyi bir fikir değil.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Çağrıldığında yanına patlayıcı rünler yaratır. Söylemeliyim ki pek iyi bir fikir değil.", Language.Turkish);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "İşte geliyor.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "İşte geliyor.", Language.Turkish);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "Gelişini önceden gördüm.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "Gelişini önceden gördüm.", Language.Turkish);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Nihayet burada.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Nihayet burada.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Keskin Nişancı Bilge", Language.Turkish);
            RegisterCard("Sniper Sage", "Keskin Nişancı Bilge", "A mage whose training allows it to cast spells from afar.", "Eğitimi sayesinde uzaktan büyü yapabilen bir büyücü.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Eğitimi sayesinde uzaktan büyü yapabilen bir büyücü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Rün", Language.Turkish);
            RegisterCard("Rune", "Rün", "This is the last call, for alcohol.", "İçki için son sipariş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "İçki için son sipariş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Büyülü Alev", Language.Turkish);
            RegisterCard("Flame", "Büyülü Alev", "This is the last call, for alcohol.", "İçki için son sipariş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "İçki için son sipariş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Tavşan", Language.Turkish);
            RegisterCard("Rabbit", "Tavşan", "This is the last call, for alcohol.", "İçki için son sipariş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "İçki için son sipariş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "İçki için son sipariş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Bira için son sipariş.", Language.Turkish);
            RegisterCard("Master Goranj", "Usta Turuncil", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "Heybetli Usta Turuncil. Yalnızca korkunç büyüler yapmakla kalmaz, sağlam bir duruşa da sahiptir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "Heybetli Usta Turuncil. Yalnızca korkunç büyüler yapmakla kalmaz, sağlam bir duruşa da sahiptir.", Language.Turkish);
            RegisterCard("Master Bleene", "Usta Mavşil", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "Fedakâr Usta Mavşil. Büyük ihtiyaç anlarında sana yardım eder... Kendi savunma yeteneği pahasına. Takdire değer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "Fedakâr Usta Mavşil. Büyük ihtiyaç anlarında sana yardım eder... Kendi savunma yeteneği pahasına. Takdire değer.", Language.Turkish);
            RegisterCard("Master Orlu", "Usta Mavuncu", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Solgun kanatlarıyla süzülen büyük Usta Mavuncu; yukarıdan saldırır ve aşağıdan kart çeker...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Solgun kanatlarıyla süzülen büyük Usta Mavuncu; yukarıdan saldırır ve aşağıdan kart çeker...", Language.Turkish);
            RegisterCard("Master Magnus", "Yüce Usta Magnus", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Benim adım... Shake-Zula! Mikrofonun kralı! Eski okulun ustası! Yolculuk mu istiyorsun? Sana getiririm...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Benim adım... Shake-Zula! Mikrofonun kralı! Eski okulun ustası! Yolculuk mu istiyorsun? Sana getiririm...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "Yüce Usta Magnus", Language.Turkish);
            RegisterCard("Master Magnus", "Yüce Usta Magnus", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, evet, zirvedeyim; polis gibi sarsarım seni. Meatwad, sıra sende, çal bakalım kapıyı!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, evet, zirvedeyim; polis gibi sarsarım seni. Meatwad, sıra sende, çal bakalım kapıyı!", Language.Turkish);
            RegisterCard("Master Magnus", "Yüce Usta Magnus", "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad parayı götürür, anladın mı? Meatwad kızları kapar, dostum.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad parayı götürür, anladın mı? Meatwad kızları kapar, dostum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "Anka Kuşu", Language.Turkish);
            RegisterCard("Phoenix", "Anka Kuşu", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Bir zamanlar Usta Mavuncu'nun suç ortağı olduğu söylenen görkemli bir kuş...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Bir zamanlar Usta Mavuncu'nun suç ortağı olduğu söylenen görkemli bir kuş...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "Mavşil Tazısı", Language.Turkish);
            RegisterCard("Bleenehound", "Mavşil Tazısı", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Bir zamanlar Usta Mavşil'in sadık yoldaşı olduğu söylenen vefalı bir köpek.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Bir zamanlar Usta Mavşil'in sadık yoldaşı olduğu söylenen vefalı bir köpek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "Simyaya Giriş", Language.Turkish);
