            RegisterCard("Ethereal Gems", "Eterik Cevherler", "A frail spirit of a late magnus mox.. Only sustains for a turn.", "Ölmüş bir Kadim Güç Taşı'nın narin ruhu... Yalnızca bir tur dayanır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frail spirit of a late magnus mox.. Only sustains for a turn.", "Ölmüş bir Kadim Güç Taşı'nın narin ruhu... Yalnızca bir tur dayanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Açgözlülük Vazosu", Language.Turkish);
            RegisterCard("Vase of Greed", "Açgözlülük Vazosu", "The vase of greed.. Look at its smug face..", "Açgözlülük vazosu... Şu kendini beğenmiş suratına bak...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vase of greed.. Look at its smug face..", "Açgözlülük vazosu... Şu kendini beğenmiş suratına bak...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Cüceleştirme", Language.Turkish);
            RegisterCard("Gnomification", "Cüceleştirme", "Conjure a plain old garden gnome on the board..", "Oyun tahtasına bildiğin eski bir bahçe cücesi çağır...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure a plain old garden gnome on the board..", "Oyun tahtasına bildiğin eski bir bahçe cücesi çağır...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Skull", "Lanetli Kafatası", Language.Turkish);
