            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "İlham", Language.Turkish);
            RegisterCard("Inspiration", "İlham", "A culmination of the great Master Orlu's essence.", "Büyük Usta Mavuncu'nun özünün birleşimi.");
