            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of the brave Master Bleene.", "Cesur Usta Mavşil'in ruhu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Ateş Topu", Language.Turkish);
            RegisterCard("Fireball", "Ateş Topu", "Conjure up a fireball, and shoot it towards your enemy.", "Bir ateş topu yarat ve düşmanına fırlat.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Bir ateş topu yarat ve düşmanına fırlat.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potion", "İksir", Language.Turkish);
            RegisterCard("Potion", "İksir", "Conjure up a fireball, and shoot it towards your enemy.", "Bir ateş topu yarat ve düşmanına fırlat.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Bir ateş topu yarat ve düşmanına fırlat.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnome", "Cüce", Language.Turkish);
            RegisterCard("Gnome", "Cüce", "joem", "joem");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "joem", "joem", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuba Gnome", "Dalgıç Cüce", Language.Turkish);
