            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huber", "Huber", Language.Turkish);
            RegisterCard("Free Legs", "Özgür Bacaklar", "", "");
