            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knight, the assassin in hell.", "Ölüm Şövalyesi, cehennemdeki suikastçı.", Language.Turkish);
