            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ferry Crow", "Uyanmış Kayıkçı Kuzgun", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mournful cry of looking down upon the undead after death.", "Ölümün ardından yaşayan ölülere yukarıdan bakanın kederli çığlığı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave", "Mezar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope no one will disturb it.", "Umarım kimse onu rahatsız etmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Man", "Başsız Adam", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An incompetent headless person, as if searching for something he had lost.", "Kaybettiği bir şeyi arar gibi görünen beceriksiz, başsız bir kişi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Kennel", "Uyanmış Köpek Kulübesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dog house, hopefully no one will mess with the things inside.", "Bir köpek kulübesi. Umarım kimse içindekileri kurcalamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharmacist", "Eczacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Pharmacist", "Uyanmış Eczacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead pharmacist who poisons all creations that oppose him.", "Kendisine karşı çıkan tüm yaratımları zehirleyen ölü bir eczacı.", Language.Turkish);
