            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton leader, once on stage, is surrounded by skeletons.", "Sahneye çıkar çıkmaz etrafı iskeletlerle çevrilen bir iskelet lideri.", Language.Turkish);
