    public class CustomSideDeckMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for CustomSideDeck Mod");
            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How the mod should handle side deck card backs for side decks that don't add their own custom card back. If enabled, automatically generates a unique card back based on the side deck's main card's portrait. Otherwise, the default squirrel back will be used.", "Kendi özel kart arkasını eklemeyen yan destelerin kart arkalarının nasıl ele alınacağını belirler. Etkinse yan destenin ana kartının portresinden otomatik olarak benzersiz bir kart arkası oluşturulur. Aksi hâlde varsayılan sincap arkası kullanılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether to automatically add an Aqua version of all custom side decks. Buggy, not recommended.", "Tüm özel yan destelerin Islak sürümünün otomatik eklenip eklenmeyeceği. Hatalıdır, önerilmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether or not Aquasquirrels and custom side decks marked as `CSDIsAqua` should be shown as options even when the Squirrel Fish challenge isn't on.", "Sincap Balıklar mücadelesi kapalıyken bile Islak Sincapların ve `CSDIsAqua` olarak işaretlenen özel yan destelerin seçenek olarak gösterilip gösterilmeyeceği.", Language.Turkish);

            // ShowText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Side Deck", "Yan Deste Seç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Configure Side Deck", "Yan Desteyi Ayarla", Language.Turkish);
            for (int point = 0; point <= 100; point++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>" + point.ToString() + "</color> Challenge Points", "GEÇERLİ YAN DESTE: <color=#eef4c6>" + point.ToString() + "</color> Meydan Okuma Puanı", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>+" + point.ToString() + "</color> Challenge Points", "GEÇERLİ YAN DESTE: <color=#eef4c6>+" + point.ToString() + "</color> Meydan Okuma Puanı", Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Challenge Points: <color=#eef4c6>" + point.ToString() + "</color>", "Toplam Meydan Okuma Puanı: <color=#eef4c6>" + point.ToString() + "</color>", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\nContains {0} cards", "\n{0} kart içerir", Language.Turkish); // todo

        }
    }

    public class PackManagementMod
    {

        public static Dictionary<string, string> EncountersTitle = new();
        public static Dictionary<string, KeyValuePair<string, string>> EncountersDescription = new();

        public static void RegisterEncounter(string en, string zh, string endes, string zhdes)
        {
            EncountersTitle.Add(en, zh);
            EncountersDescription.Add(en, new KeyValuePair<string, string>(endes, zhdes));
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PackManagement Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Card Packs", "Kart Paketlerini Seç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Encounter Packs", "Karşılaşma Paketlerini Seç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Active Packs", "Etkin Paketleri Seç", Language.Turkish);

            // Packs
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Card Expansion Pack", "Inscryption: Canavar Kartları Genişletme Paketi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "Leshy'nin kulübesindeki orijinal kart seti. Kurtlar, peygamberdeveleri ve arada bir hamamböceği içerir.", Language.Turkish);
            RegisterEncounter("Inscryption: Beastly Card Expansion Pack", "Inscryption: Canavar Kartları Genişletme Paketi", "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "Leshy'nin kulübesindeki orijinal kart seti. Kurtlar, peygamberdeveleri ve arada bir hamamböceği içerir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Techno Card Expansion Pack", "Inscryption: Teknolojik Kartlar Genişletme Paketi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of robotic cards, exclusively using the energy mechanic.", "Yalnızca enerji mekaniğini kullanan orijinal robot kartları seti.", Language.Turkish);
            RegisterEncounter("Inscryption: Techno Card Expansion Pack", "Inscryption: Teknolojik Kartlar Genişletme Paketi", "The original set of robotic cards, exclusively using the energy mechanic.", "Yalnızca enerji mekaniğini kullanan orijinal robot kartları seti.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Undead Card Expansion Pack", "Inscryption: Ölü Kartları Genişletme Paketi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrimoraMod", "GrimoraMod", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Ölülerin kemiklerinden güç alan bu kartlar, senin için savaşmak üzere mezardan döndü.", Language.Turkish);
            RegisterEncounter("Inscryption: Undead Card Expansion Pack", "Inscryption: Ölü Kartları Genişletme Paketi", "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Ölülerin kemiklerinden güç alan bu kartlar, senin için savaşmak üzere mezardan döndü.");
            RegisterEncounter("GrimoraMod", "GrimoraMod", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Magickal Card Expansion Pack", "Inscryption: Büyülü Kartlar Genişletme Paketi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Çıraklar çağırmak ve en onurlu düellolarda savaşmak için güç taşlarının kudretini kullan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels. (Magnificus Mod Cards)", "Çıraklar çağırmak ve en onurlu düellolarda savaşmak için güç taşlarının kudretini kullan. (Magnificus Modu Kartları)", Language.Turkish);
            RegisterEncounter("Inscryption: Magickal Card Expansion Pack", "Inscryption: Büyülü Kartlar Genişletme Paketi", "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Çıraklar çağırmak ve en onurlu düellolarda savaşmak için güç taşlarının kudretini kullan.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miscellaneous Community Cards", "Çeşitli Topluluk Kartları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Modlarla eklenen ama paketlere düzgünce ayrılmayan sıra dışı, düzensiz ve ele avuca sığmaz kartlar.", Language.Turkish);
            RegisterEncounter("Miscellaneous Community Cards", "Çeşitli Topluluk Kartları", "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Modlarla eklenen ama paketlere düzgünce ayrılmayan sıra dışı, düzensiz ve ele avuca sığmaz kartlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Encounters", "Inscryption: Canavar Karşılaşmaları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "Leshy'nin ideal oyun deneyimi için özenle hazırladığı orijinal [summary] seti.", Language.Turkish);
            RegisterEncounter("Inscryption: Beastly Encounters", "Inscryption: Canavar Karşılaşmaları", "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "Leshy'nin ideal oyun deneyimi için özenle hazırladığı orijinal [summary] seti.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unsorted Regions and Encounters", "Sınıflandırılmamış Bölgeler ve Karşılaşmalar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These [summary] have been added by mods but not properly sorted into packs.", "Bu [summary], modlarla eklendi ama paketlere düzgünce ayrılmadı.", Language.Turkish);
            RegisterEncounter("Unsorted Regions and Encounters", "Sınıflandırılmamış Bölgeler ve Karşılaşmalar", "These [summary] have been added by mods but not properly sorted into packs.", "Bu [summary], modlarla eklendi ama paketlere düzgünce ayrılmadı.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri Card Expansion", "Eri'nin Kart Genişletmesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From the [randomcard] to the [randomcard], this pack contains [count] wild animals that feel right at home in the wild world of Inscryption.", "[randomcard] ile [randomcard] arasındaki bu paket, Inscryption'ın vahşi dünyasında kendini evinde hisseden [count] vahşi hayvan içerir.", Language.Turkish); // todo
