            MagnificusMod.RegisterCard("Angry Witch", "Öfke Cadısı", "The witch in charge of anger will ignite flames in the opposite battlefield.", "Öfkeyi yöneten cadı, karşı savaş alanında alevler yakacak.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "Öfkeyi yöneten cadı, karşı savaş alanında alevler yakacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "Kibir Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Arrogant Witch", "Kibir Cadısı", "The witch who mastered the power of arrogance appeared with the demon.", "Kibrin gücüne hükmeden cadı, iblisle birlikte ortaya çıktı.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "Kibrin gücüne hükmeden cadı, iblisle birlikte ortaya çıktı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "Kahve Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Coffee Mage", "Kahve Büyücüsü", "Mages who love coffee use gems to regulate their breath.", "Kahveyi seven büyücüler, nefeslerini düzenlemek için cevher kullanır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "Kahveyi seven büyücüler, nefeslerini düzenlemek için cevher kullanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "Komik Büyülü Tavuk", Language.Turkish);
            MagnificusMod.RegisterCard("Funny MagiChiking", "Komik Büyülü Tavuk", "A smelly Rooster who has learned magic.", "Büyü öğrenmiş, pis kokulu bir horoz.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "Büyü öğrenmiş, pis kokulu bir horoz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "Oburluk Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Gluttonous Witch", "Oburluk Cadısı", "The witch in charge of gluttony committed a terrible sin.", "Oburluğu yöneten cadı, korkunç bir günah işledi.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "Oburluğu yöneten cadı, korkunç bir günah işledi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "Açgözlülük Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Greedy Witch", "Açgözlülük Cadısı", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Açgözlülüğün gücünü yöneten cadı, ne yazık ki ancak öldükten sonra bize değer katabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Açgözlülüğün gücünü yöneten cadı, ne yazık ki ancak öldükten sonra bize değer katabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "Hırs Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Inquisitive Witch", "Hırs Cadısı", "Nothing is more powerful than her curiosity.", "Hiçbir şey onun merakından güçlü değildir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "Hiçbir şey onun merakından güçlü değildir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Kıskançlık Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Jealous Witch", "Kıskançlık Cadısı", "The witch in charge of jealousy has powerful magic and power.", "Kıskançlığı yöneten cadı, kuvvetli büyüye ve güce sahiptir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "Kıskançlığı yöneten cadı, kuvvetli büyüye ve güce sahiptir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Tembellik Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Lazy Witch", "Tembellik Cadısı", "The witch in charge of the power of laziness is really a lazy guy.", "Tembelliğin gücünü yöneten cadı, gerçekten de tembel biridir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "Tembelliğin gücünü yöneten cadı, gerçekten de tembel biridir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Şehvet Cadısı", Language.Turkish);
            MagnificusMod.RegisterCard("Lust Witch", "Şehvet Cadısı", "The witch in charge of lust, don't look into her eyes.", "Şehveti yöneten cadı. Gözlerine bakma.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "Şehveti yöneten cadı. Gözlerine bakma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Dokuz Renkli Geyik", Language.Turkish);
            MagnificusMod.RegisterCard("Nine Color Deer", "Dokuz Renkli Geyik", "The colorful nine color deer has precious value.", "Rengârenk, dokuz renkli geyik çok değerlidir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "Rengârenk, dokuz renkli geyik çok değerlidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Kokmuş Sihirli Tavukçuk", Language.Turkish);
