            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Kendini patlatsa bile başkalarına asla boyun eğmez.", Language.Turkish);
