            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Aşçılıkta usta, esprili bir büyücü. Peyniri büyülü güce sahiptir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Buz Golemi", Language.Turkish);
            MagnificusMod.RegisterCard("Frost Golem", "Buz Golemi", "Once on the field, there is a strong sense of oppression.", "Oyun alanına çıkar çıkmaz güçlü bir baskı hissedilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "Oyun alanına çıkar çıkmaz güçlü bir baskı hissedilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Beyzbol Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Baseball Mage", "Beyzbol Büyücüsü", "His soul is bound under sportswear and can never be liberated.", "Ruhu spor giysilerinin altında hapsolmuştur ve asla özgür kalamaz.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Ruhu spor giysilerinin altında hapsolmuştur ve asla özgür kalamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Baskın Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Raid Mage", "Baskın Büyücüsü", "You will understand how terrifying it is for a robber to master magic.", "Bir haydudun büyüde ustalaşmasının ne kadar korkunç olduğunu anlayacaksın.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Bir haydudun büyüde ustalaşmasının ne kadar korkunç olduğunu anlayacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Yeşim Kaplumbağa", Language.Turkish);
            MagnificusMod.RegisterCard("Jade Turtle", "Yeşim Kaplumbağa", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Baştan ayağa zümrütlerle örtülü bir kaplumbağa. Böyle bir resmin var olduğuna bile hayret etmeden duramıyorum.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Baştan ayağa zümrütlerle örtülü bir kaplumbağa. Böyle bir resmin var olduğuna bile hayret etmeden duramıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Büyülü Peynir", Language.Turkish);
            MagnificusMod.RegisterCard("Magic Cheese", "Büyülü Peynir", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Al Guguk Kuşu", Language.Turkish);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Al Guguk Kuşu", "The success or failure of the angry magic bird often depends on its face.", "Öfkeli büyülü kuşun başarısı ya da başarısızlığı çoğunlukla yüz ifadesine bağlıdır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Öfkeli büyülü kuşun başarısı ya da başarısızlığı çoğunlukla yüz ifadesine bağlıdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Mızrak Çırağı", Language.Turkish);
            MagnificusMod.RegisterCard("Spear Apprentice", "Mızrak Çırağı", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Mızrak Büyücülerinin çırakları. Bilge kişiler her zaman yedek bir plan hazırlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Mızrak Büyücülerinin çırakları. Bilge kişiler her zaman yedek bir plan hazırlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "Karanlığın Gözü", Language.Turkish);
            MagnificusMod.RegisterCard("The Eye of Darkness", "Karanlığın Gözü", "This precious pearl was once the devil's eye.", "Bu değerli inci, bir zamanlar şeytanın gözüydü.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Bu değerli inci, bir zamanlar şeytanın gözüydü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Orman Büyüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Forest Spell", "Orman Büyüsü", "The forest spell obtained from Leshy can provide the most primitive defense.", "Leshy'den alınan orman büyüsü, en ilkel savunmayı sağlayabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "Leshy'den alınan orman büyüsü, en ilkel savunmayı sağlayabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Güç Taşı Kalkanı", Language.Turkish);
            MagnificusMod.RegisterCard("MoxShield", "Güç Taşı Kalkanı", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Cevherlerle süslü büyülü bir kalkan, varlığıyla daima güven hissi verir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Cevherlerle süslü büyülü bir kalkan, varlığıyla daima güven hissi verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Bulutsu Fırtınası", Language.Turkish);
            MagnificusMod.RegisterCard("Nebula Storm", "Bulutsu Fırtınası", "This cruel storm can directly take away an enemy.", "Bu acımasız fırtına bir düşmanı doğrudan alıp götürebilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Bu acımasız fırtına bir düşmanı doğrudan alıp götürebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Ruh Sözleşmesi", Language.Turkish);
            MagnificusMod.RegisterCard("Soul Contract", "Ruh Sözleşmesi", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Belki daha fazla kart desteğine ihtiyacın vardır. Bir ruh sözleşmesi harika bir seçimdir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Belki daha fazla kart desteğine ihtiyacın vardır. Bir ruh sözleşmesi harika bir seçimdir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Ağlama Duvarı", Language.Turkish);
            MagnificusMod.RegisterCard("Wailing Wall", "Ağlama Duvarı", "Such perseverance even moves the thorny walls to weep.", "Böyle bir azim, dikenli duvarları bile ağlatır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Böyle bir azim, dikenli duvarları bile ağlatır.", Language.Turkish);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Kahve Zamanı", Language.Turkish);
            MagnificusMod.RegisterAbility("Coffee Time", "Kahve Zamanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "[creature] ilk kez hasar aldığında 2 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Kibrin Ölümü", Language.Turkish);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Kibrin Ölümü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "[creature] öldüğünde bitişik kartlar 2 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Açgözlülüğün Ölümü", Language.Turkish);
            MagnificusMod.RegisterAbility("Death of Greed", "Açgözlülüğün Ölümü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "[creature] öldüğünde bitişik kartlar 3 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Tanrı Yapımı", Language.Turkish);
            MagnificusMod.RegisterAbility("God Made", "Tanrı Yapımı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "[creature] oynandığında bitişikteki her boş alanda bir Homunkulus oluşturulur. Homunkulusun özellikleri: 1 güç, 1 can, Büyü Yoldaşı.", Language.Turkish);
            MagnificusMod.RegisterAbility("Fir Caller", "Köknar Çağıran");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "[creature] öldüğünde sahibinin tarafındaki boş alanlar Büyük Köknarlarla dolar. Büyük Köknarın özellikleri: 0 güç, 3 can, Güçlü Sıçrayış.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Kalıcı Tat", Language.Turkish);
            MagnificusMod.RegisterAbility("Lingering Taste", "Kalıcı Tat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "[creature] öldüğünde bitişik kartlar 1 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Peynir Sevgisi", Language.Turkish);
            MagnificusMod.RegisterAbility("Love of Cheese", "Peynir Sevgisi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "[creature] oynandığında bir Peynir kartı çek. Peynirin özellikleri: 0 güç, 2 can, Kalıcı Tat.", Language.Turkish);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Büyü Genişletmesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "Fantastik dünyanın kartları geldi! İleride daha fazla içerik eklenecek!", Language.Turkish);
        }
    }
