            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You slay the glimmering creature, stealing its pelt.", "Işıldayan yaratığı öldürüp postunu alırsın.", Language.Turkish);
