            P03InKayceesModMod.RegisterCardPart("Sparkplug", "Buji");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splice Conduit", "Birleştirme Borusu", Language.Turkish);
