            P03InKayceesModMod.RegisterCardPart("Bolthound", "Robotazı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explode Bot", "Patlar Bot", Language.Turkish);
            RegisterCard("Explode Bot", "Patlar Bot");
            P03InKayceesModMod.RegisterCardPart("Explode", "Patlama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Null Conduit", "Boş Boru", Language.Turkish);
            RegisterCard("Null Conduit", "Boş Boru");
            P03InKayceesModMod.RegisterCardPart("Null", "Boş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multi Gunner", "Çoklu Nişancı", Language.Turkish);
            RegisterCard("Multi Gunner", "Çoklu Nişancı");
            P03InKayceesModMod.RegisterCardPart("Multi", "Çoklu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Module", "Güç Taşı Modülü", Language.Turkish);
            RegisterCard("Mox Module", "Güç Taşı Modülü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Latcher", "Bomba Takar", Language.Turkish);
            RegisterCard("Bomb Latcher", "Bomba Takar");
            P03InKayceesModMod.RegisterCardPart("Bomb", "Bomba");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield Latcher", "Kalkan Takar", Language.Turkish);
            RegisterCard("Shield Latcher", "Kalkan Takar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skel-E-Latcher", "İskelet Takar", Language.Turkish);
            RegisterCard("Skel-E-Latcher", "İskelet Takar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "L33pBot", "H0pB0t", Language.Turkish);
            RegisterCard("L33pBot", "H0pB0t");
            P03InKayceesModMod.RegisterCardPart("L33pBot", "Zıplama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DummyCard", "Kukla Kartı", Language.Turkish);
            RegisterCard("DummyCard", "Kukla Kartı");
            P03InKayceesModMod.RegisterCardPart("DummyCard", "Kukla Kartı");
            // Card: Talking
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painbot", "Acı Botu", Language.Turkish);
            RegisterCard("Painbot", "Acı Botu");
            P03InKayceesModMod.RegisterCardPart("Pain", "Acı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melter", "Eritici", Language.Turkish);
            RegisterCard("Melter", "Eritici");
            P03InKayceesModMod.RegisterCardPart("Melter", "Eritici");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogbot", "Köpek Botu", Language.Turkish);
            RegisterCard("Dogbot", "Köpek Botu");
            P03InKayceesModMod.RegisterCardPart("Dog", "Robot Köpek");

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Lütfen! Buradan çıkmama yardım etmelisin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you! I hope he doesn't notice me here...", "Teşekkürler! Umarım beni burada fark etmez...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Teşekkürler!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much power, but so much pain...", "Ne kadar çok güç, ama ne kadar çok acı...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good riddance to that little freak.", "O küçük ucubeden kurtulduk, çok şükür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "Goobert", Language.Turkish);
            RegisterConsumable("Goobert", "Goobert");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Lütfen! Buradan çıkmama yardım etmelisin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Cube", "Veri Küpü", Language.Turkish);
            RegisterConsumable("Data Cube", "Veri Küpü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can be placed on the scales for some damage, if you're into that sort of thing.", "Hoşuna gidiyorsa biraz hasar vermek için teraziye konabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laser Rifle", "Lazer Tüfeği", Language.Turkish);
            RegisterConsumable("Laser Rifle", "Lazer Tüfeği");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will give one of your cards the Sniper sigil for the rest of the battle. It's a gun - what else do you want?", "Kartlarından birine savaşın sonuna kadar Nişancı mührü verir. Bu bir silah; daha ne istiyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amplification Coil", "Güçlendirme Bobini", Language.Turkish);
            RegisterConsumable("Amplification Coil", "Güçlendirme Bobini");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases your max energy by 2. I suppose you can find some use for this.", "Azami enerjini 2 artırır. Sanırım bir işe yarar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UFO", "UFO", Language.Turkish);
            RegisterConsumable("UFO", "UFO");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abducts a card of your choice. It gets the job done I suppose", "Seçtiğin bir kartı kaçırır. Sanırım işini görür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wiseclock", "İşler Saat", Language.Turkish);
            RegisterConsumable("Wiseclock", "İşler Saat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rotates the board clockwise or something. I stole it from Leshy. Do you think he'll notice?", "Oyun tahtasını saat yönünde falan döndürür. Leshy'den çaldım. Sence fark eder mi?", Language.Turkish);

            // Rule
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I play a Mr:Clock", "Bir Saat:Bay oynuyorum", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a random card becomes a fish", "rastgele bir kart balığa dönüşür", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 of your lanes catches fire", "1 hattın alev alır", Language.Turkish);

            // Mode
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traps", "Tuzaklar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems there are some [c:bR]traps[c:] here", "Görünüşe göre burada [c:bR]tuzaklar[c:] var", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bots will have to fight past them to get to me", "Botların bana ulaşmak için onların arasından geçerek savaşmalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Rule", "Rastgele Kural", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For this battle, I'm going to add an additional rule.", "Bu savaş için ek bir kural ekleyeceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conveyor", "Taşıma Bandı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears someone activated the [c:bR]conveyor belt[c:]", "Görünüşe göre biri [c:bR]taşıma bandını[c:] çalıştırdı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards will rotate clockwise every turn", "Kartlar her tur saat yönünde dönecek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "Patlayıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm; it looks like the cards in this battle will [c:bR]explode[c:] when they die", "Hmm; görünüşe göre bu savaşta kartlar öldüklerinde [c:bR]patlayacak[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems dangerous", "Bu tehlikeli görünüyor", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stickers", "Çıkartmalar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See those [c:bR]stickers[c:]? They give my cards extra abilities.", "Şu [c:bR]çıkartmaları[c:] görüyor musun? Kartlarıma ek yetenekler veriyorlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't mind an extra challenge, do you?", "Fazladan bir mücadeleye itirazın yoktur, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missiles", "Füzeler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, there appears to be a malfunctioning missile launcher here", "Aa, burada arızalı bir füze fırlatıcı var gibi görünüyor", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for rogue missile strikes I guess", "Sanırım başıboş füze saldırılarına dikkat etmelisin", Language.Turkish);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss", "Son Boss", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Description for the Final Boss challenge", "Son Patron mücadelesinin açıklaması", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missing Remote", "Kayıp Kumanda", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not start with Mrs. Bomb's Remote", "Oyuna Bayan Bomba'nın Kumandası olmadan başlarsın", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbo Vessels", "Turbo Kaplar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your vessels have the Double Sprinter sigil.", "Kapların Çift Koşucu mührüne sahiptir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bridges", "Kırık Köprüler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only two regions are available at the start of each run", "Her koşunun başında yalnızca iki bölge kullanılabilir", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pricey Upgrades", "Pahalı Yükseltmeler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All upgrades cost more", "Tüm yükseltmeler daha pahalıdır", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eccentric Painter", "Tuhaf Ressam", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All bosses start with a random canvas rule.", "Tüm patronlar rastgele bir tuval kuralıyla başlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Hammer", "Enerji Çekici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hammer now costs 2 energy to use", "Çekici kullanmak artık 2 enerjiye mal olur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Costly Respawn", "Pahalı Yeniden Doğuş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cost for additional respawns is tripled", "Ek yeniden doğuşların maliyeti üç katına çıkar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Side Deck", "Sıçrayan Yan Deste", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replace your Empty Vessels with L33pbots.", "Boş Kaplarını H0pB0t'larla değiştir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wanted Fugitive", "Aranan Kaçak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bounty level is permanently increased by 2", "Ödül seviyen kalıcı olarak 2 artar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Encounters", "Tuhaf Karşılaşmalar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some battles on each map will have additional effects", "Her haritadaki bazı savaşlarda ek etkiler olur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Transcendence", "Muazzam Yükseliş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlock the secrets of the Great Transcendence", "Muazzam Yükseliş'in sırlarını açığa çıkar", Language.Turkish);

            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENTER NAME HERE", "ADI BURAYA GİR", Language.Turkish);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Redraw: $" + count.ToString(), "Yeniden çek: $" + count.ToString(), Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sell Token: " + count.ToString() + " Robobucks", "Jetonu sat: " + count.ToString() + " robopara", Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reset: $1", "Sıfırla: $1", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PRINT", "YAZDIR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RECALL", "GERİ ÇAĞIR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN", "JETON", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN++", "Jeton++", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE", "NADİR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE++", "NADİR++", Language.Turkish);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 In Kaycee's Mod", "Kaycee'nin Modunda P03", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uber Apocalypse", "Üstün Kıyamet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beat \"P03 in Kaycee's Mod\" for the first time", "«Kaycee'nin Modunda P03»ü ilk kez bitir", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Skull", "Kızıl Kafatası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win a run with every challenge skull from the first page enabled", "İlk sayfadaki tüm mücadele kafatasları etkinken bir koşuyu kazan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avatar", "Avatar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take ownership of one of G0lly's beloved trinkets", "G0lly'nin çok sevdiği biblolardan birini ele geçir", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Book of the Dead", "Ölüler Kitabı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "During The Archivist's boss fight, survive 6 turns during phase 2", "Arşivci ile patron savaşında 2. aşamada 6 tur hayatta kal", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feral Spirit", "Yabani Ruh", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Photographer without using the camera", "Fotoğrafçıyı kamerayı kullanmadan yen", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallery Showcase", "Galeri Sergisi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create an infinite loop in the Unfinished Boss fight", "Bitmemiş Patron savaşında sonsuz döngü oluştur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Frenzy", "Savaş Çılgınlığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Destroy 30 Bounty Hunters in your lifetime", "Toplam 30 ödül avcısını yok et", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calling for Backup", "Takviye Çağrısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete all NPC quests that appear in a single run", "Tek bir koşuda ortaya çıkan tüm NPC görevlerini tamamla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accelerated Fuse", "Hızlandırılmış Fitil", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock and destroy a card given to you by an NPC", "Bir NPC'den aldığın kartın dış iskeletini aşırı yükle ve kartı yok et", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Blink", "Mana Parlaması", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have six energy available on turn two", "İkinci turda altı kullanılabilir enerjin olsun", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aimless Assault", "Hedefsiz Saldırı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earn 15 Robobucks in a single battle", "Tek bir savaşta 15 robopara kazan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rebuild From Scrap", "Hurdadan Yeniden Yap", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card in your deck that is gemified, skeleclocked, transformable, and can complete a circuit", "Destende Cevherli, dış iskeleti aşırı yüklenmiş, dönüşebilen ve devre tamamlayabilen bir kart bulundur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buy Your Buddy", "Dostunu Satın Al", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give a card with the maximum amount of SP to the Bot Builder", "Bot Yapıcı'ya azami SP miktarına sahip bir kart ver", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me Smash", "Ben Ezer", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike P03 six separate times in a single turn", "Tek bir turda P03'e altı ayrı kez saldır", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolution", "Aklanma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have the scales tilted 4 points against you on three different turns", "Üç farklı turda terazinin aleyhine 4 puan eğilmesini sağla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Perfect Crime", "Kusursuz Suç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win five battles with bounty hunters without killing them", "Ödül avcılarını öldürmeden beş savaş kazan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blastenheimer 5000 Ultra Cannon", "Blastenheimer 5000 Ultra Top", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 6 damage with Plasma Jimmy in a single turn", "Tek bir turda Plazma Jimmy ile 6 hasar ver", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Time", "İki Kat Hız", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock every card in your deck", "Destendeki tüm kartların dış iskeletini aşırı yükle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One And The Same", "Bir ve Aynı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete the Mycologist's experiment and create an abomination of science", "Mikoloğun deneyini tamamla ve bilimin bir ucubesini yarat", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Adrenaline", "Yanan Adrenalin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repair the generator in four turns or less", "Jeneratörü dört turda veya daha kısa sürede onar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnival Clown", "Karnaval Palyaçosu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Achieve a high score of 50 or more on the test of strength", "Güç testinde 50 veya daha yüksek bir rekor puan elde et", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Verse Riff", "Evren Rifi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Understand the true meaning of the Great Transcendence", "Muazzam Yükseliş'in gerçek anlamını anla", Language.Turkish);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla", "Orijinal", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb", "Bomba", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield", "Kalkan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random", "Rastgele", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit", "boru", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evolve", "Evrimleşme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gems", "Cevherler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stall", "Oyalama", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying", "Sinir Bozucu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire", "Yanma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "Yeniden Şarj", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NoCharge", "ŞarjYok", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swap", "Takas", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nefarious", "Alçak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheapo", "Ucuzcu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FullDraft", "TamSeçim", Language.Turkish);

            // StatLabel
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Expended", "Harcanan Enerji", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammer Blows Dealt", "Çekiç Darbeleri", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abominations Created", "Yaratılan Ucubeler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quests Completed", "Tamamlanan Görevler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunters Killed", "Öldürülen Ödül Avcıları", Language.Turkish);

            // Mod
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Special Hammer Mod", "Özel Çekiç Modu", Language.Turkish);
            RegisterMod("Special Hammer Mod", "Özel Çekiç Modu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible Drafting Mod", "İnanılmaz Kart Seçimi Modu", Language.Turkish);
            RegisterMod("Incredible Drafting Mod", "İnanılmaz Kart Seçimi Modu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Community API", "Topluluk API'si", Language.Turkish);
            RegisterMod("The Community API", "Topluluk API'si");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super-Duper Unity Editor", "Süper Ötesi Unity Düzenleyicisi", Language.Turkish);
            RegisterMod("Super-Duper Unity Editor", "Süper Ötesi Unity Düzenleyicisi");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #1", "Kaycee'nin P03 Genişletme Paketi #1", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "«Kaycee'nin Modunda P03» geliştiricilerinin ilk genişletme paketi, Botopya'nın dört bölgesine [count] yeni kart ekler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #2", "Kaycee'nin P03 Genişletme Paketi #2", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "Patlayıcı bir tepki yaratacak [count] ateşli yeni kartla ikinci resmî genişletme paketi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Rogue Bots of Botopia", "Inscryption: Botopya'nın Asi Botları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has become overrun with rogue bots! These [count] encounters have been rebalanced for Kaycee's Mod.", "Botopya'yı asi botlar istila etti! Bu [count] karşılaşma, Kaycee'nin Modu için yeniden dengelendi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #1", "Kaycee'nin P03 Karşılaşma Genişletmesi #1", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the first official P03 expansion pack.", "İlk resmî P03 genişletme paketinin kartlarını içeren [count] ek karşılaşma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #2", "Kaycee'nin P03 Karşılaşma Genişletmesi #2", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the second official P03 expansion pack.", "İkinci resmî P03 genişletme paketinin kartlarını içeren [count] ek karşılaşma.", Language.Turkish);

