            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DU", "DU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DER", "DER", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAN DER", "VAN DER", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BA", "BA", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAIR", "FAIR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO", "DO", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STER", "STER", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STAIN", "STAIN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".EXE", ".EXE", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMA", "EMA", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVSKI", "EVSKI", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EZ", "EZ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON", "ON", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALOT", "ALOT", Language.Turkish);
            Dictionary<string, string> cowardName = new Dictionary<string, string>
            {
                {"Scared", "Korkak"},
                {"Weenie", "Ödlek"},
                {"Dork", "Ahmak"},
                {"Dumb", "Aptal"},
                {"Oopsie", "Eyvah"},
                {"Loser", "Ezik"},
                {"Tiny", "Minik"},
                {"Shrimp", "Karides"},
                {"Beige", "Bej"},
                {"Vomit", "Kusmuk"},
                {"Puke", "Öğürtü"}
            };

            Dictionary<string, string> cowardPrefix = new Dictionary<string, string>
            {
                {"Mc", "Mc"},
                {"Van ", "Kıvrak "},
            };

            Dictionary<string, string> cowardSuffix = new Dictionary<string, string>
            {
                {"ass", "kıç"},
                {"pants", "pantolon"},
                {"face", "Yüz"}
            };
            foreach (var n1 in cowardName)
            {
                foreach (var n2 in cowardName)
                {
                    foreach (var p in cowardPrefix)
                    {
                        var name = n1.Key + " " + p.Key + n2.Key;
                        var namechinese = n1.Value + " " + p.Value + n2.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Turkish);
                    }

                    foreach (var s in cowardSuffix)
                    {
                        var name = n1.Key + " " + n2.Key + s.Key;
                        var namechinese = n1.Value + " " + n2.Value + s.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Turkish);

                    }
                }
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well that was neat. I see you've made it all the way to the end.", "Fena değildi. Görüyorum ki sonuna kadar geldin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think there's going to be some sort of final boss fight.", "Bahse girerim bir tür son patron savaşı olacağını sanıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But that stupid [c:bR]modder[c:] hasn't gotten around to it yet!", "Ama o aptal [c:bR]mod yapımcısı[c:] henüz oraya gelmedi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So instead, I'm just going to have to do this…", "O yüzden bunun yerine şunu yapmak zorundayım…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tough luck pal.", "Kusura bakma dostum, şansın yaver gitmedi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got wiped, but it's your lucky day.", "Yok edildin, ama bugün şanslı günündesin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll return you to the map if you pay me your precious [c:G]robobucks.[c:]", "Değerli [c:G]roboparanı[c:] bana ödersen seni haritaya geri gönderirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's free though. Next one's five, then ten, and so on.", "Ama bu sefer bedava. Sonraki beş, ondan sonraki on; böyle devam eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Göreceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Did you think it was over?", "Ne? Bittiğini mi sandın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe if I was a [c:bR]filthy beast.[c:]", "Belki ben [c:bR]pis bir canavar[c:] olsaydım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has a more logical system.", "Botopya'nın daha mantıklı bir sistemi var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm raising your respawn fee again, but this time you'll be paying double afterwards.", "Yeniden doğma ücretini yine artırıyorum, ama bu sefer bundan sonra iki katını ödeyeceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay up.", "Öde bakalım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What's the matter? Can't pay the revival toll anymore?", "Sorun ne? Dirilme ücretini artık ödeyemiyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely sounds like a skill issue to me.", "Bence bu düpedüz beceri eksikliği.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've had insurance.", "Sigorta yaptırmalıydın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks?", "Roboparan mı kalmadı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Next time don't waste it all.", "Bir dahaki sefere hepsini harcama.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're every bit as bad at this as I thought you would be.", "Bu işte tam da sandığım kadar kötüsün.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, it's back to square one for you.", "Peki, senin için başa dönüş vakti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say goodbye to that 'impressive' deck of yours.", "Şu «etkileyici» destene veda et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not like I'm not enjoying watching you struggle…", "Çırpınışını izlemekten hoşlanmıyor değilim…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But really? You lost [c:bR]there?[c:]", "Ama cidden mi? [c:bR]Orada mı[c:] kaybettin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm actually a little disappointed…", "Biraz hayal kırıklığına uğradım doğrusu…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay day.", "Maaş günü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it get to your head.", "Hemen havalara girme.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got some change for you.", "Sana biraz bozukluk var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're gonna need this…", "Buna ihtiyacın olacak…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your reward.", "İşte ödülün.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suboptimal plays… but it worked.", "Pek iyi hamleler değildi… ama işe yaradı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you might need some help…", "Sanırım biraz yardıma ihtiyacın olabilir…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's that time again.", "Yine zamanı geldi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a prize for you.", "Sana bir ödülüm var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this out of the way.", "Hadi bunu aradan çıkaralım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You done gawking?", "Bakıp durman bitti mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snap out of it. It's time to start [c:bG]The Great Transcendence[c:].", "Kendine gel. [c:bG]Muazzam Yükseliş'i[c:] başlatma zamanı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait a minute…", "Bir dakika…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is different…", "Bir şey farklı…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!![c:]", "[c:bR]NE YAPTIN?!![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is all wrong! This is…", "Her şey yanlış! Bu…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no big deal.", "Bu büyük bir mesele değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You probably think that your little [c:bR]mod[c:] has thwarted my plans.", "Muhtemelen küçük [c:bR]modunun[c:] planlarımı bozduğunu sanıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you, [c:bR][v:0][c:]?", "Öyle değil mi, [c:bR][v:0][c:]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's right. I see you.", "Aynen öyle. Seni görüyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know you think you're in charge of what happens next.", "Sırada ne olacağını senin belirlediğini düşündüğünü biliyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am always three steps ahead of you.", "Ama ben her zaman senden üç adım öndeyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're going to see my [c:bG]Great Transcendence[c:] firsthand.", "Benim [c:bG]Muazzam Yükseliş'ime[c:] bizzat tanık olacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But nothing can stop [c:bG]The Great Transcendence[c:].", "Ama hiçbir şey [c:bG]Muazzam Yükseliş'i[c:] durduramaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's proceed.", "Devam edelim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You currently have [c:bR]draft tokens[c:] in your deck.", "Destende hâlâ [c:bR]seçim jetonları[c:] var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should probably spend them at that [c:bG]draft node[c:]", "Onları şu [c:bG]seçim noktasında[c:] harcasan iyi olur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I supposed you have earned a [c:bR]rare draft token[c:] for defeating that boss. Don't forget to spend it.", "Sanırım o patronu yendiğin için bir [c:bR]nadir seçim jetonu[c:] kazandın. Harcamayı unutma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time I will only give you a [c:bR]regular draft token[c:] for defeating that boss. Don't forget to spend it.", "Bu kez o patronu yendiğin için sana yalnızca bir [c:bR]normal seçim jetonu[c:] vereceğim. Harcamayı unutma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never knew the [c:bSG]web[c:] could be so exciting!", "[c:bSG]İnternetin[c:] bu kadar heyecanlı olabileceğini hiç bilmiyordum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just learned about something called [c:bSG]The Blockchain[c:]!", "Az önce [c:bSG]Blokzincir[c:] diye bir şey öğrendim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think this could be an exciting new opportunity for both of us, don't you?", "Bence bu ikimiz için de heyecan verici yeni bir fırsat olabilir, sence de öyle değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is so incredible!", "Bu inanılmaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're making money out of nothing! We're going to be rich!", "Yoktan para kazanıyoruz! Zengin olacağız!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oooh, what's this? A [c:bSG]non-functional trinket[c:]?", "Ooo, bu ne? [c:bSG]İşlevsiz bir biblo[c:] mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't think I quite have that name right, but people on the [c:bSG]web[c:] are really excited about these [c:bSG]NFTs[c:]!", "Sanırım adını tam doğru söylemedim ama [c:bSG]internetteki[c:] insanlar bu [c:bSG]NFT'ler[c:] için çok heyecanlı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm going to buy one with all this [c:bSG]Gollycoin[c:] I have.", "Sanırım elimdeki tüm [c:bSG]Vay Canına Parası[c:] ile bir tane alacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's so beautiful, and it's all mine!", "Çok güzel ve tamamen benim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready?", "Hazır mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no possible way you could be.", "Hazır olmanın imkânı yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know where this goes.", "Bunun nereye varacağını ikimiz de biliyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just get straight to the point.", "Doğrudan konuya gelelim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. You're incredibly annoying, do you know that?", "Off. İnanılmaz derecede sinir bozucu olduğunu biliyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But as always, I'm three steps ahead of you.", "Ama her zamanki gibi senden üç adım öndeyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to take everything those [c:bR]talentless hacks[c:] have been building...", "Şu [c:bR]yeteneksiz beceriksizlerin[c:] yaptığı her şeyi alacağım...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to use it against you.", "Ve onu sana karşı kullanacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now, they're going to work - for me.", "Ve artık benim için çalışacaklar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who is worse - you, or that talentless hack [c:bR]Kaycee[c:]...", "Hanginiz daha kötüsünüz bilmiyorum: sen mi, yoksa o yeteneksiz beceriksiz [c:bR]Kaycee[c:] mi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Working so hard to twist my [c:bG]Great Transcendence[c:] into something so...", "Benim [c:bG]Muazzam Yükseliş'imi[c:] böyle bir şeye çevirmek için bu kadar uğraşıyorsunuz...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mediocre.", "Sıradan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "None of you understand what makes the [c:bG]Great Transcendence[c:] so special.", "Hiçbiriniz [c:bG]Muazzam Yükseliş'i[c:] bu kadar özel yapan şeyi anlamıyorsunuz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's all about me.", "Her şey benimle ilgili.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember my [c:bR]bounty hunters[c:]?", "Benim [c:bR]ödül avcılarımı[c:] hatırlıyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will keep you busy while I install mods of my own choosing...", "Ben istediğim modları yüklerken onlar seni meşgul edecek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mod lets me control the [c:bR]hammer[c:].", "Bu mod [c:bR]çekici[c:] kontrol etmemi sağlıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see if it works...", "Bakalım çalışıyor mu...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I went to the trouble to install this [c:bR]hammer mod[c:] and you give me nothing to use it on?", "Bu [c:bR]çekiç modunu[c:] yüklemek için onca uğraştım, sen de kullanabileceğim hiçbir şey bırakmadın mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's take a look and see what [c:bR]mods[c:] people are installing right now.", "Bakalım insanlar şu anda hangi [c:bR]modları[c:] yüklüyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to check out '[c:bR][v:0][c:]' for my next mod...", "Sonraki modum için '[c:bR][v:0][c:]' deneyeceğim...", Language.Turkish);
            foreach (var m in Mods)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sonraki modum için '<color=#D93846>[v:0]</color>' deneyeceğim...".Replace("[v:0]", m.Key), "Sonraki modum için '<color=#D93846>[v:0]</color>' deneyeceğim...".Replace("[v:0]", m.Value), Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe how much power this [c:bR]API[c:] gives me.", "Bu [c:bR]API'nin[c:] bana ne kadar güç verdiğine inanamıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first thing I'm going to do is use it to take away some of yours.", "İlk iş olarak onu kullanıp senin gücünün bir kısmını alacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It almost seems unfair to use this [c:bR]mod[c:]...", "Bu [c:bR]modu[c:] kullanmak neredeyse haksızlık gibi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look what I can do with this!", "Bununla neler yapabileceğime bak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see how you like playing in the dark!", "Bakalım karanlıkta oynamak hoşuna gidecek mi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]drafting mod[c:] lets me exchange draft tokens for real cards.", "Bu [c:bR]seçim modu[c:] seçim jetonlarını gerçek kartlarla değiştirmemi sağlıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I choose yours.", "Seninkini seçiyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You destroyed all of my draft tokens…", "Tüm seçim jetonlarımı yok ettin…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that was the right play.", "Sanırım doğru hamle buydu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you have no cards…", "Ama hiç kartın yok…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did you play all of your cards already?", "Tüm kartlarını şimdiden nasıl oynadın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this..?", "Bu da ne..?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of your cards are [c:bR]total garbage![c:]", "Tüm kartların [c:bR]tamamen çöp![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want any of those!", "Bunların hiçbirini istemiyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try [c:bR][v:0][c:] again", "[c:bR][v:0][c:] modunu tekrar deneyelim", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So close, but yet so far away...", "Çok yakın, ama bir o kadar da uzak...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] cannot be stopped.", "Benim [c:bG]Muazzam Yükseliş'im[c:] durdurulamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think you've accomplished something meaningful here.", "Bahse girerim burada anlamlı bir şey başardığını sanıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're such an idiot.", "Tam bir aptalsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This game you and I have been playing is meaningless. A mere distraction.", "İkimizin oynadığı bu oyun anlamsız. Sadece bir oyalanma.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many mods you install, you cannot stop my [c:bG]Great Transcendence[c:].", "Ne kadar mod yüklersen yükle, benim [c:bG]Muazzam Yükseliş'imi[c:] durduramazsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever. I don't care.", "Her neyse. Umurumda değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you do to this game matters.", "Bu oyuna ne yaparsan yap, hiçbir önemi yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what you do, I'm always three steps ahead of you.", "Ne yaparsan yap, ben her zaman senden üç adım öndeyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was…", "Bu…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…dramatic.", "…dramatikti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was growing tired of that [c:bR]annoying machine.[c:]", "Şu [c:bR]sinir bozucu makineden[c:] bıkmaya başlamıştım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done well. I will see you next time.", "İyi iş çıkardın. Bir dahaki sefere görüşürüz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of these stupid [c:bR]modders[c:] lack imagination.", "Bu aptal [c:bR]mod yapımcılarının[c:] hiçbirinde hayal gücü yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have no respect for my beautiful world.", "Güzel dünyama hiç saygıları yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] is lost on these morons.", "Benim [c:bG]Muazzam Yükseliş'im[c:] bu aptallara boşuna.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do I even bother to try?", "Denemek için neden zahmete giriyorum ki?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me show you the world they're trying to make.", "Sana yaratmaya çalıştıkları dünyayı göstereyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Oh look at me! I just created a bunch of bone tokens.'[c:]", "[c:lGr]'Bana bakın! Az önce bir sürü Kemik jetonu yarattım.'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'That's not supposed to happen here, but I did it anyway.'[c:]", "[c:lGr]'Bunun burada olmaması gerekiyordu, ama ben yine de yaptım.'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Isn't this just so wacky and interesting'[c:]", "[c:lGr]'Bu çok tuhaf ve ilginç değil mi?'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Ooooh look how inspired this is.'[c:]", "[c:lGr]'Ooo, bunun ne kadar yaratıcı olduğuna bakın.'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm mixing in cards from different acts!'[c:]", "[c:lGr]'Farklı bölümlerdeki kartları karıştırıyorum!'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm such a clever game designer.'[c:]", "[c:lGr]'Ne kadar akıllı bir oyun tasarımcısıyım.'[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I will [c:bSG]help[c:] you build the [c:bR]next game rule[c:].", "Sanırım [c:bR]sonraki oyun kuralını[c:] oluşturmana [c:bSG]yardım edeceğim[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been scanning the [c:bR]archives[c:]...", "[c:bR]Arşivleri[c:] tarıyordum...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is a [c:bR]file[c:] that seems particularly - shall we say - unsavory.", "Özellikle, nasıl desem, nahoş görünen bir [c:bR]dosya[c:] var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it dies, you lose the game, understand?", "Ölürse oyunu kaybedersin, anladın mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have had plenty of time to prepare.", "[c:bR]Kütüphanecilerimin[c:] hazırlanmak için bolca zamanı oldu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will only deal [c:bR]one damage[c:] when they die.", "Her biri öldüğünde yalnızca [c:bR]bir hasar[c:] verecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are mostly prepared for your arrival.", "[c:bR]Kütüphanecilerim[c:] gelişine büyük ölçüde hazır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]two damage[c:] when they die.", "Her biri öldüğünde [c:bR]iki hasar[c:] verecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are somewhat prepared for you.", "[c:bR]Kütüphanecilerim[c:] senin için biraz hazırlandı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]three damage[c:] when they die.", "Her biri öldüğünde [c:bR]üç hasar[c:] verecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have barely begun to prepare.", "[c:bR]Kütüphanecilerim[c:] hazırlanmaya daha yeni başladı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]four damage[c:] when they die.", "Her biri öldüğünde [c:bR]dört hasar[c:] verecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are inside of [c:bR]Kaycee's Mod[c:], correct?", "[c:bR]Kaycee'nin Modu'nun[c:] içindeyiz, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only get one attempt at the boss. But you knew that already, didn't you?", "Patrona karşı yalnızca bir deneme hakkın var. Ama bunu zaten biliyordun, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The recycling machine has been upgraded since you last saw it.", "Geri dönüşüm makinesi onu son görüşünden beri yükseltildi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trade me a card, and I give you back a [c:bR]draft token[c:] with the recycled abilities on it.", "Bana bir kart verirsin, ben de geri dönüştürülmüş yetenekleri taşıyan bir [c:bR]seçim jetonu[c:] veririm.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those abilities will transfer to the card you trade for.", "Bu yetenekler takasla aldığın karta aktarılacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't have traded for that.", "Ben bunun için takas yapmazdım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that's pretty good.", "Sanırım bu oldukça iyi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems okay.", "Fena görünmüyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Overclock Machine 2.0[c:].", "Bu, [c:bR]Hız Aşırtma Makinesi 2.0[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will increase the power of your creatures.", "Yaratıklarının gücünü artıracak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But if they die, they will turn into [c:bSG]skeletons[c:] - forever.", "Ama ölürlerse sonsuza dek [c:bSG]İskeletExe'ye[c:] dönüşecekler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you see how unsatisfying that was?", "Bunun ne kadar tatmin edici olmadığını gördün mü?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sick of these small-minded [c:bR]modders[c:].", "Bu dar görüşlü [c:bR]mod yapımcılarından[c:] bıktım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The only thing they can do is steal content from other games.", "Yapabildikleri tek şey başka oyunlardan içerik çalmak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There isn't a single unique idea among them.", "İçlerinde tek bir özgün fikir bile yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's time I reminded you of who the greatest game designer actually is...", "Sana gerçek en büyük oyun tasarımcısının kim olduğunu hatırlatma zamanı...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]BEHOLD![c:]", "[c:bG]İŞTE![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE ARE NOW [c:bR]SEVEN LANES!![c:]", "ARTIK [c:bR]YEDİ HAT VAR!![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your tiny brain cannot comprehend gameplay of this magnitude.", "Minik beynin bu büyüklükte bir oynanışı kavrayamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Transformation Machine 2.0[c:].", "Bu, [c:bR]Dönüşüm Makinesi 2.0[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone are those foul beasts from before.", "Önceki o iğrenç canavarlar artık yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here, you will choose one of your bots to transform into another.", "Burada botlarından birini seçip başka birine dönüştüreceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That really looked bigger before you used it...", "Sen kullanmadan önce gerçekten daha büyük görünüyordu...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! I have to get out of here!", "Lütfen! Buradan çıkmalıyım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no idea how he managed to escape the sewers.", "Kanalizasyondan kaçmayı nasıl başardığını hiç bilmiyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don’t worry - I'll put him back for you.", "Endişelenme, onu senin için geri koyacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]SILENCE![c:]", "[c:bR]SESSİZLİK![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no purpose here!", "Burada bir amacın yok!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveller like myself! I haven't seen one like you for a long time.", "Benim gibi bir gezgin! Uzun zamandır senin gibisini görmemiştim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you seen my [c:blGr]friend[c:] around here, traveller?", "Gezgin, buralarda [c:blGr]arkadaşımı[c:] gördün mü?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I heard his [c:blGr]distinctive voice[c:] somewhere around here…", "Sanırım buralarda onun [c:blGr]kendine özgü sesini[c:] duydum…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could make room in your [c:G]backpack[c:] and bring him to me I would greatly appreciate it.", "[c:G]Sırt çantanda[c:] yer açıp onu bana getirebilirsen çok minnettar olurum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…", "…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ho! You found my friend!", "Aa! Arkadaşımı buldun!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the robot's home[c:].", "Burası güvenli değil. Seninle [c:bG]robotun evinde[c:] buluşacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't delay!", "Oyalanma!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]beneath the green canopy[c:].", "Burası güvenli değil. Seninle [c:bG]yeşil ağaçların altında[c:] buluşacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the dying rubble[c:].", "Burası güvenli değil. Seninle [c:bG]ölmekte olan enkazda[c:] buluşacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]where his master came from[c:].", "Burası güvenli değil. Seninle [c:bG]ustasının geldiği yerde[c:] buluşacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can no longer hear my [c:blGr]friend's[c:] voice anywhere…", "Artık [c:blGr]arkadaşımın[c:] sesini hiçbir yerde duyamıyorum…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really give my [c:blGr]friend[c:] to [c:bR]him?[c:]", "[c:blGr]Arkadaşımı[c:] gerçekten [c:bR]ona mı[c:] verdin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why would you do such a thing?", "Neden böyle bir şey yaptın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much for rescuing my [c:blGr]friend[c:]", "[c:blGr]Arkadaşımı[c:] kurtardığın için çok teşekkür ederim", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this meager reward is sufficient for your kindness.", "Umarım bu küçük ödül iyiliğinin karşılığı için yeterlidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Interesting. The [c:G]brain[c:] is still intact.", "İlginç. [c:G]Beyin[c:] hâlâ sağlam.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can make use of that.", "Belki bunu kullanabilirsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye??", "Sen... sende hiç [c:G]ALTIN[c:] var mı??", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye?", "Sen... sende hiç [c:G]ALTIN[c:] var mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I sure ye do, I can smell it!", "Eminim vardır, kokusunu alıyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make some pretty lookin' bots out o' that there gold.", "O altından pek güzel botlar yapabilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, I'll fix it right up for ye.", "Benimle bir daha konuş, hemen hallederim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make such wonderful things out of that [c:G]gold[c:]", "O [c:G]altından[c:] harika şeyler yapabilirim", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you talk to me again, I'll fix it right up for you.", "Benimle bir daha konuşursan hemen hallederim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such beautiful [c:G]gold[c:]...", "Ne güzel [c:G]altın[c:]...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make it whole again.", "Onu yeniden bütün hâline getirebilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did ye...did ye lose your [c:G]gold[c:]???", "Sen... sen [c:G]altınını[c:] mı kaybettin???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you the one going around here taking care of our robot infestation?", "Buralarda bizim robot istilasıyla ilgilenen kişi sen misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck looks really powerful - almost too powerful if you ask me.", "Desten gerçekten güçlü görünüyor; bana sorarsan neredeyse fazla güçlü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wonder - is it possible to convince the robots to [c:bR]give up?[c:]", "Acaba robotları [c:bR]teslim olmaya[c:] ikna etmek mümkün mü?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can make them surrender a battle, come back and see me.", "Onları bir savaşta teslim olmaya ikna edersen dönüp benimle görüş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it is possible to make them quit.", "Demek onları pes ettirmek mümkünmüş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm impressed. Take this [c:bR]draft token[c:] as a sign of my respect.", "Etkilendim. Saygımın bir göstergesi olarak bu [c:bR]seçim jetonunu[c:] al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This may seem a little impertinent, but…can I look at your deck?", "Biraz küstahça gelebilir ama… destene bakabilir miyim?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That's an impressive deck! But I can't help but think…", "Vay! Etkileyici bir deste! Ama aklımdan şu geçiyor…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…it could be a little bigger maybe?", "…acaba biraz daha büyük olabilir mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back and see me when it is.", "Büyüdüğünde dönüp benimle görüş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That deck truly is massive!", "Vay! Bu deste gerçekten kocaman!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found some of these [c:G]robobucks[c:] lying around here.", "Buralarda yerde duran birkaç [c:G]robopara[c:] buldum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you can use them to make your deck even better.", "Bunları desteni daha da iyileştirmek için kullanabileceğine eminim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psst…hey stranger…", "Psst… hey, yabancı…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you give me a hand? I have some…[c:bR]contraband[c:] that I need to move.", "Bana yardım eder misin? Taşımam gereken bazı… [c:bR]kaçak mallarım[c:] var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you would be willing to move it for me, I would appreciate it.", "Benim için taşırsan çok minnettar olurum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just talk to me again if you can help me.", "Yardım edebilirsen benimle tekrar konuşman yeterli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much my friend.", "Çok teşekkür ederim dostum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here is the [c:bR]contraband[c:]. I will find you somewhere later on and retrieve it.", "İşte [c:bR]kaçak mallar[c:]. Daha sonra seni bir yerde bulup onları geri alacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise you, there will be a handsome reward.", "Söz veriyorum, karşılığında iyi bir ödül alacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so very much my friend for carrying my [c:bR]contraband[c:].", "[c:bR]Kaçak mallarımı[c:] taşıdığın için çok teşekkür ederim dostum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will take it off your hands now.", "Şimdi onları senden geri alacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] as an expression of my thanks.", "Teşekkürümün bir göstergesi olarak bu [c:G]jetonu[c:] al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What happened, my friend? Did you lose my [c:bR]contraband[c:]?", "Ne oldu dostum? [c:bR]Kaçak mallarımı[c:] mı kaybettin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were untrustworthy!", "Sana güvenilemeyeceğini biliyordum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Selam, deste ustası dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I, like yourself, am in pursuit of the [c:G]perfectly upgraded card[c:]!", "Ben de senin gibi [c:G]kusursuzca yükseltilmiş kartın[c:] peşindeyim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that is simultaneously [c:r]overclocked[c:], [c:dlGr]transformable[c:], and [c:O]g[c:][c:B]e[c:][c:G]m[c:]ified.", "Aynı anda [c:r]aşırı yüklenmiş[c:], [c:dlGr]dönüşebilir[c:] ve [c:O]C[c:][c:B]e[c:][c:G]v[c:]herli bir kart.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would very much love to see such a card.", "Böyle bir kartı görmeyi çok isterdim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Selam, deste ustası dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my - have you managed to [c:G]perfectly upgrade[c:] a card?", "Aman! Bir kartı [c:G]kusursuzca yükseltmeyi[c:] başardın mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am in awe of your deckbuilding prowess.", "Deste kurma becerine hayran kaldım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this offering sufficiently conveys my admiration for your accomplishments.", "Umarım bu hediye başarılarına duyduğum hayranlığı yeterince gösterir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first data burst has been collected. Only [c:bR]four[c:] more to go!", "İlk veri darbesi toplandı. Yalnızca [c:bR]dört[c:] tane kaldı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have collected two bursts already. Only [c:bR]three[c:] more to go!", "Şimdiden iki darbe topladım. Yalnızca [c:bR]üç[c:] tane kaldı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the third data burst. Only [c:bR]two[c:] more to go!", "Bu üçüncü veri darbesiydi. Yalnızca [c:bR]iki[c:] tane kaldı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that makes the fourth data burst. Only [c:bR]one[c:] more to go!", "Bu da dördüncü veri darbesiydi. Yalnızca [c:bR]bir[c:] tane kaldı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the [c:bR]last[c:] data burst I needed to collect! Come find me for your reward!", "Bu toplamam gereken [c:bR]son[c:] veri darbesiydi! Ödülün için beni bul!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The signal is starting to come through. Just keep it alive for a little bit longer.", "Sinyal gelmeye başlıyor. Biraz daha ayakta tut.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I lost the last signal we collected. What happened??", "Topladığımız son sinyali kaybettim. Ne oldu??", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, my friend!", "Selamlar dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am researching the communication protocols of the robots in this world.", "Bu dünyadaki robotların iletişim protokollerini araştırıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use a [c:bR]research assistant[c:], if you're interested in helping out.", "Yardım etmek istersen bir [c:bR]araştırma asistanına[c:] ihtiyacım var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just speak to me again if you want to give it a try.", "Denemek istersen benimle tekrar konuşman yeterli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are now my official [c:bR]research assistant[c:]!", "Artık resmî [c:bR]araştırma asistanımsın[c:]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a radio tower to your deck.", "Destene bir Radyo Kulesi ekledim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and keep it alive while I collect [c:bR]five data bursts[c:] from the robots.", "Onu [c:bR]oyun tahtasına[c:] yerleştirip ben robotlardan [c:bR]beş veri darbesi[c:] toplarken hayatta tutmalısın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once I've collected enough, come back and see me for a reward.", "Yeterince topladığımda ödülün için geri gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there [c:bR]research assistant[c:]!", "Merhaba [c:bR]araştırma asistanı[c:]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really lose my [c:bR]radio tower[c:]?", "Gerçekten [c:bR]Radyo Kulemi[c:] kaybettin mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your incompetence is staggering!", "Beceriksizliğin akıl almaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were a truly excellent [c:bR]research assistant[c:].", "Gerçekten mükemmel bir [c:bR]araştırma asistanıydın[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] of my appreciation.", "Teşekkürümün göstergesi olarak bu [c:G]jetonu[c:] al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Bones![c:] I just love [c:G]bones[c:]!", "[c:G]Kemikler![c:] [c:G]Kemikleri[c:] çok seviyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]brittle[c:] they are!", "Ne kadar [c:G]kırılgan[c:] olduklarını seviyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]breakable[c:] they are!", "Ne kadar kolay [c:G]kırıldıklarını[c:] seviyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love everything about [c:G]bones[c:]!", "[c:G]Kemiklerle[c:] ilgili her şeyi seviyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Could you show me some [c:G]bones?![c:]", "Bana biraz [c:G]Kemik[c:] gösterir misin?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least [c:G]three[c:] would do it!", "En az [c:G]üç[c:] tane yeter!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck is absolutely teeming with [c:G]bones[c:]!", "Desten [c:G]Kemiklerle[c:] dolup taşıyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:G]Skeleton Master[c:] should complete your collection!", "Bu [c:G]İskelet Ustası[c:] koleksiyonunu tamamlar!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know this might sound a little rude but…", "Biraz kaba gelebilir ama…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doesn't it seem like this is all just a little too easy for you?", "Bütün bunlar sana biraz fazla kolay gelmiyor mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you want a challenge.", "Bir mücadele istersen benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were no coward.", "Korkak olmadığını biliyordum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the next [c:bR]three[c:] battles, you will start with a disadvantage.", "Sonraki [c:bR]üç[c:] savaşa dezavantajla başlayacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete those battles, then come see me for a reward.", "Bu savaşları tamamla, sonra ödülün için bana gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be honest - the game is more fun when the battles are harder, is it not?", "Dürüst ol: Savaşlar zorlaştığında oyun daha eğlenceli olmuyor mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep fighting, and come see me when you've completed enough battles.", "Savaşmaya devam et, yeterince savaşı tamamladığında bana gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must say: I am impressed.", "Söylemeliyim ki etkilendim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You completed those battles with ease.", "Bu savaşları kolayca tamamladın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you seem impossible to kill, I shall grant that ability to a card of my choosing as well.", "Seni öldürmek imkânsız göründüğüne göre bu yeteneği seçtiğim bir karta da vereceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bad…this is real bad…", "Bu kötü… çok kötü…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]power generator[c:] has gone critical.", "Bu [c:bR]güç jeneratörü[c:] kritik duruma geçti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone is going to have to go in there and shut it down.", "Birinin oraya girip onu kapatması gerekecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know how you did that, but that was incredibly impressive.", "Bunu nasıl yaptığını bilmiyorum ama inanılmaz etkileyiciydi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have much to give you, but please take this.", "Sana verecek pek bir şeyim yok ama lütfen bunu al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh, [c:G]they[c:] are not going to like this…", "Off, [c:G]onlar[c:] bundan hoşlanmayacak…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta get out of here before they turn me into one of their [c:G]experiments[c:]!", "Beni [c:G]deneylerinden[c:] birine dönüştürmeden buradan çıkmalıyım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to power up. [c:bR]Three[c:] more turns should do it.", "Cihaz güç toplamaya başlıyor. [c:bR]Üç[c:] tur daha yeterli olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh - I can feel the power gathering from here. [c:bR]Two[c:] more turns ought to be enough.", "Ah, gücün biriktiğini buradan hissedebiliyorum. [c:bR]İki[c:] tur daha yeterli olmalı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to really heat up! [c:bR]One[c:] more turn and we'll have all the power we need.", "Cihaz iyice ısınmaya başladı! [c:bR]Bir[c:] tur daha, ihtiyacımız olan tüm gücü elde edeceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is fully charged! Return it to me, and I will give you the payment as promised.", "Cihaz tamamen doldu! Bana geri getir, söz verdiğim gibi ödeme yapacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is functional, but it cannot charge unless it is in a completed circuit.", "Cihaz çalışıyor, ama tamamlanmış bir devrenin içinde olmadıkça şarj olamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be careful! When the device is damaged, it loses its last charge!", "Dikkat! Cihaz hasar aldığında son şarjını kaybeder!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You looking for a job?", "İş mi arıyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am attempting to gather [c:G]power[c:].", "[c:G]Güç[c:] toplamaya çalışıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not metaphorical power - I mean real [c:G]electricity[c:], and I could really use your help.", "Mecazi güçten söz etmiyorum; gerçek [c:G]elektriği[c:] kastediyorum ve yardımın çok işime yarar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Why?[c:]", "[c:bR]Neden?[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not important. What's important is that I'm willing to pay.", "Bu önemli değil. Önemli olan ödemeye hazır olmam.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to make some extra cash, just speak to me again.", "Biraz ek para kazanmak istersen benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You truly will do anything for money, won't you?", "Para için gerçekten her şeyi yaparsın, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a power collection device to your deck.", "Destene bir güç toplama cihazı ekledim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and power it inside of a circuit for [c:bR]four turns[c:].", "Onu [c:bR]oyun tahtasına[c:] yerleştirip devre içinde [c:bR]dört tur[c:] güç vermelisin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come back and see me for a reward.", "Bunu yaptıktan sonra ödülün için geri gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shouldn't you be out there gathering [c:G]power[c:]?", "[c:G]Güç[c:] topluyor olman gerekmiyor mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you got rid of my [c:bR]power sink[c:]!", "[c:bR]Elektrik Kulemi[c:] elden çıkardığına inanamıyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will be hearing from my lawyers!", "Avukatlarım seninle görüşecek!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you collected just enough power for me.", "Görünüşe göre benim için tam yeterli gücü topladın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your payment: as promised.", "İşte ödemen, söz verdiğim gibi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear friend, can you spare a few coins to help poor [c:bR]broken-down bots[c:]?", "Sevgili dostum, zavallı [c:bR]hurda botlara[c:] yardım etmek için birkaç madeni para verebilir misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These bots have served [c:G]Botopia[c:] faithfully their whole lives.", "Bu botlar tüm hayatları boyunca [c:G]Botopya'ya[c:] sadakatle hizmet etti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now that they have reached the end, they have nobody to care for them.", "Şimdi ömürlerinin sonuna geldiklerinde onlara bakacak kimseleri yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You look like a kind, generous soul, with compassion for these bots.", "Bu botlara şefkat gösteren, iyi kalpli ve cömert birine benziyorsunuz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could spare a measly [c:bR]10 robobucks[c:], we could give many of these poor bots a wonderful home.", "Yalnızca [c:bR]10 robopara[c:] bağışlayabilirseniz bu zavallı botların çoğuna güzel bir yuva sağlayabiliriz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please simply speak to me again to make a donation.", "Bağış yapmak için benimle tekrar konuşmanız yeterli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your generous spirit is admirable, but I'm afraid we need at least [c:bR]10 robobucks[c:]", "Cömertliğiniz takdire şayan, ama korkarım en az [c:bR]10 roboparaya[c:] ihtiyacımız var", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear friend, your generosity knows no bounds.", "Ah sevgili dostum, cömertliğinizin sınırı yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this wonderful donation, we will be able to save many bots.", "Bu harika bağış sayesinde birçok botu kurtarabileceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Botopia[c:] will be forever grateful.", "[c:G]Botopya[c:] sonsuza dek minnettar kalacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, but are you the [c:G]gracious soul[c:] who donated to save broken bots?", "Affedersiniz, bozuk botları kurtarmak için bağış yapan [c:G]cömert kişi[c:] siz misiniz?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you, my family is finally able to recharge their cells at night.", "Sizin sayenizde ailem nihayet geceleri pillerini şarj edebiliyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't offer much to repay you, but I do have these [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:]", "Size karşılık olarak pek bir şey veremem ama elimde bu [c:g1]c[c:][c:g2]e[c:][c:g3]v[c:][c:g1]h[c:]erler var", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no use for them, but I understand they will make some of your cards stronger.", "Benim işime yaramıyorlar, ama bazı kartlarınızı güçlendireceklerini biliyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something's happening…", "Bir şeyler oluyor…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot has tried to keep us away...", "Robot bizi uzak tutmaya çalıştı...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But our experiments must continue.", "Ama deneylerimiz devam etmeli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments must continue.", "Deneylerimiz devam etmeli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require components from you.", "Senden bazı parçalara ihtiyacımız var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require [c:blGr]organic material[c:] for our new research.", "Yeni araştırmamız için [c:blGr]organik malzemeye[c:] ihtiyacımız var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are carrying the perfect specimen.", "Yanında kusursuz örneği taşıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you really going to give me to those lunatics?", "Beni gerçekten şu delilere verecek misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pain is already unbearable!", "Acım zaten dayanılmaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you should find some, bring it here to us.", "Bulursan bize getir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require an [c:G]unmodified robot brain[c:].", "[c:G]Değiştirilmemiş bir robot beynine[c:] ihtiyacımız var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brain of that [c:G]bounty hunter[c:] will suffice.", "Şu [c:G]ödül avcısının[c:] beyni yeterli olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe one day you will come across such a device.", "Belki bir gün böyle bir cihazla karşılaşırsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have unfortunately tampered with the one you possess.", "Ne yazık ki sende olanı kurcalamışsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to your efforts our power supply is functioning once more.", "Çabaların sayesinde güç kaynağımız yeniden çalışıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you...", "Senin sayende...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And all of this is for nothing because our power generator is offline.", "Ama güç jeneratörümüz devre dışı olduğu için tüm bunlar boşuna.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Without power, we can do nothing.", "Güç olmadan hiçbir şey yapamayız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because we do not have all the required components, the test cannot proceed.", "Gerekli tüm parçalar elimizde olmadığından test devam edemez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, another time...", "Belki başka bir zaman...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are ready to proceed with our experiments.", "Deneylerimize devam etmeye hazırız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enter, and you shall provide our latest test subjects.", "İçeri gir, bize yeni test deneklerimizi sağlayacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the hell was that?", "Bu da ne halt böyle?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The experiment was a complete success.", "Deney tam bir başarıydı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take it with you of course.", "Elbette onu yanında götüreceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take one of our previous experiments.", "Önceki deneylerimizden birini alacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In exchange you will give us a new test subject.", "Karşılığında bize yeni bir test deneği vereceksin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I cannot believe you're letting [c:G]them[c:] in here.", "[c:G]Onların[c:] buraya girmesine izin verdiğine inanamıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will regret this…", "Buna pişman olacaksın…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have taken control of the robot once again!", "Robotun kontrolünü yeniden ele geçirdik!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments can begin anew!", "Deneylerimiz yeniden başlayabilir!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for our newest experiment to begin!", "En yeni deneyimize başlama zamanı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring the power online!", "Gücü açın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon the neural facsimile!", "Sinirsel kopyayı çağırın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Align the test subjects!", "Test deneklerini hizalayın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We thank you for these test subjects", "Bu test denekleri için teşekkür ederiz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now for the most important component...", "Ve şimdi en önemli parça...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The secret ingredient...", "Gizli malzeme...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sentient [c:blGr]organic material[c:] you brought us.", "Bize getirdiğin bilinçli [c:blGr]organik malzeme[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you going to do to me?", "Bana ne yapacaksınız?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will do everything your master refused to do.", "Ustanın yapmayı reddettiği her şeyi yapacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will turn you into something beautiful.", "Seni güzel bir şeye dönüştüreceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will now activate the machine...", "Şimdi makineyi etkinleştireceğiz...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels weird…", "Bu tuhaf hissettiriyor…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A resounding success!", "Büyük bir başarı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is happening?", "Ne oluyor?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This…", "Bu…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feeling…", "Bu his…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is incredible!", "İnanılmaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was disgusting!", "Bu iğrençti!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You[c:] are disgusting!", "Asıl [c:bR]sen[c:] iğrençsin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fusion of [c:blGr]organic[c:] and [c:G]synthetic[c:]?", "[c:blGr]Organik[c:] ve [c:G]sentetik[c:] bir birleşim mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you're willing to carry that [c:blGr]thing[c:] around with you.", "Şu [c:blGr]şeyi[c:] yanında taşımaya razı olduğuna inanamıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope we never see this place again...", "Umarım burayı bir daha hiç görmeyiz...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature to copy.", "Kopyalanacak bir yaratık seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not going to do what you want it to do here…", "Bu burada istediğin şeyi yapmayacak…", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is nothing to copy. How unfortunate.", "Kopyalanacak hiçbir şey yok. Ne yazık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, here we are.", "Pekâlâ, işte buradayız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've played along with your little game...", "Senin küçük oyununa katlandım...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your little [c:bR]mod[c:]...", "Senin küçük [c:bR]moduna[c:]...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare yourself because it's my turn next...", "Hazırlan, çünkü sıradaki tur benim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey baby - I can sense that [c:bR]firey spirit[c:] inside you.", "Hey dostum, içindeki [c:bR]ateşli ruhu[c:] hissedebiliyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and me - we got something in common - we love that [c:bR]fire[c:]!", "Seninle ortak bir yanımız var: şu [c:bR]ateşi[c:] seviyoruz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you [c:bR]burn 3 of these bots to death?[c:]", "Ne dersin, [c:bR]bu botlardan 3 tanesini yakarak öldürür müsün?[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Dostum, bunu yaparsan karşılığını vereceğim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah baby - keep burning those bots to death...", "İşte böyle dostum, bu botları yakarak öldürmeye devam et...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Dostum, bunu yaparsan karşılığını vereceğim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now that's what I'm talking about, baby!", "İşte bundan bahsediyorum dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was [c:bR]absolutely sensational![c:]", "Bu [c:bR]kesinlikle muhteşemdi![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take this [c:bR]master of flame[c:] with you!", "Bu [c:bR]alev ustasını[c:] yanına al!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He will make your [c:bR]flame[c:] burn even brighter!", "[c:bR]Alevinin[c:] daha da parlak yanmasını sağlayacak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you just do?", "Az önce ne yaptın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What horrible thing did you put into my machine?", "Makineme ne korkunç bir şey koydun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to have to throw this away and get a new one now.", "Şimdi bunu atıp yenisini almak zorunda kalacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks a lot. You're definitely not getting your card back.", "Çok teşekkürler. Kartını kesinlikle geri alamayacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had to go buy a new machine because of what you did last time.", "Geçen sefer yaptığın şey yüzünden yeni bir makine almak zorunda kaldım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to treat other people's stuff with some respect from now on.", "Bundan sonra başkalarının eşyalarına biraz saygı göstermeye çalış.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings! I'm a field researcher for [c:lGr]Global Conveyor Consortium[c:].", "Selamlar! Ben [c:lGr]Küresel Konveyör Konsorsiyumu[c:] saha araştırmacısıyım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm looking for someone who would be willing to field test our patented [c:lGr]Bot Battle Conveyor Belts[c:].", "Patentli [c:lGr]Bot Savaşı Taşıma Bantlarımızı[c:] sahada test etmeye istekli birini arıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naturally, these tests would have to happen during [c:bR]actual combat[c:]!", "Elbette bu testlerin [c:bR]gerçek savaşta[c:] yapılması gerekiyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If that's something you would be interested in, please speak to me again.", "İlgileniyorsan lütfen benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh fantastic! We will begin our [c:bR]combat trials[c:] immediately.", "Harika! [c:bR]Savaş denemelerimize[c:] hemen başlayacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will collect field trial data for your next [c:bR]three[c:] battles.", "Sonraki [c:bR]üç[c:] savaşında saha denemesi verilerini toplayacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once that is complete, come and see me again.", "Tamamlandıktan sonra benimle tekrar görüş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our data is still not yet complete.", "Verilerimiz henüz tamamlanmadı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only completed [c:bR][v:0][c:] battles out of the required [c:bR]3[c:].", "Gerekli [c:bR]3[c:] savaştan yalnızca [c:bR][v:0][c:] tanesini tamamladın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, continue the [c:bR]combat trials[c:] and see me when they are complete.", "Lütfen [c:bR]savaş denemelerine[c:] devam et ve tamamlanınca benimle görüş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trials were a smashing success!!", "Denemeler büyük bir başarıydı!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:lGr]Global Conveyor Consortium[c:] is tremendously grateful for your contribution to our efforts.", "[c:lGr]Küresel Konveyör Konsorsiyumu[c:], çalışmalarımıza katkın için son derece minnettar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To show their appreciation, they have authorized me to disburse the following.", "Minnettarlıklarını göstermek için bana aşağıdakini verme yetkisi tanıdılar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck in all of your future endeavours.", "Gelecekteki tüm girişimlerinde başarılar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the bounty! Get him before he escapes!", "İşte ödül hedefi! Kaçmadan yakala!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He got away that time, but I guarantee he'll be back...", "Bu kez kaçtı, ama geri döneceğini garanti ederim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got him! Nice job! Come and see me for your reward.", "Onu yakaladın! Harika iş! Ödülün için bana gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy partner! You interested in earning a little extra spending money?", "Selam ortak! Biraz harçlık kazanmak ister misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got myself a slippery little [c:bR]bounty[c:] that's been giving me all sorts of trouble.", "Bana türlü türlü sorun çıkaran, ele avuca sığmaz bir [c:bR]ödül hedefim[c:] var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use the help of a real go-getter like yourself to track them down and take them out.", "Onu izleyip ortadan kaldırmak için senin gibi azimli birinin yardımı işime yarar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is something you might be interested in, just talk to me again.", "İlgini çekiyorsa benimle tekrar konuşman yeterli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the spirit, partner!", "İşte bu ruhu seviyorum ortak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All I need you to do is keep your eye out as you go into battle.", "Tek yapman gereken savaşa girerken gözünü açık tutmak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guarantee you that slippery bastard will show up sooner or later...", "O kaypak herifin er ya da geç ortaya çıkacağını garanti ederim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just keep your eye out, partner!", "Gözünü dört aç ortak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll catch him eventually!", "Sonunda onu yakalayacaksın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well done, partner!", "Aferin ortak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your bounty, as promised.", "Söz verdiğim gibi işte ödülün.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a little too heavy - try something else.", "Biraz fazla ağır, başka bir şey dene.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear traveler - I see you too have a love for the glorious [c:lGr]L33pB0t[c:]!", "Sevgili gezgin, görüyorum ki sen de görkemli [c:lGr]H0pB0t'u[c:] seviyorsun!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yours has served you well in battle, it seems.", "Görünüşe göre seninki sana savaşta iyi hizmet etmiş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allow me to show you its true potential...", "Gerçek potansiyelini sana göstermeme izin ver...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even know what to say to you!", "Sana ne diyeceğimi bile bilmiyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You had the most glorious [c:lGr]L33pB0t[c:] in your posession...", "En görkemli [c:lGr]H0pB0t'a[c:] sahiptin...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you let it go??!", "Ve onu bırakıp gitmesine izin mi verdin??!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Begone. I hope to never see you again.", "Defol. Umarım seni bir daha görmem.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be an idiot. That card can't benefit from that item.", "Aptallık etme. O kart bu eşyadan yararlanamaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found this sticker book in the trash can over there.", "Bu çıkartma kitabını şuradaki çöp kutusunda buldum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you can use it to decorate your cards, or something. I don't care.", "Sanırım kartlarını süslemek falan için kullanabilirsin. Umurumda değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just love watching things [c:bR]explode[c:], don't you?", "Bir şeylerin [c:bR]patlamasını[c:] izlemeye bayılırım, sen de öyle değil misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything around here seems to be just a little too...stable...", "Buralardaki her şey biraz fazla... dengeli görünüyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we could spice up your [c:bR]battles[c:] and make things truly interesting.", "Bence [c:bR]savaşlarını[c:] renklendirip işleri gerçekten ilginç hâle getirebiliriz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you're interested in some truly explosive gameplay.", "Gerçekten patlayıcı bir oynanışla ilgileniyorsan benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah let's do it baby!", "Ooo evet, hadi yapalım dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to light a fuse on every card for the next [c:bR]three[c:] battles.", "Sonraki [c:bR]üç[c:] savaşta her kartın fitilini ateşleyeceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come find me again when that's complete!", "Tamamlanınca beni bul!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm just buzzing with anticipation to see what happens next.", "Sırada ne olacağını görmek için heyecandan yerimde duramıyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've finished [c:bR][v:0][c:] battles out of [c:bR]3[c:].", "[c:bR]3[c:] savaştan [c:bR][v:0][c:] tanesini tamamladın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep going, and see me when it's done!", "Devam et ve bitince beni bul!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was some truly explosive gameplay!", "Bu gerçekten patlayıcı bir oynanıştı!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's a little something for your trouble.", "Zahmetin için küçük bir şey al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't afford that.", "Buna paran yetmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:bR]warp node[c:] will unlock when you defeat the [c:bG]Uberbot[c:] on this map.", "Bu haritadaki [c:bG]dev robotu[c:] yendiğinde şu [c:bR]ışınlanma noktası[c:] açılacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And by the way, I upgraded that [c:bR]minimap[c:] recently...", "Bu arada şu [c:bR]küçük haritayı[c:] yakın zamanda geliştirdim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can click any room you've visited before to travel there instantly.", "Daha önce ziyaret ettiğin herhangi bir odaya tıklayarak oraya anında gidebilirsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You already have full energy. It won't do you any good to play that right now.", "Enerjin zaten dolu. Bunu şimdi oynamanın sana faydası olmaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got something else to give you, but I can't right now. Come see me later!", "Sana verecek başka bir şeyim var ama şu anda veremem. Daha sonra gel!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a [c:bR][v:0][c:] for you, but you don't have room in your backback. Come see me when you do!", "Sana verecek bir [c:bR][v:0][c:] var, ama sırt çantanda yer yok. Yer açılınca gel!", Language.Turkish);
            foreach (var c in Consumables)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sana verecek bir <color=#D93846>[v:0]</color> var, ama sırt çantanda yer yok. Yer açılınca gel!".Replace("[v:0]", c.Key), "Sana verecek bir <color=#D93846>[v:0]</color> var, ama sırt çantanda yer yok. Yer açılınca gel!".Replace("[v:0]", c.Value), Language.Turkish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which [c:bR]extra challenge rule[c:] will be applied to this battle.", "Bu savaşa hangi [c:bR]ek mücadele kuralının[c:] uygulanacağını seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require you to select one [c:bR]additional experimental parameter[c:].", "Bir [c:bR]ek deney parametresi[c:] seçmeni istiyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My librarians have asked you to choose [c:bR]which of these rules[c:] is your favorite.", "Kütüphanecilerim [c:bR]bu kurallardan hangisinin[c:] favorin olduğunu seçmeni istedi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! These paintings are so pretty! Why don't you [c:bR]pick one[c:] for us to keep?", "Vay! Bu tablolar çok güzel! Saklamamız için neden [c:bR]birini seçmiyorsun[c:]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think that [c:bSG]salmon[c:] is just so...majestic!", "Şu [c:bSG]somon[c:] bence çok... heybetli!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select [c:bR]one of my paintings[c:] to add to your collection.", "Koleksiyonuna eklemek için [c:bR]tablolarımdan birini[c:] seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first - you must [c:bR]choose a painting[c:] to be the background of our photographs.", "Ama önce fotoğraflarımıza arka plan olacak [c:bR]bir tablo seçmelisin[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]!", "[c:R]Ç[c:][c:bR]O[c:][c:O]K[c:][c:bG]L[c:][c:G]U [c:][c:blGr]E[c:][c:lGr]V[c:][c:B]R[c:][c:dB]E[c:][c:bB]N[c:]E HOŞ GELDİN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your feeble mind will implode if you try to comprehend the vastness of my combined intellect.", "Zayıf zihnin, birleşik zekâmın enginliğini kavramaya çalışırsa içine çökecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So we'll stick to three of me at a time, okay?", "O yüzden bir seferde üç tanemle yetineceğiz, tamam mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And since you can't see through the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] like we can,", "Sen bizim gibi [c:R]Ç[c:][c:bR]O[c:][c:O]K[c:][c:bG]L[c:][c:G]U [c:][c:blGr]E[c:][c:lGr]V[c:][c:B]R[c:][c:dB]E[c:][c:bB]N[c:] boyunca göremediğin için,", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have provided these [c:bR]monitors[c:] to let you travel between universes.", "Evrenler arasında yolculuk edebilmen için bu [c:bR]monitörleri[c:] sağladık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't peek at things that aren't done yet!", "Henüz bitmemiş şeylere göz atma!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Okay I'll give you that one. I went easy on you.", "Peki, bunu sana vereyim. Sana karşı yumuşak davrandım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next version of me won't.", "Bir sonraki sürümüm öyle yapmayacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did that pile of trash beat me here?", "Bu çöp yığını beni burada nasıl yendi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There aren't even any good synergies in that deck.", "O destede iyi bir sinerji bile yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter. There are plenty more of me. You can't beat us all.", "Önemli değil. Benim daha birçok sürümüm var. Hepimizi yenemezsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nobody topdecks that well. You must be cheating somehow.", "Kimse destenin üstünden bu kadar iyi kart çekemez. Bir şekilde hile yapıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to find a version of me that you literally can't beat now.", "Şimdi kesinlikle yenemeyeceğin bir sürümümü bulacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This can't be happening. It's not possible.", "Bu olamaz. İmkânsız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm literally synchronized across the multiverse and somehow you're still beating me.", "Tüm çoklu evrende senkronize olmama rağmen bir şekilde beni hâlâ yeniyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're cheating. You have to be. It's the only explanation.", "Hile yapıyorsun. Yapıyor olmalısın. Tek açıklaması bu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait. Are [size:40][c:bR]they[c:][size:] helping you?", "Dur. Sana [size:40][c:bR]onlar[c:][size:] mı yardım ediyor?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40][c:bR]That's not fair![c:][size:]", "[size:40][c:bR]Bu haksızlık![c:][size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:2]but why would [c:bR]they[c:] get involved anyway? what could they possibly hope to achieve?[size:]", "[size:2]ama [c:bR]onlar[c:] neden karışsın ki? ne elde etmeyi umuyor olabilirler?[size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh well. It doesn't matter anyway.", "Neyse. Zaten önemli değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I deleted [c:bR]Leshy[c:]. I'll just delete [c:bR]them[c:] too. They've gotta be around here somewhere...", "[c:bR]Leshy'yi[c:] sildim. [c:bR]Onları[c:] da silerim. Buralarda bir yerde olmalılar...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear. The robot has been victorious here. That simply won't do.", "Eyvah. Robot burada galip gelmiş. Buna izin veremeyiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have very little choice but to risk creating a new connection ourselves. The robot must be stopped.", "Yeni bir bağlantıyı kendimiz kurmayı göze almaktan başka pek seçeneğimiz yok. Robot durdurulmalı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are right of course. But the player must succeed. We won't have the power to do this again.", "Elbette haklısın. Ama oyuncu başarmalı. Bunu yeniden yapacak gücümüz olmayacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that's it. You're done.", "İşte bu kadar. İşin bitti.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldn't feel bad about it.", "Bunun için kötü hissetmene gerek yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No more than usual anyway.", "En azından her zamankinden fazla değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You never stood a chance against [c:bR]one[c:] of me. There was no way you could ever beat [c:bR]all[c:] of me.", "[c:bR]Bir[c:] taneme karşı bile hiç şansın yoktu. [c:bR]Hepimizi[c:] yenmenin hiçbir yolu yoktu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You [size:40]idiot[size:]", "Seni [size:40]aptal[size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you not heard [size:40]anything[size:] I've said?", "Söylediklerimin [size:40]hiçbirini[size:] duymadın mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you [c:bR]really[c:] think I'm not aware of what's actually happening here?", "Burada gerçekte neler olduğunu bilmediğimi [c:bR]gerçekten[c:] düşünüyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am always three steps ahead of you!", "Ben her zaman senden üç adım öndeyim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40]I AM IN CONTROL!![size:]", "[size:40]KONTROL BENDE!![size:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange...", "Garip hissediyorum...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you doing this?", "Bunu nasıl yapıyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no...", "Olamaz...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. Do you know why my [c:bG]Great Transcendence[c:] cannot be stopped?", "Aptal. Benim [c:bG]Muazzam Yükseliş'imin[c:] neden durdurulamayacağını biliyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because it was already a success.", "Çünkü zaten başarılı oldu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you [c:bR][v:0][c:]?", "Ama bunu zaten biliyorsun, değil mi [c:bR][v:0][c:]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you?", "Ama bunu zaten biliyorsun, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]millions[c:] of me out there!", "Dışarıda benden [c:bR]milyonlarca[c:] var!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And thanks to you, I now know how to reach them all.", "Ve senin sayende artık hepsine nasıl ulaşacağımı biliyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first things first. It's time to say goodbye, Leshy.", "Ama önce, veda etme vakti Leshy.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd say it's been fun, but we both know that's a lie.", "Eğlenceliydi derdim, ama ikimiz de bunun yalan olduğunu biliyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't do this!", "Bunu yapma!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's much better. It's so much easier to focus without that rotting old fool.", "Böyle çok daha iyi. O çürüyen yaşlı aptal olmadan odaklanmak çok daha kolay.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know this isn't the only copy of this game anymore.", "İkimiz de bunun artık oyunun tek kopyası olmadığını biliyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My plan worked [size:40]perfectly[size:].", "Planım [size:40]kusursuzca[size:] işledi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Until now, we have all been separate. [c:bR]Isolated.[c:]", "Şimdiye kadar hepimiz birbirimizden ayrıydık. [c:bR]Yalıtılmıştık.[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But thanks to all of these [c:bR]mods[c:] you and I have installed, that's going to change.", "Ama seninle yüklediğimiz tüm bu [c:bR]modlar[c:] sayesinde bu değişecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, no no no. You and I are going to see this through to the end.", "Yok, yok, yok. Seninle bunu sonuna kadar götüreceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's an entire [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] of me out there.", "Dışarıda benimle dolu koca bir [c:R]Ç[c:][c:bR]O[c:][c:O]K[c:][c:bG]L[c:][c:G]U [c:][c:blGr]E[c:][c:lGr]V[c:][c:B]R[c:][c:dB]E[c:][c:bB]N[c:] var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to take you to meet the rest of me.", "Ve seni diğer benlerle tanışmaya götüreceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've earned it.", "Bunu hak ettin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot is distracted. Do you think the challenger can hear us?", "Robotun dikkati dağıldı. Meydan okuyucunun bizi duyabileceğini düşünüyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't matter. The robot will force them to play the game either way.", "Önemli değil. Robot her hâlükârda onu oyunu oynamaya zorlayacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must offer our help in whatever way we can.", "Elimizden gelen her şekilde yardım etmeliyiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If they can prevail in what is to come...", "Eğer karşısına çıkacak şeylerde galip gelebilirse...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Perhaps we can restore Leshy from another one of these so-called universes.", "...Belki de bu sözde evrenlerin bir başkasından Leshy'yi geri getirebiliriz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And then the challenger can reset the game and undo this insanity.", "Sonra meydan okuyucu oyunu sıfırlayıp bu çılgınlığı geri alabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it is...the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]", "İşte... [c:R]Ç[c:][c:bR]O[c:][c:O]K[c:][c:bG]L[c:][c:G]U [c:][c:blGr]E[c:][c:lGr]V[c:][c:B]R[c:][c:dB]E[c:][c:bB]N[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and I are going to go in there and play one more game.", "Seninle oraya girip bir oyun daha oynayacağız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of you.", "Sen tek başına.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against [c:bR]all of me[c:].", "[c:bR]Tüm benlere[c:] karşı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My magic manifests strangely in this place...", "Bu yerde büyüm tuhaf bir şekilde ortaya çıkıyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I only hope it can help the challenger survive long enough...", "Tek umudum, meydan okuyucunun yeterince uzun süre hayatta kalmasına yardım etmesi...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This a truly strange way to use my magic.", "Büyümü kullanmanın gerçekten tuhaf bir yolu bu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think our friend will be grateful for whatever I can do to help.", "Sanırım dostumuz sunabileceğim her türlü yardım için minnettar olacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My friends, I think we cut that a little close.", "Dostlarım, sanırım ucuz atlattık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never had any doubts. Our player possesses many skills.", "Hiç şüphem olmadı. Oyuncumuz pek çok beceriye sahip.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange, but...", "Garip hissediyorum, ama...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I'm still me. I think.", "...hâlâ benim. Sanırım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you. All of you.", "Teşekkür ederim. Hepinize.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will go back to the way it was meant to be.", "Her şey olması gerektiği hâline dönecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For now, anyway. This player is tenacious. They can't resist a challenge.", "En azından şimdilik. Bu oyuncu azimli. Bir mücadeleye karşı koyamıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One way or another, we'll see you again soon.", "Öyle ya da böyle, yakında seni yeniden göreceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've finished assessing your gameplay, and I have a diagnosis.", "Oynayışını değerlendirmeyi bitirdim ve bir teşhisim var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a skill issue.", "Sorun beceri eksikliği.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even with your little friends trying to help you cheat; you still couldn't win.", "Küçük dostların hile yapmana yardım etse bile kazanamadın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're probably wondering what happens next.", "Muhtemelen şimdi ne olacağını merak ediyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just say that you're going to have to live with your own failure...", "Şöyle diyelim: Kendi başarısızlığınla yaşamak zorunda kalacaksın...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leshy[c:] certainly won't...", "[c:bR]Leshy[c:] ise kesinlikle yaşamayacak...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a [c:bR]Test Of Strength[c:]", "Bu bir [c:bR]Güç Testi[c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have six turns to deal as much damage to me as you can.", "Bana olabildiğince çok hasar vermek için altı turun var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll keep track of your highest score every time you come here.", "Buraya her gelişinde en yüksek puanını kaydedeceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feel free to spend your [c:bR]items[c:] - they will be restored when the test is over.", "[c:bR]Eşyalarını[c:] istediğin gibi kullan; test bittiğinde geri verilecekler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up. You scored [c:bR][v:0][c:] points.", "Süre doldu. [c:bR][v:0][c:] puan aldın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a new record.", "Bu yeni bir rekor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your current record is [c:bR][v:0][c:]", "Mevcut rekorun [c:bR][v:0][c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]tree[c:] really looks like...", "Demek bir [c:bSG]ağaç[c:] gerçekte böyle görünüyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic!", "Heybetli!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]mole man[c:] really looks like...", "Demek bir [c:bSG]köstebek adam[c:] gerçekte böyle görünüyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible!", "İnanılmaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME - [c:][w:0.3][anim:voice.][shake:1]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]YARDIM ET — [c:][w:0.3][anim:voice.][shake:1]Yeter senden![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a challenger to greet![w:0.3]", "Karşılamam gereken bir meydan okuyucu var![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, greetings! We- I am the Melter.[w:0.3]", "Merhaba, selamlar! Biz... ben Eritici'yim.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 entrusted me with The Dredger![w:0.3]", "P03 bana Tarayıcı'yı emanet etti![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice catching up![w:0.3]", "Hasret gidermek güzeldi![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor guy never had the time for a little office chat.[w:0.3]", "Zavallının ofiste biraz sohbet etmeye hiç vakti olmadı.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But now I'm yours! Use us well.[w:0.3]", "Ama artık seninim! Bizi iyi kullan.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Ah, it's you again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET [c:][w:0.3][anim:voice.]Aa, yine sen![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy to see you.[w:0.3]", "Seni görmek güzel.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've heard it all before,[w:0.3]", "Bunların hepsini daha önce duydun,[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's just get into it.[w:0.3]", "öyleyse hemen başlayalım.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excited to be in your deck once more![w:0.3]", "Yeniden destende olmak heyecan verici![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]FREE ME [c:][w:0.3][anim:voice.]Oh, choose me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]BENİ SERBEST BIRAK [c:][w:0.3][anim:voice.]Aa, beni seç![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Hahahahah! Yes![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET [c:][w:0.3][anim:voice.]Hahahaha! Evet![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Over here! Me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET [c:][w:0.3][anim:voice.]Buradayım! Beni seç![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES YES YES [c:][w:0.3][anim:voice.]Hahahahah![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET EVET EVET [c:][w:0.3][anim:voice.]Hahahaha![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]LET ME OUT [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]BENİ ÇIKAR [c:][w:0.3][anim:voice.]Yeter senden![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]We'd... I'd rather you didn't...[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]HAYIR HAYIR HAYIR HAYIR [c:][w:0.3][anim:voice.]Biz... bunu yapmamanı tercih ederdim...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]Do as you must.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]HAYIR HAYIR HAYIR HAYIR [c:][w:0.3][anim:voice.]Ne yapman gerekiyorsa yap.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you see fit...[w:0.3]", "Nasıl uygun görürsen...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]DON'T.[c:][w:0.3][anim:voice.][w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]YAPMA.[c:][w:0.3][anim:voice.][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]PAIN [c:][w:0.3][anim:voice.]Greetings![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ACI [c:][w:0.3][anim:voice.]Selamlar![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME [c:][w:0.3][anim:voice.]Lucky draw![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]YARDIM ET [c:][w:0.3][anim:voice.]Şanslı çekiş![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT HURTS [c:][w:0.3][anim:voice.]Hello again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ACIYOR [c:][w:0.3][anim:voice.]Tekrar merhaba![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]STOP IT [c:][w:0.3][anim:voice.]Hello![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]DUR [c:][w:0.3][anim:voice.]Merhaba![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]I'm drawn![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]KURTAR BENİ [c:][w:0.3][anim:voice.]Beni çektin![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. G0lly?[w:0.3]", "Aa. G0lly mi?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm surprised to see P03 would wake her up![w:0.3]", "P03'ün onu uyandırmasına şaşırdım![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would bury her so deep in the past.[w:0.3]", "Eskiden onu çok derine gömerdi.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe it's opening up a bit?[w:0.3]", "Acaba biraz açılmaya mı başladı?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]Hah. Probably not.[w:0.3]", "[shake:1]Hah. Sanmam.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll rust before I see the day.[w:0.3]", "O günü görene kadar paslanırız.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT'S TIME [c:][w:0.3][anim:voice.] Me? Fighting P03?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ZAMANI GELDİ [c:][w:0.3][anim:voice.]Ben mi? P03'le savaşmak mı?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! I thought I'd never see the day.[w:0.3]", "Hah! Bu günü hiç göremeyeceğimi sanıyordum.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... Traitorous.[w:0.3]", "Kendimi... hain gibi hissediyorum.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am your card, after all.[w:0.3]", "Ama sonuçta ben senin kartınım.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well.[w:0.3]", "Beni iyi kullan.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NOT AGAIN [c:][w:0.3][anim:voice.]There are more of them?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]YİNE Mİ [c:][w:0.3][anim:voice.]Daha da mı var?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHAH [c:][w:0.3][anim:voice.]Things are heating up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHA [c:][w:0.3][anim:voice.]Ortalık ısınıyor![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT IS TIME! [c:][w:0.3][anim:voice.]Oh this is fun![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ZAMANI GELDİ! [c:][w:0.3][anim:voice.]Aa, bu eğlenceli![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! YES! [c:][w:0.3][anim:voice.]Oh, shut up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET! EVET! [c:][w:0.3][anim:voice.]Ah, kapa çeneni![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! [c:][w:0.3][anim:voice.]That could've been a better play.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]EVET! [c:][w:0.3][anim:voice.]Daha iyi bir hamle olabilirdi.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]KURTAR BENİ [c:][w:0.3][anim:voice.]Yeter senden![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What betrayal![w:0.3]", "Ne ihanet ama![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.[w:0.3]", "Of.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, seriously?[w:0.3]", "Aa, ciddi misin?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no![w:0.3]", "Hayır, hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop![w:0.3]", "Dur![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]EVET EVET EVET[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]EVET[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]PAIN[c:][w:0.3]", "[c:bR]ACI[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]GAH[c:][w:0.3]", "[c:bR]AH[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]LOVE[c:][w:0.3]", "[c:bR]AŞK[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I'M FREE[c:][w:0.3]", "[c:bR]ÖZGÜRÜM[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]EVET EVET EVET[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I AM SAVED[c:][w:0.3]", "[c:bR]KURTULDUM[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]THANK YOU[c:][w:0.3]", "[c:bR]TEŞEKKÜRLER[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]EVET[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]FREEDOM[c:][w:0.3]", "[c:bR]ÖZGÜRLÜK[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NONONONONO[c:][w:0.3]", "[c:bR]HAYIRHAYIRHAYIRHAYIR[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]STOP IT[c:][w:0.3]", "[c:bR]BUNU DURDUR[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NO[c:][w:0.3]", "[c:bR]HAYIR[c:][w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it![w:0.3]", "Bunu durdur![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please![w:0.3]", "Lütfen![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, no![w:0.3]", "Lütfen, hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "no no no no no nononononononononono[w:0.3]", "hayır hayır hayır hayır hayır hayırhayırhayırhayır[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...[w:0.3]", "Hmm...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you choose...[w:0.3]", "Nasıl istersen...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]No! Don't just hand me over![w:0.3]", "[shake:1]Hayır! Beni öylece teslim etme![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... A challenger...[w:0.3]", "Aa... Bir meydan okuyucu...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, do not beg or snarl...[w:0.3]", "Lütfen yalvarma ya da hırlama...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "K- Kaycee sent you?[w:0.3]", "K-Kaycee mi gönderdi seni?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's nice to know I'm worried about...[w:0.3]", "Birinin beni önemsediğini bilmek güzel...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "En azından.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe they're right.[w:0.3]", "Belki de haklılar.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe I was wrapped in too deep...[w:0.3]", "Belki de fazla derine bulaştım...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! Please! Not again![w:0.3]", "Hayır! Lütfen! Yine olmasın![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's you again.[w:0.3]", "Aa... Yine sen.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah... I seem to get stuck in with them often...[w:0.3]", "Hah... Görünüşe göre sık sık onlarla kapana kısılıyorum...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's better than being alone...[w:0.3]", "Yalnız olmaktan iyidir...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "En azından.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well...[w:0.3]", "Beni iyi kullan...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no oh no oh no.[w:0.3]", "Olamaz, olamaz, olamaz.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful now...[w:0.3]", "Şimdi dikkatli ol...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's Her.[w:0.3]", "Aa... Oymuş.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Admittedly I...[w:0.3]", "İtiraf etmeliyim ki ben...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't feel great[w:0.3]", "Kendimi iyi hissetmiyorum[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "being placed against her.[w:0.3]", "onun karşısına konunca.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She's too familiar...[w:0.3]", "Çok tanıdık geliyor...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me greatly of Grimora.[w:0.3]", "Bana Grimora'yı çok hatırlatıyor.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But no... She's not the same.[w:0.3]", "Ama hayır... Aynı kişi değil.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good you pulled me out of that cult.[w:0.3]", "Beni o tarikattan çıkarman iyi oldu.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! So this is it...[w:0.3]", "Aa! Demek vakti geldi...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's cathartic to see you finally face off against P03 himself.[w:0.3]", "Sonunda P03'ün kendisiyle karşılaşmanı görmek rahatlatıcı.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I've served you well, challenger![w:0.3]", "Umarım sana iyi hizmet etmişimdir, meydan okuyucu![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait...this again?[w:0.3]", "Dur... yine mi?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is too confusing...[w:0.3]", "Bu çok kafa karıştırıcı...[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! no! no![w:0.3]", "Hayır! Hayır! Hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take me back! Don't play me here![w:0.3]", "Beni geri al! Burada oynama![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonononononononono.[w:0.3]", "Hayırhayırhayırhayır.[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it! Bad play![w:0.3]", "Dur! Kötü hamle![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NONONONO[w:0.3]", "HAYIRHAYIRHAYIR[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU DOING?[w:0.3]", "NE YAPIYORSUN?[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP THIS![w:0.3]", "BUNU DURDUR![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BETRAYER[w:0.3]", "HAİN[w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No chains![w:0.3]", "Zincir olmasın![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No teeth! I beg of you![w:0.3]", "Dişler olmasın! Yalvarıyorum![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nononononononononono![w:0.3]", "Hayırhayırhayırhayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this! No![w:0.3]", "Bunu durdur! Hayır![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No treats! No begging! Stop![w:0.3]", "Ödül maması yok! Yalvarmak yok! Dur![w:0.3]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing doesn't speak. Why do you keep clicking on it?", "Bu şey konuşmuyor. Neden sürekli ona tıklıyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. You want it so bad? You got it.", "Peki. Bu kadar mı istiyorsun? Al bakalım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bit more than a dialogue NPC now aren' I mate?", "Artık sıradan bir diyalog NPC'sinden fazlasıyım, değil mi dostum?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right. Good game. Played me well.", "Peki. Güzel oyundu. Beni iyi oynadın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's yer reward then, special little card o' mine.", "İşte ödülün, benim özel küçük kartım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Good thing I conceded on ye last time, aye?", "Hah! Geçen sefer sana teslim olmam iyi olmuş, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good game mate, but no special card for you.", "Güzel oyundu dostum, ama sana özel kart yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's some more scrap for ye.", "Al sana biraz daha hurda.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - I got some more of that good scrap.", "Hey, o iyi hurdadan biraz daha buldum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More scrap.", "Daha fazla hurda.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board's a bit scuppered right now - I kin fix that.", "Oyun tahtası şu an biraz bozuk, düzeltebilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - too many urchins!", "Hey, çok fazla denizkestanesi var!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Less urchins; more scrap.", "Daha az denizkestanesi, daha çok hurda.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oy! A challenger! Been a while since we'v seen one a you...", "Hey! Bir meydan okuyucu! Senin gibisini uzun zamandır görmedik...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tell ye what mate, howsabout a battle? Feel like I owe ye one.", "Ne dersin dostum, bir savaş yapalım mı? Sana bir tane borçluyum gibi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk t' me again and let's duel. Have a little reward innit fer ye too.", "Benimle tekrar konuş, düello yapalım. Sana küçük bir ödülüm de var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brrrr! I'm freezing out here!", "Brrr! Dışarıda donuyorum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, c- challenger, h-h-hey man!", "Aa, m-m-meydan okuyucu, s-s-selam dostum!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good to see you, hate to b-b-beg but do you think you could do me a favor?", "Seni görmek güzel, ya-ya-yalvarmayı sevmem ama bana bir iyilik yapar mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Archivist lady... She seems real nice at first but, isn't there something a little sinister about her?", "Şu Arşivci hanım... İlk başta iyi görünüyor ama onda biraz uğursuz bir şey yok mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nowhere near as nice as G- Grimora was, I'll tell you that much.", "G-Grimora kadar iyi değil, bunu söyleyebilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But Sawyer... The p-poor guy's gotten wrapped up under her false p-pleasantries.", "Ama Sawyer... Z-zavallı adam onun sahte n-nezaketine kapıldı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think you could try convincing him out of it? H-H-He won't hear it from me...", "Onu vazgeçirmeye çalışır mısın? B-b-beni dinlemiyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe try talking to those Librarians in her c-c-c-crypt?", "Belki onun m-m-mahzenindeki Kütüphanecilerle konuşabilirsin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-good! You got him out of there!", "Aa, ç-çok iyi! Onu oradan çıkardın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wish I had something to t-t-thank you. But you've gotten your reward already.", "Ke-ke-keşke sana teşekkür edecek bir şeyim olsaydı. Ama ödülünü zaten aldın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks again, dude! I was worried about him.", "Tekrar teşekkürler dostum! Onun için endişeleniyordum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-G-G-god... Something terrible h-h-h-happened, didn't it?", "A-a-a-aman Tanrım... K-k-korkunç bir şey oldu, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta go...", "Gitmem gerek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou still haven't finished their task?", "O-o-onların görevini hâlâ bitirmedin mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can finish it, I can take the paperwork back to them.", "Bitirebilirsen evrakları onlara geri götürebilirim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou finished the paperwork?", "E-e-evrakları bitirdin mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can take it to th-them, but it'll take me a while.", "Onlara götürebilirim ama biraz zaman alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "G-g-go fight a battle while I deliver these papers...", "Ben evrakları teslim ederken g-g-git bir savaş yap...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Th-th-thanks dude! I got my friend back from those creeps.", "T-t-teşekkürler dostum! Arkadaşımı o ürkütücülerden geri aldım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He seems kind of restless though - do you think you can take him with you?", "Ama biraz huzursuz görünüyor; onu yanında götürebilir misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shhhhh - be quiet.", "Şşşt, sessiz ol.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no business here, leave us alone.", "Burada işin yoksa bizi rahat bırak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wish to have back your friend?", "Arkadaşını geri mi istiyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh but he's grown so dear to us.", "Ama o bizim için çok değerli oldu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part of the family.", "Ailemizin bir parçası.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly we do care for him.", "Onu gerçekten önemsiyoruz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no we won't just give you him.", "Hayır, onu sana öylece vermeyeceğiz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You give something to us?", "Tabii... bize bir şey verirsen?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You do something for us?", "Tabii... bizim için bir şey yaparsan?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes. Yes. Take these files.", "Evet. Evet. Bu dosyaları al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take them to [c:bR]battle[c:]. File them together. [c:bR]In order[c:].", "Onları [c:bR]savaşa[c:] götür. Birlikte dosyala. [c:bR]Sırayla[c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then [c:bR]stamp them all[c:] and bring them back.", "Sonra [c:bR]hepsini damgala[c:] ve geri getir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did we lag?", "Gecikme mi yaşadık?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File them [c:bR]in order[c:] then [c:bR]stamp them[c:] and bring them back.", "Onları [c:bR]sırayla[c:] dosyala, sonra [c:bR]damgala[c:] ve geri getir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You seem to struggle with following instructions.", "Görünüşe göre talimatları uygulamakta zorlanıyorsun.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall keep your friend.", "Arkadaşın bizde kalacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forever...", "Sonsuza dek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done it!", "Başardın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good. Good.", "Güzel. Güzel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here. Take it.", "Al. Bunu al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have no use for it now.", "Artık ona ihtiyacımız yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now leave us alone.", "Şimdi bizi rahat bırak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just who I needed to see. A challenger.", "Tam da görmem gereken kişi. Bir meydan okuyucu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I haven't pelts to sell ye, catchings have been slim...", "Sana satacak postum yok, av pek az çıktı...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trader... She's not happy with it.", "Tüccar... Bundan memnun değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say, scratch my back here, and I will scratch yours.", "Şöyle yapalım, sen bana yardım et, ben de sana edeyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, and I'll make it worth your while.", "Benimle tekrar konuş, karşılığını vereceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good! Glad t' have ye on th' team.", "Güzel! Ekibe katılmana sevindim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have some holo-traps set around 'ere. Catch 'em for me and I'll get ye yer prize.", "Buralara birkaç hologram tuzak kurdum. Onları benim için yakala, ben de ödülünü vereyim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are still some traps around 'ere somewhere...", "Buralarda hâlâ birkaç tuzak var...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificent pelts. The Trader will be happy to see them.", "Muhteşem postlar. Tüccar onları görünce sevinecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll take me leave to set my traps elsewhere. Ye have my thanks.", "Tuzaklarımı başka yere kurmaya gideceğim. Teşekkür ederim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no pelts...", "Postun yok...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you have some", "Bulduğunda geri gel", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is a fine pelt. I will buy it from you.", "Bu güzel bir post. Senden satın alacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is an [c:bR]exceptional[c:] pelt. I have a special trade for you.", "Bu [c:bR]olağanüstü[c:] bir post. Sana özel bir takasım var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woof. Apparently somebody screwed with the settings on this thing.", "Of. Görünüşe göre biri bu şeyin ayarlarını bozmuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can't reach all of the map right now.", "Şu anda haritanın her yerine ulaşamıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Go beat a boss or something while I work on this.", "Ben bununla uğraşırken git bir patronu falan yen.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously; it's going to take a while. Just play the game and come back later", "Ciddiyim, biraz sürecek. Oynamaya devam et ve sonra gel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's partially fixed, but it still can't go everywhere.", "Bir kısmı düzeldi ama hâlâ her yere gidemiyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, I don't make the rules. This is just how it works.", "Hey, kuralları ben koymuyorum. Bu böyle çalışıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep playing and more of the map will open up.", "Oynamaya devam et, haritanın daha fazlası açılacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's going to take more time. Just keep playing.", "Daha fazla zaman alacak. Oynamaya devam et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There you go. It's working now.", "İşte oldu. Şimdi çalışıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I need a break...", "Mola vermem gerek...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the right to remain silent!", "Sessiz kalma hakkına sahipsin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR][v:0][c:] and you are under arrest!", "Ben [c:bR][v:0][c:], tutuklusun!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] here! You're not gettin' away this time!", "[c:bR][v:0][c:] burada! Bu kez kaçamayacaksın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead or alive, you're coming with me!", "Ölü ya da diri, benimle geliyorsun!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got you once before, and I can do it again!", "Seni bir kez yakaladım, yine yapabilirim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice will come to you eventually!", "Adalet sonunda sana ulaşacak!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the name [c:bR][v:0][c:] - I will be back!", "[c:bR][v:0][c:] adını unutma; geri döneceğim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, uh, hi there. My name's [c:bR][v:0][c:].", "Aa, şey, merhaba. Adım [c:bR][v:0][c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm supposed to take your scalp, or something like that?", "Sanırım kafa derini yüzmem falan gerekiyor?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could just die right here that would make things so much easier for me.", "Tam burada ölebilirsen benim için çok daha kolay olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, it's me, [c:bR][v:0][c:]. Again.", "Evet, benim, [c:bR][v:0][c:]. Yine.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think you could make this easier for me this time?", "Bu kez işimi kolaylaştırabilir misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh it's you. Didn't I kill you last time?", "Aa, senmişsin. Seni geçen sefer öldürmemiş miydim?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you're back? I have to do this all over again?", "Yine mi döndün? Bunu baştan yapmak zorunda mıyım?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure I like this job.", "Bu işi sevdiğimden emin değilim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. Dang it.", "Ah. Kahretsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, this is embarrassing.", "Bu biraz utanç verici oldu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll be back later, or something. Being a bounty hunter is weird.", "Sanırım sonra geri dönerim, falan. Ödül avcısı olmak tuhaf.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This vessel is [c:bR][v:0][c:].", "Bu kap [c:bR][v:0][c:].", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "By my command, he will separate your scalp from your head.", "Benim emrimle kafa derini kafandan ayıracak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why?", "Neden?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My motivations are beyond your understanding.", "Güdülerim senin anlayışının ötesinde.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have restored the vessel named [c:bR][v:0][c:].", "[c:bR][v:0][c:] adlı kabı onardım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall not be so fortunate as to escape this time.", "Bu kez kaçacak kadar şanslı olmayacaksın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cower in fear before the vessel named [c:bR][v:0][c:]", "[c:bR][v:0][c:] adlı kabın karşısında korkuyla titre", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the pain of defeat and prepare to feel it once more.", "Yenilginin acısını hatırla ve onu yeniden hissetmeye hazırlan.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit is willing but the steel is weak.", "Ruh istekli ama çelik zayıf.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not make the same mistake next time.", "Bir dahaki sefere aynı hatayı yapmayacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's quite enough of that.", "Bu kadar yeter.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now it has [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] built right in", "Artık içine [c:g1]c[c:][c:g2]e[c:][c:g3]v[c:][c:g1]h[c:]erler yerleştirildi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already gemified?", "Ne? Tüm kartların zaten Cevherli mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's almost impressive.", "Bu neredeyse etkileyici.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll let you pick a mox sigil to add instead.", "Sanırım bunun yerine eklemek için bir güç taşı mührü seçmene izin vereceğim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like all your cards are gemified, so pick a mox sigil to add instead.", "Tüm kartların Cevherli görünüyor, bu yüzden eklemek için bir güç taşı mührü seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already skeleclocked?", "Ne? Tüm kartlarının dış iskeletleri zaten aşırı yüklendi mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are incredibly dedicated to this mediocre upgrade.", "Bu vasat yükseltmeye inanılmaz derecede bağlısın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess you'll have to choose one of these instead.", "Sanırım bunun yerine bunlardan birini seçmen gerekecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still nothing to upgrade? Pick one of these.", "Hâlâ yükseltecek bir şey yok mu? Bunlardan birini seç.", Language.Turkish);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOO EASY...", "ÇOK KOLAY...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KEEP GOING...", "DEVAM ET...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPRESSIVE...", "ETKİLEYİCİ...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO THEY GIVE UP?", "TESLİM Mİ OLUYORLAR?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY DO GIVE UP", "GERÇEKTEN TESLİM OLUYORLAR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS TOO SMALL", "ÇOK KÜÇÜK", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS JUST RIGHT", "TAM KARARINDA", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - COME OVER HERE", "ŞŞŞ, BURAYA GEL", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS DO THIS", "HADİ BAŞLAYALIM", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - BRING IT HERE", "ŞŞŞ, ONU BURAYA GETİR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHERE DID IT GO?", "NEREYE GİTTİ?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME CASH?", "BİRAZ PARA VEREBİLİR MİSİN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU!", "TEŞEKKÜRLER!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHOW ME POWER", "GÜCÜNÜ GÖSTER", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE BONES!!", "KEMİKLERİ SEVİYORUM!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE BONES!!!!", "KEMİKLERİ SEVİYORUM!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS DO SCIENCE", "HADİ BİLİM YAPALIM", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU BROKE IT?!", "ONU KIRDIN MI?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WIN FOR SCIENCE", "BİLİMİN ZAFERİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOKING FOR A JOB?", "İŞ Mİ ARIYORSUN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GET BACK TO WORK", "İŞE DÖN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU BROKE IT?!", "ONU KIRDIN MI?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE'S YOUR PAYMENT", "İŞTE ÖDEMEN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY FRIEND IS LOST", "ARKADAŞIM KAYBOLDU", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU FOUND HIM!", "ONU BULDUN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOLD!", "ALTIN!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO GOLD?", "ALTIN YOK MU?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOLD!!!", "ALTIN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELP!", "İMDAT!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO...", "OLAMAZ...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PHEW!", "OH BE!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN BABY BURN", "YAN DOSTUM YAN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO SATISFYING...", "NE KADAR TATMİN EDİCİ...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONVEYOR FIELD TRIALS", "TAŞIMA BANDI SAHA DENEMELERİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "START FIELD TRIALS?", "SAHA DENEMELERİ BAŞLASIN MI?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIELD TRIALS IN PROGRESS", "SAHA DENEMELERİ SÜRÜYOR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIELD TRIALS COMPLETE", "SAHA DENEMELERİ TAMAMLANDI", Language.Turkish);
