            foreach (var value in P03InKayceesModMod.Cards)
            {
                string name;
                string nameLoc;
                if (value.Key != null && value.Key.ToLowerInvariant().Contains("skel-e"))
                {
                    name = "Skel-E-" + value.Key.Replace(" ", "-");
                    nameLoc = value.Value + " İskelet";
                }
                else
                {
                    name = "Skele " + value.Key;
                    nameLoc = value.Value + " Dış İskelet";
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, nameLoc, Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beta " + value.Key, "Beta " + value.Value, Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser " + value.Key, "Küçük " + value.Value, Language.Turkish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder " + value.Key, "Yaşlı " + value.Value, Language.Turkish);
                for (int score = 0; score <= 100; score++)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.Key + " " + score.ToString() + ".0", value.Value + " " + score.ToString() + ".0", Language.Turkish);
                }
                //string[] array = value.Key.Split(new char[] { ' ', '-' });
                //Debug.Log(((array.Length > 1) ? (array[0].ToLowerInvariant().Contains("gem") ? array[1] : array[0]) : (value.Key.Contains("bot") ? value.Key.Replace("bot", "") : value.Key)) + ", " + value.Key + ", " + value.Value);
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Gluk gluk gluk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We seem to have a [c:bR]tentacle[c:] problem", "Görünüşe göre bir [c:bR]dokunaç[c:] sorunumuz var", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to help out, talk to me again.", "Yardım etmek istersen benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you for your help", "Yardımın için teşekkürler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]3[c:] tentacles that need to be destroyed.", "Yok edilmesi gereken [c:bR]3[c:] dokunaç var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come talk to me again.", "Bunu yaptıktan sonra benimle tekrar konuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Gluk gluk gluk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have killed [c:bR][v:0][c:] tentacles.", "[c:bR][v:0][c:] dokunaç öldürdün.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See me once you've killed them all.", "Hepsini öldürdüğünde beni bul.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Gluk gluk gluk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scourge of the tentacles has been erased", "Dokunaç belası ortadan kaldırıldı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this as a token of my gratitude.", "Lütfen bunu teşekkürümün bir göstergesi olarak al.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]UYARI! UYARI![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Unidentified flying objects[c:] have been spotted in the area", "Bölgede [c:bR]tanımlanamayan uçan cisimler[c:] görüldü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should leave [c:bR]immediately[c:] before they return.", "Onlar dönmeden [c:bR]hemen[c:] gitmelisin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]UYARI! UYARI![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] are arriving!", "[c:bR]UFO'lar[c:] geliyor!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]CONGRATULATIONS![c:]", "[c:bR]TEBRİKLER![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] have been defeated!", "[c:bR]UFO'lar[c:] yenildi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And they event left one behind!", "Hatta arkalarında bir tane bıraktılar!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]DISASTER! DISASTER![c:]", "[c:bR]FELAKET! FELAKET![c:]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] were victorious!", "[c:bR]UFO'lar[c:] galip geldi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We may never recover from this failure!", "Bu başarısızlıktan belki de hiç kurtulamayacağız!", Language.Turkish);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLUG GLUG GLUG", "GLUK GLUK GLUK", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "DOKUNAÇLARLA SAVAŞ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "DOKUNAÇLARLA SAVAŞ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TO THE TENTACLES", "DOKUNAÇLARA ÖLÜM", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WARNING!!!", "UYARI!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE THEY COME!!!", "İŞTE GELİYORLAR!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS!!!", "TEBRİKLER!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DISASTER!!!", "FELAKET!!!", Language.Turkish);
        }
    }
