            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and fast", "Pizza Tower'ın güçlü ve hızlı hükümdarı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and holding a secret if it can evolve", "Pizza Tower'ın güçlü hükümdarı; evrimleşebilirse bir sırrı açığa çıkar.", Language.Turkish);
