            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The broken ruler of the Pizza Tower", "Pizza Tower'ın kırılmış hükümdarı.", Language.Turkish);
