    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Aga'nın Magnificus Genişletmesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "[count] özgün ve renkli büyücü içeren, Magnificus Modu için gayriresmî bir genişletme.", Language.Turkish);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Yükseliş Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Ascension Mage", "Yükseliş Büyücüsü", "Utilising the power of time they grant knowledge and experience from far beyond", "Zamanın gücünü kullanarak çok ötelere uzanan bilgi ve deneyim aktarırlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Zamanın gücünü kullanarak çok ötelere uzanan bilgi ve deneyim aktarırlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Kül Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Ash Mage", "Kül Büyücüsü", "Ashes he sheds from his own body, scorching any and all who oppose him", "Bedeninden dökülen küller ona karşı çıkan herkesi yakar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Bedeninden dökülen küller ona karşı çıkan herkesi yakar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Kırık Yumurta", Language.Turkish);
            MagnificusMod.RegisterCard("Broken Egg", "Kırık Yumurta", "Only the greatest of trainers might find this treasure", "Bu hazineyi yalnızca en büyük eğitmenler bulabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Bu hazineyi yalnızca en büyük eğitmenler bulabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Seçilmiş Kişi", Language.Turkish);
            MagnificusMod.RegisterCard("Chosen One", "Seçilmiş Kişi", "My selected favourite. He still clings to his elders though...", "Seçtiğim gözdem. Yine de büyüklerine bağlı kalıyor...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "Seçtiğim gözdem. Yine de büyüklerine bağlı kalıyor...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Temizlik Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Temizlik Büyücüsü", "The proudest of all my pupils. None come close to his bath superpowers", "Öğrencilerimin en gururlusu. Banyo süper güçleriyle kimse boy ölçüşemez.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "Öğrencilerimin en gururlusu. Banyo süper güçleriyle kimse boy ölçüşemez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Rahip", Language.Turkish);
            MagnificusMod.RegisterCard("Cleric", "Rahip", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "İlahi büyüsünün gücüyle herkesin acısını üstlenir ve yaralarını iyileştirir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "İlahi büyüsünün gücüyle herkesin acısını üstlenir ve yaralarını iyileştirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Saat Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Clock Mage", "Saat Büyücüsü", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Zamanın kendisine hükmeden bir büyücü. Ölümü yaklaşınca geçmişe dönüp yeniden hayat bulur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Zamanın kendisine hükmeden bir büyücü. Ölümü yaklaşınca geçmişe dönüp yeniden hayat bulur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Yaratık Koleksiyoncusu", Language.Turkish);
            MagnificusMod.RegisterCard("Creature Collector", "Yaratık Koleksiyoncusu", "He had searched far and wide for his little companion, you see", "Bilirsin, küçük yoldaşını her yerde aramış.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Bilirsin, küçük yoldaşını her yerde aramış.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Bölme Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Division Mage", "Anlaşmazlık Büyücüsü", "So the card says at least... I assumed those freaks were long dealth with", "En azından kart öyle söylüyor... O ucubelerden çoktan kurtulunduğunu sanıyordum.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "En azından kart öyle söylüyor... O ucubelerden çoktan kurtulunduğunu sanıyordum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Yumurta", Language.Turkish);
            MagnificusMod.RegisterCard("Egg", "Yumurta", "Only the greatest of trainers might find this treasure", "Bu hazineyi yalnızca en büyük eğitmenler bulabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Bu hazineyi yalnızca en büyük eğitmenler bulabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druid", Language.Turkish);
            MagnificusMod.RegisterCard("Druid", "Druid", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Doğanın ilkel bir müridi; müttefiklerini iyileştirmek için çektiği manayla beslenir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Doğanın ilkel bir müridi; müttefiklerini iyileştirmek için çektiği manayla beslenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Efsuncu", Language.Turkish);
            MagnificusMod.RegisterCard("Enchanter", "Efsuncu", "He spews cosmic magicks upon his demise, enchanting everything nearby", "Ölürken kozmik büyü saçarak yakınındaki her şeyi büyüler.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "Ölürken kozmik büyü saçarak yakınındaki her şeyi büyüler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Her Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("EveryMage", "Her Büyücü", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("mage", "büyücü", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Evokasyon Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Evoker", "Evokasyon Büyücüsü", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "İğrenç öğretileri olan uğursuz bir budala. Çağırdığı yılanlar en ölümcül olanlardandır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "İğrenç öğretileri olan uğursuz bir budala. Çağırdığı yılanlar en ölümcül olanlardandır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Yılan Çağırma", Language.Turkish);
            MagnificusMod.RegisterCard("Serpent Summon", "Yılan Çağırma", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Ateş Bükücü", Language.Turkish);
            MagnificusMod.RegisterCard("Firebender", "Ateş Bükücü", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Savaşın kızıştığı anlarda neşesi yerindedir; ateş toplarının bir sonraki kurbanını hep arar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Savaşın kızıştığı anlarda neşesi yerindedir; ateş toplarının bir sonraki kurbanını hep arar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Öngörü Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Foresight Mage", "Öngörü Büyücüsü", "As he gazes upon your future, attacks that may come his way he forever predicts", "Geleceğine bakarken kendisine yöneltilebilecek saldırıları hep öngörür.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "Geleceğine bakarken kendisine yöneltilebilecek saldırıları hep öngörür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Öngörü Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Foresight Mage", "Öngörü Büyücüsü", "Gazing into the future, he may see any body who dares make an approach", "Geleceğe bakarak yaklaşmaya cesaret eden herkesi görebilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "Geleceğe bakarak yaklaşmaya cesaret eden herkesi görebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Buzul", Language.Turkish);
            MagnificusMod.RegisterCard("Glacier", "Buzul", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.Turkish);
            MagnificusMod.RegisterCard("Gashadokuro", "Gashadokuro", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Cevher Gözcü", Language.Turkish);
            MagnificusMod.RegisterCard("Gem Sentinel", "Cevher Gözcü", "the elite warrior unit enchanted with the aura of my moxen", "Güç taşlarımın aurasıyla büyülenmiş seçkin savaşçı birliği.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "Güç taşlarımın aurasıyla büyülenmiş seçkin savaşçı birliği.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Yüce Astrolog", Language.Turkish);
            MagnificusMod.RegisterCard("Grand Astrologer", "Yüce Astrolog", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Savaş alanı sonsuza dek onun oyun sahasıdır, mekân ise silahı. Her şey onun karşısında açıktadır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Savaş alanı sonsuza dek onun oyun sahasıdır, mekân ise silahı. Her şey onun karşısında açıktadır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Yerçekimi Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Gravity Mage", "Yerçekimi Büyücüsü", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Yer çekimi kuvvetlerinin ustası. Tüm güç taşları onun sarsılmaz iradesine boyun eğer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Yer çekimi kuvvetlerinin ustası. Tüm güç taşları onun sarsılmaz iradesine boyun eğer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Yanılsama Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Illusion Mage", "Yanılsama Büyücüsü", "Dawning his tricks and disguises, there is none scarier. At first glance", "Hileleri ve kılıklarıyla ondan korkuncu yoktur. İlk bakışta.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "Hileleri ve kılıklarıyla ondan korkuncu yoktur. İlk bakışta.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "İstila Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Infestation Mage", "İstila Büyücüsü", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Senin gibi tahtı ele geçirmek isteyen bir meydan okuyucu, biraz şekil değiştirme büyüsüne kapılabilir sanırım.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Senin gibi tahtı ele geçirmek isteyen bir meydan okuyucu, biraz şekil değiştirme büyüsüne kapılabilir sanırım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Hakaret Eden Ayna", Language.Turkish);
            MagnificusMod.RegisterCard("Insulting Mirror", "Hakaret Eden Ayna", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Büyülü Tehdit etrafta uçar, alaylar ve küstah sözler savurur. Öfkeni kendi gücüne dönüştürür.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Büyülü Tehdit etrafta uçar, alaylar ve küstah sözler savurur. Öfkeni kendi gücüne dönüştürür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Demir Bakire", Language.Turkish);
            MagnificusMod.RegisterCard("Iron Maiden", "Demir Bakire", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "En iyi paladinim en uzun saatler boyunca çalışır. Yüce duvarından tek bir ruh bile geçemez.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "En iyi paladinim en uzun saatler boyunca çalışır. Yüce duvarından tek bir ruh bile geçemez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Güç Taşı Boksörü", Language.Turkish);
            MagnificusMod.RegisterCard("Kickmoxer", "Güç Taşı Boksörü", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Hayatını savaş sanatına adamış; karşısına çıkan herkese uyum sağlayabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Hayatını savaş sanatına adamış; karşısına çıkan herkese uyum sağlayabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Toplu Mezar", Language.Turkish);
            MagnificusMod.RegisterCard("Mass Grave", "Toplu Mezar", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Usta Agairan", Language.Turkish);
            MagnificusMod.RegisterCard("Master Agairan", "Usta Agairan", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Kızıl Kimera. Simya öğretmeni en ölümcül zehirleri aşılar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Kızıl Kimera. Simya öğretmeni en ölümcül zehirleri aşılar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Usta Bluetwo", Language.Turkish);
            MagnificusMod.RegisterCard("Master Bluetwo", "Usta Bluetwo", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Safirin çelik şövalyesi. Ölümünden sonra bile psişik varlığı düşmanlarımıza hükmeder.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Safirin çelik şövalyesi. Ölümünden sonra bile psişik varlığı düşmanlarımıza hükmeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Usta Doublin", Language.Turkish);
            MagnificusMod.RegisterCard("Master Doublin", "Usta Doublin", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Kemiklerin Efendisi'nin mesihi. Dua öğretmeni öz çalmayı ustalıkla öğrenmiş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Kemiklerin Efendisi'nin mesihi. Dua öğretmeni öz çalmayı ustalıkla öğrenmiş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Mega Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("Megawizard", "Mega Büyücü", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Heybeti tehditkâr, aklı kıtlığı ürkütücüdür. Böyle ham bir güç sonsuza dek süremez.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Heybeti tehditkâr, aklı kıtlığı ürkütücüdür. Böyle ham bir güç sonsuza dek süremez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Meteorolog", Language.Turkish);
            MagnificusMod.RegisterCard("Meteorologist", "Meteorolog", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Evreni dikkatle gözlemler, uygun gördükleri kişilerin üzerine meteor fırtınaları yağdırırlar. Acımasızlar mı? Değiller mi? Yalnızca kendileri bilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Evreni dikkatle gözlemler, uygun gördükleri kişilerin üzerine meteor fırtınaları yağdırırlar. Acımasızlar mı? Değiller mi? Yalnızca kendileri bilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Mini Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("Miniwizard", "Mini Büyücü", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Minicik boyuyla lanetlenmiş bir büyücü. Ama merak etme, bir çözüm bulmuş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Minicik boyuyla lanetlenmiş bir büyücü. Ama merak etme, bir çözüm bulmuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Hayalet Hırsız", Language.Turkish);
            MagnificusMod.RegisterCard("Phantom Thief", "Hayalet Hırsız", "A billowing cloud of crime, darting in and out, and stealing his foes", "Bir görünüp bir kaybolarak düşmanlarını soyan kabarık bir suç bulutu.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Bir görünüp bir kaybolarak düşmanlarını soyan kabarık bir suç bulutu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Önsöz Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Preformence Mage", "Önsöz Büyücüsü", "Who knows to what ends his mystery rabbit has been through", "Gizemli tavşanının neler yaşadığını kim bilir?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Gizemli tavşanının neler yaşadığını kim bilir?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Kraliçenin Büyü Yoldaşı", Language.Turkish);
            MagnificusMod.RegisterCard("Queen's Familiar", "Kraliçenin Büyü Yoldaşı", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Güzel canavarlardan oluşan görkemli bir kimera. Ordularını içinde, yakınında tutar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Güzel canavarlardan oluşan görkemli bir kimera. Ordularını içinde, yakınında tutar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Artan Açlık", Language.Turkish);
            MagnificusMod.RegisterCard("RisingHunger", "Artan Açlık", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Büyü Yoldaşı Hamamböceği", Language.Turkish);
            MagnificusMod.RegisterCard("Roach Familiar", "Büyü Yoldaşı Hamamböceği", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Ruhani yollarla yaratılmış bir hamamböceği. İradesi ona dirilme yeteneği verir! Ama sonunda bu da başarısız olur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Ruhani yollarla yaratılmış bir hamamböceği. İradesi ona dirilme yeteneği verir! Ama sonunda bu da başarısız olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Gölge Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Shadow Wizard", "Gölge Büyücüsü", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Gözlerden uzak bir mafya üyesi. Düşmanlarına topluca saldırmaları için gölgeleri çağırır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Gözlerden uzak bir mafya üyesi. Düşmanlarına topluca saldırmaları için gölgeleri çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Şinobi", Language.Turkish);
            MagnificusMod.RegisterCard("Shinobi", "Şinobi", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Karanlığın savaşçıları, kimsenin görmediği ve sahip çıkmadığı yerlerden ansızın saldırır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Karanlığın savaşçıları, kimsenin görmediği ve sahip çıkmadığı yerlerden ansızın saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Duş Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Shower Mage", "Duş Büyücüsü", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Okulumdan dışlanan biri, hem de haklı olarak! Kokusu ancak büyüyle tarif edilebilir...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Okulumdan dışlanan biri, hem de haklı olarak! Kokusu ancak büyüyle tarif edilebilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Çamur Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Sludge Mage", "Çamur Büyücüsü", "An entity of unknown origins, powered off the ill spreading plague to all", "Kökeni bilinmeyen bir varlık; hastalıktan güç alır ve vebayı herkese yayar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Kökeni bilinmeyen bir varlık; hastalıktan güç alır ve vebayı herkese yayar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Sui Bilgesi", Language.Turkish);
            MagnificusMod.RegisterCard("Sui-Sage", "Sui Bilgesi", "The leader of a pack, soon to be packed away", "Bir sürünün lideri; yakında kendisi de paketlenecek.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "Bir sürünün lideri; yakında kendisi de paketlenecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Çağırıcı", Language.Turkish);
            MagnificusMod.RegisterCard("Summoner", "Çağırıcı", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Yaşam sanatında bir deli; yaşamı yoktan var eder. Hem de korkutucu bir sezgiyle.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Yaşam sanatında bir deli; yaşamı yoktan var eder. Hem de korkutucu bir sezgiyle.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Simetrik Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Simetrik Büyücü", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Herkesin iki yüzü vardır, bilirsin. Özellikle de beni kızdırdıklarında.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Herkesin iki yüzü vardır, bilirsin. Özellikle de beni kızdırdıklarında.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Işınlanma Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Teleportation Mage", "Işınlanma Büyücüsü", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Sonsuz geçitlerin habercisi; savaş alanında durmadan sıçrar ve gelen darbeleri etkisiz kılar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Sonsuz geçitlerin habercisi; savaş alanında durmadan sıçrar ve gelen darbeleri etkisiz kılar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Sel Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Torrent Mage", "Sel Büyücüsü", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Okyanusun bir çırağı; onu kullanarak karayı ve yukarıdaki araziyi sular altında bırakır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Okyanusun bir çırağı; onu kullanarak karayı ve yukarıdaki araziyi sular altında bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Ehlileşmemiş Ejderha", Language.Turkish);
            MagnificusMod.RegisterCard("Untamed Dragon", "Ehlileşmemiş Ejderha", "Legends whisper this beast, was once a companion to the mox master Goranj", "Efsanelere göre bu canavar bir zamanlar güç taşı ustası Turuncil'in yoldaşıydı.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "Efsanelere göre bu canavar bir zamanlar güç taşı ustası Turuncil'in yoldaşıydı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Kara Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("Warlock", "Kara Büyücü", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Kan büyüsünü araştıran kararmış bir büyücü. Kanamayı korkunç bir silaha dönüştürür.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Kan büyüsünü araştıran kararmış bir büyücü. Kanamayı korkunç bir silaha dönüştürür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Kötü Cadı", Language.Turkish);
            MagnificusMod.RegisterCard("Wicked Witch", "Kötü Cadı", "A flying jesting witch, laughing your sorrows and posioning your armies", "Üzüntülerine gülen ve ordularını zehirleyen uçan, şakacı bir cadı.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Üzüntülerine gülen ve ordularını zehirleyen uçan, şakacı bir cadı.", Language.Turkish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Asit Aurası", Language.Turkish);
            MagnificusMod.RegisterAbility("Acid Aura", "Asit Aurası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] her tur karşısındaki yaratığa 1 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Uyanış", Language.Turkish);
            MagnificusMod.RegisterAbility("Awakening", "Uyanış");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "[creature] oynandığında sahibi, daha üst bir biçime evrimleştirmek için dost bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Geri Tepme Vuruşu", Language.Turkish);
            MagnificusMod.RegisterAbility("Backfire Strike", "Geri Tepme Vuruşu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature], saldırdığı hedeflerin karşısında kendi tarafında duran yaratıklara hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Kan Bağımlısı", Language.Turkish);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Kan Bağımlısı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "[creature] hasar verdiğinde verdiği her hasar için 1 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Vahşi Parazit", Language.Turkish);
            MagnificusMod.RegisterAbility("Brute Parasite", "Vahşi Parazit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "[creature] oynandığında karşısındaki alanda bir Yumurta oluşturulur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Tufan", Language.Turkish);
            MagnificusMod.RegisterAbility("Deluge", "Tufan");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "[creature] oynandığında gücü 0 olan rakip yaratıklar suya dalar ve Suda Süzülen mührünü kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "Bölünme", Language.Turkish);
            MagnificusMod.RegisterAbility("Division", "Bölünme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "Saldırdıktan sonra [creature], her biri özgün niteliklerinin yarısına sahip 2 özdeş klona bölünür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Nöbetçi", Language.Turkish);
            MagnificusMod.RegisterAbility("Sentry", "Nöbetçi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Bir yaratık [creature] karşısındaki alana hareket ettiğinde 1 hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ah, bir Öngörü Büyücüsü'nün hızını asla küçümseme.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Şifa Aurası", Language.Turkish);
            MagnificusMod.RegisterAbility("Healing Aura", "Şifa Aurası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] yakındaki dost yaratıkları iyileştirir. İyileştirme gücü kendi gücüyle orantılıdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Kalp Hırsızı", Language.Turkish);
            MagnificusMod.RegisterAbility("Heart Stealer", "Kalp Hırsızı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "[creature] bir yaratığı öldürdüğünde öldürülen yaratık eline eklenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Alev Efsunu", Language.Turkish);
            MagnificusMod.RegisterAbility("Ignis Incant", "Alev Efsunu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "[creature] seçilen bir rakip yuvasına 2 hasar versin diye 1 kan öde.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Korkutma", Language.Turkish);
            MagnificusMod.RegisterAbility("Intimidate", "Korkutma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "[creature] oyun tahtasına yerleştirildiğinde karşısındaki yaratık kendi sağına kaçar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Yalnız", Language.Turkish);
            MagnificusMod.RegisterAbility("Lonesome", "Yalnız");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature], bitişiğindeki her boş alan için +1 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Büyü Patlaması", Language.Turkish);
            MagnificusMod.RegisterAbility("Magic Burst", "Büyü Patlaması");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "[creature] yok olduktan sonra yanındaki yaratıkların gücü 1 artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Psişik Darbe", Language.Turkish);
            MagnificusMod.RegisterAbility("Psystrike", "Psişik Darbe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "[creature] yok olduktan sonra karşısındaki yaratığı kendi iki yanındaki müttefike saldırmaya yönlendirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Yılan Ustası", Language.Turkish);
            MagnificusMod.RegisterAbility("Serpent Master", "Yılan Ustası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "Her turun başında [creature], sahibinin seçtiği bir alanda Yılan Çağırma kartı oluşturur. Yılan Çağırma'nın 1 gücü ve 1 canı vardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Gölge Darbesi", Language.Turkish);
            MagnificusMod.RegisterAbility("Shadow Strike", "Gölge Darbesi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature], hedefine komşu yaratıkların gölgelerini onu da vurmak için çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Gelgitsel Kilitleyiş", Language.Turkish);
            MagnificusMod.RegisterAbility("Tidal Lock", "Gelgitsel Kilitleyiş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "Sahibinin turu başında [creature], Sincap gibi küçük yaratıkları kendi yörüngesine çeker.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Sihirbazın Kalbi", Language.Turkish);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Sihirbazın Kalbi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "[creature] yok olduğunda kontrol ettiğin mevcut cevherlere karşılık gelen bir güç taşı kartı onun yerini alır.", Language.Turkish);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Kunduzun Savunması", Language.Turkish);
            MagnificusMod.RegisterCard("Beaver's Defense", "Kunduzun Savunması", "Curating defensive dams upon use, not bad for a dire situation.", "Kullanıldığında savunma barajları oluşturur. Zor bir durum için fena değil.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Kullanıldığında savunma barajları oluşturur. Zor bir durum için fena değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Bomba Bilgesi", Language.Turkish);
            MagnificusMod.RegisterCard("Bomb Sage", "Bomba Bilgesi", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Bu bilge saldırıya uğradığında patlamasıyla tanınır... Hem gerçek hem mecazi anlamda.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Bu bilge saldırıya uğradığında patlamasıyla tanınır... Hem gerçek hem mecazi anlamda.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Boks Şampiyonu", Language.Turkish);
            MagnificusMod.RegisterCard("Boxing Champ", "Boks Şampiyonu", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Asa kullanmayı reddeden bu şampiyon, işleri yumruklarıyla çözmeyi tercih eder.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Asa kullanmayı reddeden bu şampiyon, işleri yumruklarıyla çözmeyi tercih eder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontozor", Language.Turkish);
            MagnificusMod.RegisterCard("Brontosaurus", "Brontozor", "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Peynir Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Cheese Wizard", "Peynir Büyücüsü", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Eğitimli Şef Büyücüler olan Peynir Büyücüleri, amaçlarına ulaşmak için zekâlarını ve gizemli güçlerini kullanırlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Eğitimli Şef Büyücüler olan Peynir Büyücüleri, amaçlarına ulaşmak için zekâlarını ve gizemli güçlerini kullanırlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Peynirci", Language.Turkish);
            MagnificusMod.RegisterCard("Cheezling", "Peynirci", "With cheese like this, who needs friends?", "Böyle bir peynir varken kimin dosta ihtiyacı var?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "Böyle bir peynir varken kimin dosta ihtiyacı var?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Telepati", Language.Turkish);
            MagnificusMod.RegisterCard("Telepathy", "Telepati", "A pupil can gather all the resources they need through sheer will alone.", "Bir öğrenci, ihtiyaç duyduğu tüm kaynakları yalnızca irade gücüyle toplayabilir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Bir öğrenci, ihtiyaç duyduğu tüm kaynakları yalnızca irade gücüyle toplayabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Doğrudan İsabet", Language.Turkish);
            MagnificusMod.RegisterCard("Direct Hit", "Doğrudan İsabet", "Upon being casted, your opponent will instantly take three damage.", "Kullanıldığında rakibin anında üç hasar alır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "Kullanıldığında rakibin anında üç hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Gizemli Yumurta", Language.Turkish);
            MagnificusMod.RegisterCard("Mysterious Egg", "Gizemli Yumurta", "Who knows what could hatch from this egg...", "Bu yumurtadan ne çıkacağını kim bilir...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Bu yumurtadan ne çıkacağını kim bilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Yüzsüz", Language.Turkish);
            MagnificusMod.RegisterCard("Faceless", "Yüzsüz", "A hollow shell of a mage, desperately looking for something to call its own.", "Kendisine ait diyebileceği bir şeyleri çaresizce arayan boş bir büyücü kabuğu.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "Kendisine ait diyebileceği bir şeyleri çaresizce arayan boş bir büyücü kabuğu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Sahteci", Language.Turkish);
            MagnificusMod.RegisterCard("Faker", "Sahteci", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Yalan. Hile. İnkâr. Sahtekâr yara almadan kaçmak için her yola başvurur...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Yalan. Hile. İnkâr. Sahtekâr yara almadan kaçmak için her yola başvurur...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Figletar", Language.Turkish);
            MagnificusMod.RegisterCard("Figletar", "Figletar", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Kötü bir kralı korkunç bir sona sürükleyen bu sihirbaz, ringde dövüşmekten de anlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Kötü bir kralı korkunç bir sona sürükleyen bu sihirbaz, ringde dövüşmekten de anlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Yangın Başlatıcı", Language.Turkish);
            MagnificusMod.RegisterCard("Firestarter", "Yangın Başlatıcı", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Bu büyüyü kullanırken dikkatli ol; öğrenciler düello alanının biraz fazla ısınabildiğini söylüyor.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Bu büyüyü kullanırken dikkatli ol; öğrenciler düello alanının biraz fazla ısınabildiğini söylüyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Buzdolabı Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Fridge Mage", "Buzdolabı Büyücüsü", "Its cold atmosphere will chill foes, weakening their offensive power.", "Soğuk havası düşmanlarını üşüterek saldırı güçlerini zayıflatır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Soğuk havası düşmanlarını üşüterek saldırı güçlerini zayıflatır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Cevher Kankası", Language.Turkish);
            MagnificusMod.RegisterCard("Gembro", "Cevher Kankası", "The ability to tank any hit once, this pupil has high gusto.", "Bu öğrenci herhangi bir darbeye bir kez dayanabilir; cesareti de boldur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Bu öğrenci herhangi bir darbeye bir kez dayanabilir; cesareti de boldur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Cevher Kenesi", Language.Turkish);
            MagnificusMod.RegisterCard("Gem Tick", "Cevher Kenesi", "An elusive tick, which grants power to others via its mox body.", "Güç taşı gövdesiyle başkalarına güç veren ele avuca sığmaz bir kene.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Güç taşı gövdesiyle başkalarına güç veren ele avuca sığmaz bir kene.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Hayalet Dinozor", Language.Turkish);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Hayalet Dinozor", "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Üçüncü Göz", Language.Turkish);
            MagnificusMod.RegisterCard("Third Eye", "Üçüncü Göz", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Üçüncü gözün gücünü kullanan bu büyü, destende kalan kartlardan birini seçip eline eklemeni sağlar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Üçüncü gözün gücünü kullanan bu büyü, destende kalan kartlardan birini seçip eline eklemeni sağlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Beyzbol Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Baseball Mage", "Beyzbol Büyücüsü", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Bu büyücünün asası beyzbol sopası olarak da kullanılır. Şaşırtıcı derecede dayanıklıdır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Bu büyücünün asası beyzbol sopası olarak da kullanılır. Şaşırtıcı derecede dayanıklıdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Buz Golemi", Language.Turkish);
            MagnificusMod.RegisterCard("Ice Golem", "Buz Golemi", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Buzlu bir dağ zirvesinden gelen bu canavarın erimeyi hiç umursadığı görülmemiş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Buzlu bir dağ zirvesinden gelen bu canavarın erimeyi hiç umursadığı görülmemiş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Yağmacı Haydut", Language.Turkish);
            MagnificusMod.RegisterCard("Looting Bandit", "Yağmacı Haydut", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Usta Mavuncu'nun Valkürlerini uzaktan izleyen ve onlar gibi olmak için çalışan bir takipçi.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Usta Mavuncu'nun Valkürlerini uzaktan izleyen ve onlar gibi olmak için çalışan bir takipçi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Mana Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Mana Mage", "Mana Büyücüsü", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Güçlü darbeler indirmek için Manadan yayılan enerjiyi toplar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Güçlü darbeler indirmek için Manadan yayılan enerjiyi toplar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Düşünceli Çırak", Language.Turkish);
            MagnificusMod.RegisterCard("Pondering Pupil", "Düşünceli Çırak", "It draws from your gem pile using the powers of its mind alone.", "Yalnızca zihninin gücüyle cevher destenden kart çeker.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Yalnızca zihninin gücüyle cevher destenden kart çeker.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Ayna Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Mirror Mage", "Ayna Büyücüsü", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Ayna ayna, söyle bana, en iyi Kâtip kim bu dünyada?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Ayna ayna, söyle bana, en iyi Kâtip kim bu dünyada?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Köstebek Büyücü", Language.Turkish);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Köstebek Büyücü", "Always popping up to cause mischief whenever he can.", "Fırsat buldukça ortaya çıkıp yaramazlık yapar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "Fırsat buldukça ortaya çıkıp yaramazlık yapar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononikus", Language.Turkish);
            MagnificusMod.RegisterCard("Mononykus", "Mononikus", "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "PLÜTON", Language.Turkish);
            MagnificusMod.RegisterCard("PLUTO", "PLÜTON", "Hmph. So this is where that one went.", "Hıh. Demek buraya gitmiş.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Hıh. Demek buraya gitmiş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Koru", Language.Turkish);
            MagnificusMod.RegisterCard("Protect", "Koru", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Zor durumda mısın? Bu büyü kartlarından birini alacağı bir sonraki saldırıya karşı tamamen bağışık kılar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Zor durumda mısın? Bu büyü kartlarından birini alacağı bir sonraki saldırıya karşı tamamen bağışık kılar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodaktil", Language.Turkish);
            MagnificusMod.RegisterCard("Pterodactyl", "Pterodaktil", "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Çılgın Tavşan Bilge", Language.Turkish);
            MagnificusMod.RegisterCard("Rabbid Sage", "Çılgın Tavşan Bilge", "A raving magician with a field of electricity at his disposal.", "Emrinde elektrik alanı olan çılgın bir sihirbaz.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Emrinde elektrik alanı olan çılgın bir sihirbaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "İskelet Güç Taşı", Language.Turkish);
            MagnificusMod.RegisterCard("Skelemox", "İskelet Güç Taşı", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Yeşil Güç Taşı'nın kontrol ettiği zavallı bir iskelet. Neredeyse ona acıyacağım.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Yeşil Güç Taşı'nın kontrol ettiği zavallı bir iskelet. Neredeyse ona acıyacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Balçık Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Slime Wiz", "Balçık Büyücüsü", "It'll use the slime against the enemies, to drop their attack whence struck.", "Düşmanlarına karşı balçık kullanır; ona vurduklarında saldırılarını azaltır.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Düşmanlarına karşı balçık kullanır; ona vurduklarında saldırılarını azaltır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Kendini Beğenmiş Cadı", Language.Turkish);
            MagnificusMod.RegisterCard("Smug Witch", "Kendini Beğenmiş Cadı", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Tüm diyarın en kendini beğenmiş öğrencisi. Efsaneye göre Kibirli Atışı eşsizdir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Tüm diyarın en kendini beğenmiş öğrencisi. Efsaneye göre Kibirli Atışı eşsizdir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Çağırma Mızrağı", Language.Turkish);
            MagnificusMod.RegisterCard("Summon Spear", "Çağırma Mızrağı", "Roots up a spear from the ground, acting as a sturdy counter.", "Yerden bir mızrak çıkararak sağlam bir karşılık verir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Yerden bir mızrak çıkararak sağlam bir karşılık verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Diken Büyücüsü", Language.Turkish);
            MagnificusMod.RegisterCard("Spike Mage", "Diken Büyücüsü", "This mage learned from the best of my Pike Mage's Scarecrows.", "Bu büyücü, Mızrak Büyücümün Korkuluklarının en iyisinden öğrendi.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Bu büyücü, Mızrak Büyücümün Korkuluklarının en iyisinden öğrendi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "Tiranazor", Language.Turkish);
            MagnificusMod.RegisterCard("T-Rex", "Tiranazor", "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "DİNOZOR MODUNA BAYILIYORUM!!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Sanal Kral", Language.Turkish);
            MagnificusMod.RegisterCard("Virtual King", "Sanal Kral", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Sanal diyarların kendi kendini ilan etmiş hükümdarı, basit “kart oyunu kurallarına” uymaz.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Sanal diyarların kendi kendini ilan etmiş hükümdarı, basit “kart oyunu kurallarına” uymaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Aptal Çekirdek", Language.Turkish);
            MagnificusMod.RegisterCard("Moron Core", "Aptal Çekirdek", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Terk edilmiş bir fabrikadan gelen tuhaf bir çekirdek. “Aptal” sözcüğünden nefret eder.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Terk edilmiş bir fabrikadan gelen tuhaf bir çekirdek. “Aptal” sözcüğünden nefret eder.", Language.Turkish);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Smughtro'nun MagMod Genişletmesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Magnificus Moduna 19 sıradan kart, 7 nadir kart, 7 büyü ve 6 yardımcı kart ekler.", Language.Turkish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Ölüm Yardımı", Language.Turkish);
            MagnificusMod.RegisterAbility("Death Assist", "Ölüm Yardımı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Bu mührü taşıyan bir kart yok olduğunda rakibe 3 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Emmental Elementali", Language.Turkish);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Emmental Elementali");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Bu mührü taşıyan bir kart oynandığında bir Peynirci çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "İlk Vuruş", Language.Turkish);
            MagnificusMod.RegisterAbility("First Strike", "İlk Vuruş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Bu mührü taşıyan bir kart oynandığında karşı şeride hemen saldırır. Karşıda kart yoksa hasar verilmez.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Bilinmeyen Yumurtadan Çıkış", Language.Turkish);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Bilinmeyen Yumurtadan Çıkış");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "Sahibinin turu başında bu mührü taşıyan bir kart yumurtadan çıkarak rastgele bir dinozora dönüşür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Sağlıklı Ölüm", Language.Turkish);
            MagnificusMod.RegisterAbility("Healthy Death", "Sağlıklı Ölüm");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Bu mührü taşıyan bir kart yok olduğunda sağındaki ve solundaki kartlar 1 can iyileşir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Mana Karmaşası", Language.Turkish);
            MagnificusMod.RegisterAbility("Mana Mess", "Mana Karmaşası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Bu mührü taşıyan bir kart oynandığında Mana bedeli olan nadir olmayan rastgele bir kart çek.", Language.Turkish);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Flowey", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Büyük Cthulhu'yu perde arkasındaki entrikalarla dirilterek kıyameti getirmeye kararlı, fanatik bir lider.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Seni Aptal", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "Beni yenebileceğini sanıyorsan gerçekten aptalsın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Omega Flowey", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Gerçekten aptalsın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Sabır", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "sabırlı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Cesaret", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Cesur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Dürüstlük", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Dürüst.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Azim", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Azimli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Nezaket", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Nazik.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Adalet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Adalet.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "Merhaba! Şey, yani... Ölmeye hazır mısın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "Merhaba! Ben Flowey, Çiçek Flowey!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Burada neler olduğunu biliyorsun, değil mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "Sadece acı çektiğimi görmek istedin[c:0]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "Seni izlediğimi biliyor muydun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "Artık Inscryption'ın kontrolünü ele geçirdim!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "Ve Inscryption'ın ardında hangi sırların saklandığını biliyorum...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "Artık dünyayı ele geçirmeme hiçbir şey engel olamaz!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "Bu savaşın ne için olduğunu sanıyorsun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "Inscryption'ın dosyalarını karıştırmak için onu sadece paravan olarak kullandım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "Bir de bilgisayarını tabii ki!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "Belki fark etmişsindir, AMA artık internete bağlıyım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "O hâlde Inscryption'ı yüklemeye başlamanın zamanı geldi!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "Sen GERÇEKTEN bir aptalsın!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "ESKİ_VERİ'yi kullanırsam insan ruhlarının gücüne bile ihtiyacım yok!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]Bununla ne başardığını biliyor musun? Hiçbir şey.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]Benden kurtulamazsın! Ne yaparsan yap, hep burada olacağım!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]R-ruhlar mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]G-güçlerim nerede?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]NE YAPTIN SEN?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "Flowey'nin savunması [c:bR]0'a düştü!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]HAYIIIIIR!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "Az önce ne oldu...?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Hıh, görünüşe göre bu kez sen kazandın...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]KİMSE SANA YARDIM ETMEYECEK!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "ARTIK BAĞIRIP DURMA: [c:bR]YARDIM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]Beni bu kadar kolay öldürmene izin vereceğimi gerçekten mi sandın?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]Bu da ne...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Flowey beni öylece kullanabileceğini sandı...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]Benim ne olduğumu bile bilmiyordu!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Ama artık kontrol BENDE...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Canını sonsuz yapmaması ne acınası... Ben o hatayı yapmayacağım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]İstediğin kadar dene, beni öldüremezsin!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]Şimdi bunun ne yaptığını görelim...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]BUNU NEDEN GERİ ALAMIYORUM???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "TEKRAR TEKRAR ÖLÜŞÜNÜ İZLEMEK ÇOK [c:bR]EĞLENCELİ!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "TEK BİR HASAR BİLE YOK!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "SENİN GİBİ BİRİ [c:bR]BENİ YENEMEZ!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]Açlık bu savaşı kesintiye uğratmayacak!", Language.Turkish);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Kart Paketi: Undertale", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Aaron", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ah evet, cesur Aaron, güzel Aaron. Gözlerini kaslarından ayırabiliyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Alphys", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "Dr. Alphys, burada gördüğün daha “ürkütücü” bireylerden bazılarının yaratıcısı... Yoksa... ÇOKlu bireyler mi demeliyim?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Sevimli ama can sıkıcı. Bu yaratığın ikili doğasının eşi benzeri yok.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Asgore", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "Canavarların kralı... Kaba kuvveti gerçekten korkutucu, ama aynı zamanda... merhametli mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Asriel Dreemurr", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "Yeraltı'nın en güçlü varlığı... Umarım ondan yararlanabilirsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Astigmat", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "Sinir bozucu Astigmatizm... bir türlü karar veremiyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Gaster Patlatıcısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Buz Kütlesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Alışılmadık derecede büyük bir buz küpü... İçinde ne olduğunu kim bilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Chara", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Dogamy", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "Dogamy ve eşi Dogaressa, savaş alanında takım olmayı sever. Yeter ki ikisinden biri yok olmasın...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Dogaressa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Doggo", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ah, kör köpek... Her hareket sesine doğru atılır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Doodlebog", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Kukla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "Sıradan kukla... “deli” benzeri kadar karizmatik değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Birleşik Canavar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Endogeny", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "boş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Son Froggit", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ah evet, Froggitlerin en büyük patronu... Daha az gelişmiş akrabaları kadar kolay kandırılıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Frisk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Froggit", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ah, bundan daha utangaç olamaz... Froggit çatışmaya girmek istemiyor. Ne yazık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W.D. Gaster", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Glyde", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "Öyle narsist ki ancak önünde onu izleyecek bir kart varsa saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Büyük Köpek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Gerçekten asil ve yeterli; bir köpeğin erişebileceği en gelişmiş biçim.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Gyftrot", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Bu yaratığa nazik davran, zaten yeterince şey yaşadı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Buz Kurdu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ah evet, bu kaslı yaratık öldüğünde bir buz bloğu oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Icecap", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Jerry", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Artık onu boş ver.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "İyi Geceler Şövalyesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ah, uğursuz Knight Knight... uykunun nöbetçisi. Fetihlerinde acımasızdır...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Limonlu Ekmek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Küçük Köpek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "Olsa olsa sıradan bir köpek... En azından şu anki hâliyle.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Loox", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "Kurnaz Loox EyeWalker... Onunla uğraşmamak akıllıca olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Deli Kukla", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "Kukla mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "Görünüş aldatıcı olabilir...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Madjick", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Ne büyücü ama...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Hafıza Kafası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Mettaton", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Son derece zeki, sistematik ve karmaşık bir veri analizcisi... Bana eski bir “dostumu” hatırlatıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Mettaton EX", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Migosp", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "Huysuz Migosp... kalabalıkta saldırısı artar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Migospel", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Moldbygg", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Moldsmal", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "Bu bana sahtekâr hissi veriyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Moldessa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ah, jölemsi Moldsmal. Muhtemelen neyden yapıldığını hiç merak etmedin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Muffet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ah evet, örümceklerin kraliçesi. Hızlı oynayışı etkileyici.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Napstablook", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "Hayaletlerin en melankoliği... Savaşı umursamaz ama yine de etkilemek için savaşır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Onionsan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "Bununla pek stratejiye gerek yok... İkinci turda rastgele bir dokunaç kartına dönüşür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Papyrus kemikli bir kabadayıdır. Kemik üretmekte üstüne yoktur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Parsnik", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Pyrope", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Pyrope yalnızca sıcaklığı artırmak istiyor. Bakalım bu ne kadar ölümcül olabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Azrail Kuşu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Kraliyet Muhafızları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Kaderin ayırdığı iki âşık... Acaba önemli olana odaklanabilecekler mi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Bu kartı seçersen kötü zaman geçireceğimi hissediyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Shyren", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "Müziğe düşkün Shyren... Şarkısını duymak için çanlarını çal.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Snowdrake", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "Gülünç Snowdrake... Babasının yanıldığını kanıtlamaya çalışıyor. Başarmasına izin verecek misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "Çok Soğuk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "çok üzgünüm", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "o çok üzgün", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Temmie", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Ölümsüz kedi Temmie... En azından onun bir kedi olduğunu sanıyorum. Kaybedecek bir şeyi yok, kazanacağı çok şey var.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Toriel", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "Harabelerin bekçisi... Oyun tahtasının senin tarafını elinden geldiğince koruyacak.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Tsunderplane", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "Dikkatini mi istiyor, yoksa uzaklaşmanı mı, bir türlü karar veremiyor... İkincisini öneririm.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Undyne", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "Undyne'ı nasıl unutabilirim? Mızrağıyla olağanüstü isabet sağlayan gerçek bir savaşçı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Vegetoid", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Sebzelerini ye. (FDA tarafından denetlenmemiştir.)", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Vulkin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Çok coşkulu bir yaratık. Kimseye zarar vermek istemez ama bu onu durdurmaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Whimsalot", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "Soylu Whimsalot... Fetihlerini adil bulması için dua et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Whimsun", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "Önemsiz Whimsun... yalnızca bir kez saldırdıktan sonra savaştan kaçar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Woshua", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Bu yaratığın kan dökme arzusu yoktur. Başkalarına yardım etmek ister ama kışkırtılırsa savaşır.", Language.Turkish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Asosyal", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Bu mührü taşıyan bir kart, oyun tahtasının senin tarafında en az 1 başka kart varsa saldırı bonusu kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Temizleyici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "Bu mührü taşıyan bir kart, sahibinin savaş aşamasının başında, onun tarafındaki diğer tüm kartları 1 can iyileştirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Kararlılık", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Bu mührü taşıyan bir kart, sahibinin seçtiği herhangi bir boş yuvaya hareket edebilir. Birini öldürünce deneyim ve seviye de kazanır. Ama gerçekten istediğin bu mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Ateşleyici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Bu mührü taşıyan bir kart başka bir karta saldırdığında hedef Alevler İçinde mührünü kazanır. Yanan kart sahibinin savaş aşamasının başında 1 hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "Alevler İçinde", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Bu mührü taşıyan bir kart sahibinin savaş aşamasının başında 1 hasar alır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Kararsız", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Bu mührü taşıyan bir kart darbe aldığında 50/50 olasılıkla ya nitelik bonusu kazanır ya da yok olarak elinde bu kartın bir kopyasını oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Herkes Jerry'yi tanır. Turları 2 saniye uzatır. Jerry öldürüldüğünde veya kurban edildiğinde oyun tahtasının senin tarafındaki kartlar nitelik bonusu kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Merhamet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Kararlılık taşıyan bir kart, karşısındaki kartın canı azaldığında bu mührü kazanır ve oyuncuyu ahlaki bir karar vermeye yöneltir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "İçgörü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "Kötü zaman geçirmek ister misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Karalayıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Bu mührü taşıyan bir kart darbe aldığında bazen bitişik alanlara Doodleboglar çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Ürkek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Bir rakip kart bu mührü taşıyan kartın karşısındaki alana hareket ettiğinde mühür sahibi bir alan yana geçmeye çalışır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Jerry'yi geride bıraktın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Vay canına, bu işte BERBATSINIZ.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "Buradaki kablosuz ağ berbat.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "ŞŞŞT! DÜŞÜNÜYORUM, millet!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Kendininkini bul, velet.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "Bunu neden yapıyoruz? Ne başarısızlık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Millet, hava SOĞUK. UMURSAYAN var mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Ahh, of...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "TABİİ Kİ! Kim BİLMEZ ki?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Şey... SEN beni eve bırakabilir misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Çok utanç verici.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "Yani, şey, ne yapıyorsun sen?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "Ne? Beni bırakıp gittiler mi...? Ne BİÇİM arkadaşlar!", Language.Turkish);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Ölüm Dansı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Bu mührün etkisini tersine çevirmek için 2 Kemik öde. Sahibi turunu bitirdiğinde oyun tahtasındaki tüm yaratıklar 1 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Can Çekimi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Ana destenden bir kart çekmek için 1 Kan öde.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Ruh Kapısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "1 Enerji kazanmak için 1 Kemik öde. Sahibinin turu sonunda aynı miktarda azami enerji kaybet.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Çağırma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Mezarlıkta en uzun süredir bulunan, Narin mührü taşımayan dost yaratığı eline döndürmek için 3 Enerji öde.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "Uykuda", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Bu mührü 1 tur devre dışı bırakmak için [creature] gücüne eşit sayıda Kemik öde. [creature] normal şekilde saldıramaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Dönüştürme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "[creature] alternatif biçimine dönüştürmek için 2 Kemik öde.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Koruyucu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "[creature] yanındaki yaratıklar 1 azami can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Felaket Taşkını", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "Sahibinin turu sonunda oyun tahtasındaki tüm yaratıklar 1 can kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Teselli Aurası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "Sahibinin turu sonunda [creature] yanındaki yaratıklar 1 can iyileşir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Ceset Şöleni", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Sahibinin tarafındaki Narin olmayan bir yaratık savaşta yok olduğunda eline bir Zombi gelir. Bir Zombinin 1 Gücü ve 1 Canı vardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Ölüm Vuruşu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "[creature] savaşta yok olduğunda karşılık verir, ardından yok olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Ölüm Metali", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "[creature] oynandığında yanındaki yaratıklar ve karşısında solda, sağda ve ortada bulunan yaratıklar 1 hasar alır. Etkilenen her yaratık için 1 Güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Kirletici", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "[creature] yok olduğunda bir kart çek, ardından elinden atmak için bir kart seç.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "İstila", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "[creature] oyun tahtasında 2 tur geçirdikten sonra elinde kendisinin bir kopyasını oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "İskeletleştirme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "[creature] yok olduğunda eski mühürlerini taşıyan bir İskelet eline gelir. Bir İskeletin 1 Gücü, 1 Canı ve Narin mührü vardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Şeytan Çıkarma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "[creature] oynandığında oyuncu karşısındaki yaratığın Kemik bedeline eşit sayıda Kemik kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Patlayan Ceset", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "[creature] savaşta yok olduğunda oyun tahtasındaki tüm boş alanlar Bağırsaklar kartlarıyla dolar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Kin Toplayıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "Rakip yaratıklar sahibine doğrudan her 2 kez hasar verdiğinde [creature] 1 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Çan Gücü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "Bu mührün temsil ettiği değer, oyun tahtasındaki Çan kartlarının sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Kemik Kazıcı Gücü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "Bu mührün temsil ettiği değer, oyun tahtasındaki Kemik ve kazmayla ilgili mühürlerin sayısına eşittir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Ateşleme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "[creature] oyun tahtasındaki her turun ardından 1 can kaybederek 1 güç kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Kazıcı Mandalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "Sahibinin turu sonunda [creature] 1 Kemik üretir. Yok olduğunda sahibi, Kemik Kazıcı mührünü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Güçlendirilmiş Kemik Kazıcı Mandalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "Sahibinin turu sonunda [creature] 1 Kemik üretir. Yok olduğunda sahibi, bu mührü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Gençleşme", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "[creature] yok olduğunda sahibi, Tecrübesiz mührünü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Kafatası Fırtınası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "Sahibinin turu sonunda bu mühür rastgele başka bir mühürle değiştirilir. Kart yok olduğunda sahibi, bu mührü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Tutuşturma", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "[creature] yok olduğunda sahibi, Ateşleme mührünü kazanacak bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Uğursuz Kemik Nabzı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "[creature] oynandığında hemen yok olur ve sahibinin tarafındaki yaratık sayısının iki katı kadar Kemik bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Anaç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "[creature] yanındaki yaratıklar Suda Süzülen mührünü kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Nekroz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "[creature] oyun tahtasındaki her turun ardından 1 güç ve 1 azami can kaybeder.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Araf", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "[creature] yok olduğunda destenin en üstüne döner.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Amansız Hayalet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Sahibinin turu başında [creature] yanındaki yaratıklar Hayalete dönüşür. Bir Hayaletin 3 Gücü, 1 Canı ve Narin mührü vardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Hayaletlerin Dönüşü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Saldırdıktan sonra [creature] yok olur; ardından eski mühürlerini taşıyan 2 Hayaleti yan destene karıştır. Bir Hayaletin 3 Gücü, 1 Canı ve Narin mührü vardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Kötü Alamet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "Sahibinin turu sonunda [creature] sahibine 1 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Kin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "[creature] yok olduğunda bulunduğu alanda kalıcı 1 güç bonusu bırakır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Huzur Veren Çayırlar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "Sahibinin turu sonunda oyun tahtasındaki tüm yaratıklar 1 can kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Son Vuruş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Sahibinin tarafındaki Narin olmayan bir yaratık savaşta yok olduğunda sahibi, tüm mühürlerini kaybedecek bir yaratık seçer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Bölünen Ceset", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "[creature] savaşta yok olduğunda bitişik her boş alanda bir Dismorfi oluşturur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Uyuşuk", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] normal şekilde saldıramaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Kasvetli Kitabe", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "[creature] oynandığında dinlenmeye bırakılmış bir kart seçip eline geri alabilirsin.", Language.Turkish);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Kocaayak", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Ormanlarda gizlenen gizemli bir yaratık. Onu gördüğünü söyleyen çok az kişi var.", Language.Turkish);
            GrimoraMod.RegisterCard("Bigfoot", "Kocaayak");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Goblin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Sadık ve vahşi bir canavar; orduna güzel bir katkı.", Language.Turkish);
            GrimoraMod.RegisterCard("Goblin", "Goblin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Vila", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "İlk görüşte aşk. En azından öyle düşünmeni istiyor.", Language.Turkish);
            GrimoraMod.RegisterCard("Vila", "Vila");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Yara-ma-yha-who", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Bu, yemeklerini bir türlü bitiremiyor gibi...", Language.Turkish);
            GrimoraMod.RegisterCard("Yaramayawho", "Yara-ma-yha-who");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Deney Uzuvları", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Bu parçalar bir zamanlar birine, şimdi ise bir şeye ait... (Test)", Language.Turkish);
            GrimoraMod.RegisterCard("Test Limbs", "Deney Uzuvları");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Allip", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "Delilerin kalıntıları! O yüzün ardında nasıl bir hikâye olduğunu asla bilemezsin ama tutkuyla dolu olduğu kesin.", Language.Turkish);
            GrimoraMod.RegisterCard("Allip", "Allip");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Amami Tavşanı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Yavrularını güvende tutmak için deliklere saklarlar.", Language.Turkish);
            GrimoraMod.RegisterCard("Amami Rabbit", "Amami Tavşanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Ankhame", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Kanına çekilen bir yadigâr. Belki de onu bir savurmalısın!", Language.Turkish);
            GrimoraMod.RegisterCard("Ankhame", "Ankhame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Anneta", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "Mürekkep akıp duruyor. Acaba o hâlâ orada mı? Ölümün tek vaadi yeniden uyanacak olman.", Language.Turkish);
            GrimoraMod.RegisterCard("Anneta", "Anneta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Anoreksiya", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Seni kendinden nefretle boğar; bir sonraki sefer hangi biçimi alacağını asla bilemezsin.", Language.Turkish);
            GrimoraMod.RegisterCard("Anorexia", "Anoreksiya");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Lich Çanı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "Görünüşe göre çanları kullanmanın yeni bir yolunu bulmuşlar.", Language.Turkish);
            GrimoraMod.RegisterCard("Lych Bell", "Lich Çanı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "Şişkin Ceset", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Patlamaya hazır, iğrenç çıbanlar.", Language.Turkish);
            GrimoraMod.RegisterCard("TheBloated", "Şişkin Ceset");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Kavanoz Beyin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "O kavanozda nasıl insanlık dışı düşünceler olduğunu hayal etmek bile ürkütüyor...", Language.Turkish);
            GrimoraMod.RegisterCard("BrainJar", "Kavanoz Beyin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Yanıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Ah, böylesine heyecan verici yüksek bir konumdan ne düşüş! Şimdi yalnızca metal bir gövde ve o tetikte maddenin son kalıntıları var...", Language.Turkish);
            GrimoraMod.RegisterCard("Combustor", "Yanıcı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Yanlış Oynanmış Gelincik", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Sözde kusursuz stratejileri onu fena hâlde yüzüstü bırakmış çürüyen bir Gelincik.", Language.Turkish);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Yanlış Oynanmış Gelincik");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Dismorfi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Sol Dismorfi.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Sağ Dismorfi.", Language.Turkish);
            GrimoraMod.RegisterCard("Dysmorphia", "Dismorfi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Şeytan Çıkarıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Lanetlileri sürmenin hâlâ ona yarayacağını düşünüyor. Acaba nerede olduğunu biliyor mu?", Language.Turkish);
            GrimoraMod.RegisterCard("Exorcist", "Şeytan Çıkarıcı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "İrinli Kemikler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Web kamerasıyla oynayana kadar bekle.", Language.Turkish);
            GrimoraMod.RegisterCard("Flembones", "İrinli Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Stein ve Frank", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Cehennem bile onları ayıracak kadar sıcak değildi.", Language.Turkish);
            GrimoraMod.RegisterCard("Stein & Frank", "Stein ve Frank");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Gök Gürültüsü Kafatası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "Dikkatle dinlersen alevlerin kemikler üzerindeki çıtırtısını... ve onların sesini hâlâ duyabilirsin.", Language.Turkish);
            GrimoraMod.RegisterCard("FulmineSkull", "Gök Gürültüsü Kafatası");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Gök Gürültüsü Kemikleri", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Elektrikli sandalyeden hiçbir zaman gerçekten ayrılmadı.", Language.Turkish);
            GrimoraMod.RegisterCard("FulurOssa", "Gök Gürültüsü Kemikleri");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Prometheus'un Alevi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Bu oldukça eşsiz: insanlığa fayda sağlayan bir hırsızın geride kalan ganimeti! Biraz karaciğer ister misin?", Language.Turkish);
            GrimoraMod.RegisterCard("PrometheusFlame", "Prometheus'un Alevi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Bağırsaklar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Sinir bozucu bağırsaklar.", Language.Turkish);
            GrimoraMod.RegisterCard("Guts", "Bağırsaklar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Haberci", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Hizmeti için ağır bir bedel isteyen güçlü bir iblis.", Language.Turkish);
            GrimoraMod.RegisterCard("Harbinger", "Haberci");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Hastur", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Yıldızların ötesinden geldi, krallara ve aptallara yansımasının parçalarını armağan etti. Bu parçayı kabul edecek misin?", Language.Turkish);
            GrimoraMod.RegisterCard("Hastur", "Hastur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Sıradan İblis", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "Muzip gülümsemesi ve oyuncu doğasıyla gittiği her yerde kargaşa çıkaran minicik bir yaratık!", Language.Turkish);
            GrimoraMod.RegisterCard("Common Imp", "Sıradan İblis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Orochi Ruhu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Ah... Onun burada olmaması gerekirdi...", Language.Turkish);
            GrimoraMod.RegisterCard("Orochimitama", "Orochi Ruhu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Inochi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Yaratıklarını iyileştiren huzur verici bir varlık; fırtına öncesi sessizlik.", Language.Turkish);
            GrimoraMod.RegisterCard("Inochi", "Inochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Azap Yolu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Ele Geçirilmiş Uzuvlar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Bir zamanlar yaşayan bir insana bağlıydılar; şimdi tamamen başka bir şeye aitler.", Language.Turkish);
            GrimoraMod.RegisterCard("Possessed Limbs", "Ele Geçirilmiş Uzuvlar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Mezarcı Köstebek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "Yılmaz Köstebek... Mezarcı mı? Her neyse...", Language.Turkish);
            GrimoraMod.RegisterCard("Mole Digger", "Mezarcı Köstebek");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Nekros", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Nekros oyun tahtasına hükmediyor, meydan okuyucu. Ölüm onun oyun alanı.", Language.Turkish);
            GrimoraMod.RegisterCard("Nekros", "Nekros");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Nekros Prime", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "Daha büyük bir güç bulamazsın... kendi adının... bir mezara kazındığını düşünmekten başka.", Language.Turkish);
            GrimoraMod.RegisterCard("NekrosPrime", "Nekros Prime");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Nuckelavee", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "Denizinin yöneticisi. Nefesinin kölelerini kirletmemesini umsan iyi olur!", Language.Turkish);
            GrimoraMod.RegisterCard("Nuckelavee", "Nuckelavee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "İğrenç Kütle", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Ne çirkin bir görüntü.", Language.Turkish);
            GrimoraMod.RegisterCard("OdiousMass", "İğrenç Kütle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Orochi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Fedakârlıklar yapılmalı.", Language.Turkish);
            GrimoraMod.RegisterCard("Orochi", "Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Usta Ouro", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "Sonsuz azap ve acının içinden bir şekilde bu zavallı, kırılmış şeyin içine bakmanın... ve acısını dindirmenin yolunu öğrendiler.", Language.Turkish);
            GrimoraMod.RegisterCard("Master Ouro", "Usta Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Sonsuz yaşam ve ölüm döngüsü bu terk edilmiş kalıntıları yıpratmış. Acı gerçekti, ama ölüm asla son değildir!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "Gan Ceann", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "Sayısız efsane dullahanı anlatır, ama hiçbiri öfkesinin gerçek boyutunu yansıtamaz.", Language.Turkish);
            GrimoraMod.RegisterCard("GanCeann", "Gan Ceann");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Karanlık Prens", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "Tüylü ufaklıkların gücü içinde parlıyor.", Language.Turkish);
            GrimoraMod.RegisterCard("Dark Prince", "Karanlık Prens");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Ölü Doğan Kuzgun", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "Yeniden genç olmak ne güzel!", Language.Turkish);
            GrimoraMod.RegisterCard("Stillborn Raven", "Ölü Doğan Kuzgun");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Diriltilmiş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "ÖLÜMÜN TIRPANIYLA GELEN HAYALET... DUR, NE?", Language.Turkish);
            GrimoraMod.RegisterCard("Reanimated", "Diriltilmiş");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "RevenantEldritch", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "Felaketin kaynağı, amansız ve şaşmaz.", Language.Turkish);
            GrimoraMod.RegisterCard("RevenantEldritch", "RevenantEldritch");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Tembel Kemikler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Şaka yapmayı bilen tembel bir iskelet. Ona bayılıyorum.", Language.Turkish);
            GrimoraMod.RegisterCard("Lazy Bones", "Tembel Kemikler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "İskeletfon", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Ölülerle iletişim kurmanın bir yolu, ama bir bedeli var.", Language.Turkish);
            GrimoraMod.RegisterCard("Skelephone", "İskeletfon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Ruh Kapısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Ruhlar âlemine girme fırsatı, ne güzel! Umarım bedelini ödeyebilirsin.", Language.Turkish);
            GrimoraMod.RegisterCard("Soulgate", "Ruh Kapısı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Maça Savaşçısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Bu korkunç savaşçı seni her anlamda yerin dibine sokacak.", Language.Turkish);
            GrimoraMod.RegisterCard("SpadeWarrior", "Maça Savaşçısı");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Ölümsüz Köylü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "Sonsuz karanlıkta kaybolan bu zavallı ruh çaresizce bir çıkış arıyor. Belki yolunu aydınlatabilirsin?", Language.Turkish);
            GrimoraMod.RegisterCard("UndeadCivilian", "Ölümsüz Köylü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Ölümsüz Köyü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Terk edilmiş ve kimsesiz bu köy, harap evlerini dolduracak yeni sakinler arıyor.", Language.Turkish);
            GrimoraMod.RegisterCard("UndeadVillage", "Ölümsüz Köyü");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "Her kasabada, her şehirde birileri ölüleri gömmek zorundadır. Zamanla onlar da gömülecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Dr. Kemik", Language.Turkish);
            GrimoraMod.RegisterCard("Dr.Bones", "Dr. Kemik");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "Seni öldürmeyen şey yalnızca daha aklı başında yapar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Wendigo", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Uzak yabandan dönmüş, bana bir arkadaşımı hatırlatıyor.", Language.Turkish);
            GrimoraMod.RegisterCard("Wendigo", "Wendigo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Bay Kazanç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Kazanan bir kart. Her zaman kazanır. Bu yüzden adı Bay Zafer.", Language.Turkish);
            GrimoraMod.RegisterCard("Mister Win", "Bay Kazanç");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Korkarım o değil.", Language.Turkish);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Sen... seni katil canavar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "Ah, eyvah... Felaketin akışı peşinden gelecek.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Bir zamanlar yaşadığın köyü kurban et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Sonsuza dek kazan küreği ara.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Elinde bir kıvılcım olan kayıp kişiyi bana getir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Kadim bir varlığın çağrısına kapılarak,", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "yasak bir ayin başlatıldı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "Acı, kadim büyük ölüm yılanına ulaşır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Fedakârlıklar yapılmalı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Ah... Henüz ölü kart yok.", Language.Turkish);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Revenant Modu Kart Paketi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Bu kart paketi, çoğunlukla çeşitli yollarla oyuncuya dönen kartlardan oluşur.", Language.Turkish);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Pipis", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Pipis.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "Yardım", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "Sahibinin turu sonunda [creature] kendini kurban ederek yanındaki kartları 1 can iyileştirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "İçinden Geçiş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "[creature], saldırısı kendi canından yüksek bir kartın saldırısına uğramak üzereyken yok olur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "İstenmeyen Arama", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "[creature] sahibinin turu sonunda, onun tamamladığı devrenin içindeki boş alanlarda İstenmeyen Posta oluşur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "NEO Saldırısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature], rakibin yaratık bulunan her alanına ve ayrıca rakip tarafın içinde yaratık bulunan her yarısındaki iki alana da saldırır. Rakip yaratık yoksa ortadaki iki alana saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Yardım Çağrısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "Sahibinin turu sonunda [creature] yardım çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "İleri Atıl", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "[creature] saldırmadan önce gücü en az 1 olarak ayarlanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Uçan Kafa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "En önemli kısım.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "İstenmeyen Posta Arabası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "İstenmeyen postayla dolu. Her tür saldırıyı emer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "İstenmeyen Posta", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Her tür unutulmaz fırsatı barındırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Büyük Nişancı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Büyük atışlar yapar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Zincirdeki Kalp", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Güzel.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Spamjeli", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "F1 tuşuna basmanın sonucu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "El Telefonu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "Gerçekten başka birine ihtiyacın var mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "NEO'NUN GÜCÜ!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "Büyük bir isim olmak istemez misin?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Alıcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "Ses eninde sonunda tükenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Grizzlipis", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Grizzlipis.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Ayı Arabası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Ayılarla dolu. Her tür saldırıyı emer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Ayı Postası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Ayılara gönderilen posta.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Zincirdeki Ayı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Ayı Pençesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Sincap Bombası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Sincaplar öldürüldüklerinde patlayarak yanlarındaki kartlara 10 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Dans Partisi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Kartların her tur hareket eder. Hareket edemeyen kartlar ölür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "bir kez daha", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Tüm rakip kartlar iki kez saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Aç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Dua et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Dikenli Köpekbalığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Her savaş Muhafız mührü taşıyan bir Yem Kovası ile başlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Sinir Bozucu Totemler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Her savaşa en çok kullandığın kabile için bir Sinir Bozucu totemiyle başla.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Acılı Kart Çekişi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Ana desteden kart çekmek 1 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Acılı Sincaplar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Yan desteden kart çekmek 1 hasar verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Rünler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Baskın kabileye ait rakip kartlar rastgele mühürler kazanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Dişçilik", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "Eşya olayları ve Ziynet Sahibi kartlar yalnızca Pense verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "Arşivlenmiş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "Her kart seçimi olayında rastgele bir kart seçeneği gizlenir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Temel", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "Tüm kartlarının saldırısı 1 azalır. Yan deste kartları Lider mührünü taşır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Son Patron v2", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Son patron Leshy'nin yerine gerçek bir BÜYÜK İSİM getirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "Dans etmelisin! Dans etmeyi bırakma!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Partimde dans etmeyi bırakan sonuçlarına katlanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "Bu mekanik sinir bozucu mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Harika. Amacı da bu zaten.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "Dans et kuklam! Daaans et.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "Geçmen gerek, hatırlıyor musun?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "KROMERLERİNİ [_spamton_0,ÇALIYORUM]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "KUTSAL [_spamton_0,CUNGADERO], KENDİMİ NE KADAR İYİ HİSSEDİYORUM", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "İŞTE BURADAYIM!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "KOCA", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>BÜYÜK!!!</size>", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,HER ZAMANKİNDEN BÜYÜK VE İYİ]</size>", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "VE ARTIK BU [_spamton_0,KART OYUNUNDA] OLDUĞUMA GÖRE", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "BENİ YENEMEZSİN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "[_spamton_0,NEO'NUN GÜCÜ] TARAFINDAN [_spamton_0,TAMAMEN YOK EDİLMEYE] HAZIRLAN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "YİNE [_spamton_0,BU] MU???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "[_spamton_0,YOK EDİLMEYE] HAZIRLAN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "HİÇ ŞANSIN YOK, SENİ [_spamton_0,KÜÇÜK YUVARLAK SOLUCAN]!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "[_spamton_0,SURATINA] [_spamton_0,YUMRUK YEMEYE] HAZIRLAN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "[_spamton_0,BANA] BAK!!! [_spamton_0,KENDİNE] BAK!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,KÖPRÜ ENGELLENDİ]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "BU BEDEN TAM BİR [_spamton_0,CENNET] DEĞİL Mİ?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2X [_spamton_0,ATEŞ] GÜCÜ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3X [_spamton_0,SU] GÜCÜ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "VE EN ÖNEMLİSİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "UÇAN KAFALAR!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "O [_spamton_0,AHMAKLARI] VE [_spamton_0,HERİFLERİ] DÖNÜŞTÜRECEĞİZ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "[_spamton_0,GÜLLÜ MEZARLARA]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "O [_spamton_0,KATOT EKRANLARINI]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "[_spamton_0,KATOT ÇIĞLIKLARINA]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "GÜZEL [_spamton_0,KALBİMİN] BİR [_spamton_0,PARÇASI] OLMAK İSTEMİYOR MUSUN?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "YOKSA... KÜÇÜK BİR [_spamton_0,ÖZL TUR] MU İSTİYORDUN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,NE]?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "[_spamton_0,KALBİMİ] Mİ [_spamton_0,ÇALDIN]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "[_spamton_0,KALBİMİ] [_spamton_0,ÇALAMAZSIN], O BENİM [_spamton_0,KALBİM]!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "KALBİMİ [_spamton_0,ÇALMAYI] BIRAK, SENİ [_spamton_0,!@#$]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "A H [_spamton_0,KÖPRÜ ENGELLENDİ]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "[_spamton_0,$4.99] DEĞERİNDEKİ KALBİMİ [_spamton_0,KIRDIN]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "BUNU [_spamton_0,YAPTIĞINDA] CANIMIN [_spamton_0,ACIDIĞINI] BİLİYOR MUSUN?!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "ESKİ DOSTUN SPAMTON'A YARDIM ETMEK İSTEMİYOR MUSUN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "DÜŞÜN! [_spamton_0,YUMURTALARIM] NE YAPACAK!?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "ÇAĞIRIYOR...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "[_spamton_0,KALBİM]...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "[_spamton_0,ELLERİM]...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "[_spamton_0,NEO'NUN GÜCÜNE] BAK VE KENDİNE SOR...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "İSTEMİYOR MUSUN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "[_spamton_0,BÜYÜK BİR İSİM] OLMAK İSTEMİYOR MUSUN!?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "SAYGIDEĞER MÜŞTERİM, CANIMI TÜKETMEYE ÇALIŞTIĞINI GÖRÜYORUM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "SENDE BİRAZ [_spamton_0,CESARET] OLDUĞUNU KABUL EDİYORUM!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "AMA [_spamton_0,1'E 1] BİR SAVAŞTA NEO ASLA YENİLMEZ!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "BİRAZ [_spamton_0,MAVİ IŞIK ÖZL FIRSATI] ZAMANI", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "[_spamton_0,ACINASI KÜÇÜK] [_spamton_0,KARTLARINLA] BENİ [_spamton_0,YOK EDEMEDİĞİNE] [_spamton_0,ŞAŞIRDIN] MI?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "[_spamton_0,NEO'NUN] YÜKSEK SAVUNMASIYLA ÜNLÜ OLDUĞUNU BİLMİYOR MUYDUN!?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "ŞİMDİ... HAVAİ FİŞ3KLERİN KEYFİNİ ÇIKAR 0HÂLDE!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "HAVAİ FİŞEKLERİN TADINI ÇIKAR!!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "NE?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "[_spamton_0,KİMİ] [_spamton_0,ARAMAYA] ÇALIŞIYORSUN???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "BU [_spamton_0,DÜNYADA] HİÇ [_spamton_0,ARKADAŞIN] YOK!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "HEPSİ [_spamton_0,KÂĞIT KARTLARDAN] İBARET!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "KİMİ ARAYACAKSIN, [_spamton_0,POLİSİ] Mİ?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "ÇOK [_spamton_0,ACINASISIN]!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "[_spamton_0,ÇÖP KONTEYNERİNİN DİBİNDE] [_spamton_0,YARDIM] DİYE [_spamton_0,BAĞIRIYORSUN]!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "SANA [_spamton_0,YARDIM] YOK!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "[_spamton_0,SESİN] ENİNDE SONUNDA TÜKENECEK!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "VAZGEÇ!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T WIN!!!", "KAZANAMAZSIN!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "BEN DURDURULAMAM!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "HAYATININ [_spamton_0,ÜCRETSİZ DENEME SÜRESİ] YAKINDA [_spamton_0,DOLACAK]!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "[_spamton_0,GOOBERT]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT THAT [_spamton_0,PATHETIC] LITTLE [_spamton_0,JAR] OF [_spamton_0,GOO]?", "ŞU [_spamton_0,ACINASI] [_spamton_0,BALÇIK] [_spamton_0,KAVANOZU] MU?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT [_spamton_0,HELP] WILL IT [_spamton_0,PROVIDE] TO [_spamton_0,YOU]???", "[_spamton_0,SANA] NE [_spamton_0,YARDIM] [_spamton_0,SAĞLAYACAK]???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,MAGNIFICUS]??", "[_spamton_0,MAGNIFICUS]??", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "[_spamton_0,MAGNIFICUS] NEDİR? BİR TÜR [_spamton_0,BALON BALIĞI] MI?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT'S A [_spamton_0,BLOWFISH] GONNA [_spamton_0,DO TO ME]??", "BİR [_spamton_0,BALON BALIĞI] [_spamton_0,BANA NE YAPABİLİR]??", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "[_spamton_0,LESHY]???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "[_spamton_0,DÖVÜŞÜMÜZÜN] BAŞINDA [_spamton_0,VURDUĞUM] [_spamton_0,ADAM] MI???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "HA! ONUN [_spamton_0,SAĞ SALİM] OLDUĞUNDAN BİLE EMİN DEĞİLİM!!!", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "[_spamton_1,ROYAL]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "ROYAL [_spamton_0,NE]? ROYAL [_spamton_0,KİM]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO/WHAT/WHEN/WHY/HOW] IS [_spamton_0,ROYAL]?", "[_spamton_0,KİM/NE/NE ZAMAN/NEDEN/NASIL] BU [_spamton_0,ROYAL]?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE SO PATHETIC", "ÇOK ACINASISIN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MUMBLING NONSENSE WORDS THROUGH A [_spamton_0,PLAYING CARD]", "BİR [_spamton_0,OYUN KARTININ] ARDINDAN ANLAMSIZ SÖZLER MIRDANAN", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU THINK YOU CAN [_spamton_0,AVOID] YOUR [_spamton_0,UNAVOIDABLE, QUICKLY APPROACHING] DEMISE?", "[_spamton_0,KAÇINILMAZ VE HIZLA YAKLAŞAN] SONUNDAN [_spamton_0,KAÇABİLECEĞİNİ] Mİ SANIYORSUN?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THERE]", "[_spamton_0,İŞTE ORADA]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU GONNA DO WITHOUT YOUR [_spamton_0,COMMUNICATION DEVICE]???", "[_spamton_0,İLETİŞİM CİHAZIN] OLMADAN NE YAPACAKSIN???", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT IS IT JUST [_spamton_0,ME]", "DUR, YOKSA SADECE [_spamton_0,BEN] Mİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "YOKSA BİR [_spamton_0,GEMİ] [_spamton_0,BİZE] DOĞRU GELİYOR GİBİ Mİ??", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY [_spamton_0,NOTHING] [_spamton_0,AT HALF PRICE]", "HERHÂLDE [_spamton_0,YARI FİYATINA] BİR [_spamton_0,HİÇTİR]", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY JUST A SOUND IN MY [_spamton_0,HEAD], IN MY [_spamton_0,EARS]", "HERHÂLDE [_spamton_0,KAFAMDAKİ], [_spamton_0,KULAKLARIMDAKİ] BİR SESTİR", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "BİR [_spamton_0,GEMİ] BU KÜÇÜK [_spamton_0,SATILIK KULÜBEYE] SIĞAMAZ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WILL NEVER DEFEAT-", "BENİ ASLA YENEME-", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY [_spamton_0,GOODBYE] [_spamton_0,TO YOUR FRIENDS AND FAMILY]", "[_spamton_0,ARKADAŞLARINA VE AİLENE] [_spamton_0,ELVEDA] DE", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE [_spamton_0,POWER OF NEO] WAS TOO MUCH FOR YOU", "[_spamton_0,NEO'NUN GÜCÜ] SANA FAZLA GELDİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONFIDENTIAL", "GİZLİ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEFEATED BY A WEAKLING HUMAN...", "ZAYIF BİR İNSANA YENİLDİM...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOOOOOOOOOOOOOOO!!!!!!", "HAYIIIIIIIIIR!!!!!!", Language.Turkish);


        }
    }
