    public class StarCraftCardpackMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for StarCraft_Cardpack Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack: StarCraft", "Kart Paketi: StarCraft", Language.Turkish);
