    public class LegendsFromTheDarknessMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LegendsFromTheDarkness Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness", "Karanlıktan Efsaneler", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of animals, myths and urban legends.", "Hayvanlar, mitler ve şehir efsanelerinden rastgele bir seçki içeren yaklaşık [count] kartlık bir koleksiyon.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Shark", "Mako Köpekbalığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Mako, an agile sea predator.", "Hızlı mako köpekbalığı, çevik bir deniz avcısı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robust Puma, a fierce creature.", "Güçlü Puma, vahşi bir yaratık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hideous offspring of a voracious creature.", "Açgözlü bir yaratığın korkunç yavrusu.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "Ahuizotl", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar creature. I wonder if that tail is special.", "Tuhaf bir yaratık. Acaba kuyruğunda özel bir şey var mı?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl Tail", "Ahuizotl Kuyruğu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in dismal waters, the ferocious alligator approaches those who dare get close.", "Kasvetli sularda gizlenen vahşi aligatör, yaklaşmaya cesaret edenlere doğru gelir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler Fish", "Fener Balığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let that glamorous shine decieve you.", "O büyüleyici ışıltının seni aldatmasına izin verme.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion", "Karınca Aslanı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automaton", "Otomaton", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rusted machine's exposed wires shock any would-be aggressor", "Paslı makinenin açıkta kalan kabloları saldırmaya yeltenenleri elektrikle çarpar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the regenerative sea predator, what would happen if the eternal juvenile were to reach maturity?", "Yenilenebilen deniz avcısı. Sonsuz yavru olgunlaşırsa ne olur?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beetle", "Böcek", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unsurpassable strength of the beetle knocks creatures away.", "Böceğin eşsiz gücü diğer yaratıkları savurur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloater", "Şişkin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unfortunate demise to this particular being.", "Bu varlık için talihsiz bir son.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boa", "Boa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The constricting Boa ensnares its prey and won't let go.", "Boğucu boa avını sarar ve bırakmaz.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "Bombacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armed with a noxious spray, this odd beetle retaliates against its aggressors.", "Zararlı bir püskürtmeyle donanmış bu tuhaf böcek saldırganlarına karşılık verir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Braxie", "Braxie", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wandering Braxie's horrid stench weakens any threat it encounters.", "Gezgin Braxie'nin korkunç kokusu karşılaştığı her tehdidi zayıflatır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cape Buffalo", "Afrika Mandası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Vengeful Buffalo, attacking it is a woeful decision.", "İntikamcı Manda. Ona saldırmak pişman olunacak bir karardır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bush Dog", "Çalı Köpeği", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thought to be extinct, the Illusive Bush Dog is normally found in packs.", "Soyunun tükendiği düşünülen bu çekingen Çalı Köpeği genellikle sürüler hâlinde bulunur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cadejo", "Cadejo", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound to chance, your guardian will be either benign or maleficent.", "Şansın belirlediği koruyucun ya iyi ya da kötü olacaktır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "Camazotz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A servant to the lords of the underworld, associated with darkness, death... and 'sacrifice'.", "Yeraltı dünyasının efendilerine hizmet eder; karanlık, ölüm... ve “kurban” ile ilişkilidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The \"spit\" of the camel is enough to blind most aggressors.", "Devenin “tükürüğü” çoğu saldırganı kör etmeye yeter.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carpenter Moth", "Ağaçkakan Güvesi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resourceful carpenter, able to draw blood from stone.", "Becerikli marangoz, taştan kan çıkarabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "few are able to catch the nimble cheetah.", "Çevik Çita'ya yetişebilen pek azdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble chicken, its meat is nourishing for most creatures.", "Mütevazı tavuk. Eti çoğu yaratık için besleyicidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chupacabra", "Çupakabra", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the horrid chupacabra. It hungers for your livestock.", "Korkunç Çupakabra. Çiftlik hayvanlarına açtır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-bothersome cicada, using its loud buzzing to summon its kin.", "Hep rahatsızlık veren ağustos böceği, yüksek sesli vızıltısıyla türdeşlerini çağırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cloth", "Kumaş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mystifying Clouded Leopard. The missing link between the cat family.", "Gizemli bulutlu leopar. Kedigiller ailesinin kayıp halkası.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cookiecutter", "Kurabiye Köpekbalığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab", "Yengeç", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an armored crustacean. The crab's carapace covers it from fatal blows.", "Zırhlı bir kabuklu. Yengecin kabuğu onu ölümcül darbelerden korur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dart Frog", "Ok Kurbağası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is Ill-advised to attack this creature.", "Bu yaratığa saldırmak pek akıllıca değildir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirt Pile", "Toprak Yığını", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dobhar-chu", "Dobhar-chu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the king of the otters. The Dobhar-chu requires sustenance to grow.", "Su samurlarının kralı. Dobhar-chu büyümek için beslenmelidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The onerous eagle, a keen guard of the sky. ", "Heybetli kartal, göklerin dikkatli bekçisi. ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did such a creature learn to use electricity as a weapon?", "Böyle bir yaratık elektriği silah olarak kullanmayı nasıl öğrendi?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerging Zombie", "Ortaya Çıkan Zombi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sprightly falcon, eager to attack in a breakneck pace", "Çevik doğan, baş döndürücü bir hızla saldırmaya hevesli.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arboreal Fisher Cat", "Ağaçlarda yaşayan balıkçı sansarı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Cat", "Balıkçı Sansar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, born with a deceitful nature.", "Doğuştan kurnaz bir kızıl tilki.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gargoyle", "Çörten", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A horrid man-made beast, does humanity know no limit?", "İnsan yapımı korkunç bir canavar. İnsanlığın hiç sınırı yok mu?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering culmination of spirits of fallen soldiers, risen from pure hatred in their souls.", "Düşmüş askerlerin ruhlarından oluşan devasa bir varlık; ruhlarındaki saf nefretten doğmuş.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genet", "Genet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slender Genet can sneak past airborne creatures.", "İnce yapılı Genet, Uçuşan yaratıkların yanından gizlice geçebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Lobster", "Dev Istakoz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An eternal lifespan can lead to dire changes in a creature.", "Sonsuz bir yaşam, yaratıkta korkunç değişimlere yol açabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Goblin", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-hungry imp of greed. He shall give you an item... But not without a cost.", "Açgözlülüğün hep aç küçük iblisi. Sana bir eşya verecek... ama bedelsiz değil.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goose", "Kaz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The phoney goose. Rarely will a creature call its bluff.", "Sahtekâr kaz. Çok az yaratık onun blöfünü görür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haggard", "Haggard", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the abominable Haggard, a wretched hulking beast.", "İğrenç Haggard, sefil ve iri bir canavar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammerhead", "Çekiçbaşlı Köpekbalığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perceptive Hammerhead, able to retaliate against those that tread into its waters", "Sularına girenlere karşılık verebilen dikkatli çekiç başlı köpekbalığı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hawk Wasp", "Şahin Eşekarısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The threatening Hawk Wasp. An intelligent hunter.", "Tehditkâr Şahin Eşekarısı. Zeki bir avcı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhound", "Cehennem Tazısı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It spreads misery to those its near, making them suffer its pain", "Yakınındakilere ıstırap yayar, kendi acısını onlara da çektirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heron", "Balıkçıl", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed heron is able to perforate through aquatic creatures.", "Keskin gözlü Balıkçıl, su yaratıklarını delebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highland Cow", "Yayla İneği", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tranquil highland cow, able to shrug off assaults by grazing the land", "Sakin yayla ineği, otlarken saldırılara aldırmayabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Horde", "Sürü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter", "Avcı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"It's all about the sport\" he claims, though his true intentions still remain a mystery.", "“Tek derdim avın heyecanı,” diyor, ama gerçek niyetleri hâlâ bir gizem.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter's Bible", "Avcının İncili", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguana", "İguana", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battered iguana, its power weakens without its tail.", "Hırpalanmış İguana. Kuyruğu olmadan gücü azalır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Isopod", "Dev Eşayaklı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stricken with gigantism, the giant isopod can resist most forms of harm.", "Devlikten mustarip dev izopod, çoğu zarar türüne dayanabilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jaguar", "Jaguar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beware the efficacy of a Jaguar's hunt.", "Jaguarın avlanma becerisinden sakın.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jellyfish", "Denizanası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple invertebrate, with barbed tentacles capable of paralyzing the biggest of creatures.", "En büyük yaratıkları bile felç edebilen dikenli dokunaçlara sahip basit bir omurgasız.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerboa", "Araptavşanı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meager rodent, the jumpy Jerboa will carelessly leap throughout the board.", "Küçük bir kemirgen olan hareketli Araptavşanı, oyun tahtasında düşüncesizce sıçrar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jiangshi", "Jiangşi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This ghastly cadaver steals life energy from unfortunate souls.", "Bu korkunç ceset, talihsiz ruhların yaşam enerjisini çalar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kappa", "Kappa", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A direful spirit of the sea, it will take those who dare tread its waters.", "Denizin korkunç bir ruhu, sularına girmeye cesaret edenleri alıp götürür.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Cobra", "Kral Kobra", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prestigious King Cobra, its venom slowly cripples any aggressor.", "Görkemli kral kobra. Zehri her saldırganı yavaşça etkisiz hâle getirir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Komodo Dragon", "Komodo Ejderi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The baneful Komodo, with a bite so caustic, it's victim is guaranteed a painful death.", "Zararlı Komodo'nun ısırığı öyle yakıcıdır ki kurbanını mutlaka acılı bir ölüm bekler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Krampus", "Krampus", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerging from the winter forests, the hateful krampus marches through, carrying unfortunate souls in his sack.", "Kış ormanlarından çıkan nefret dolu Krampus, talihsiz ruhları çuvalında taşıyarak ilerler.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kuchisake-onna", "Kuchisake-onna", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is she hiding behind that mask?", "O maskenin arkasında ne saklıyor?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion Larva", "Karınca Aslanı Larvası", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the antlion larva is a proficient hunter, though with such dwindling youth.", "Karınca Aslanı Larvası kısa süren gençliğine rağmen yetenekli bir avcıdır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious leopard. Born with an insatiable hunger.", "Vahşi Leopar. Doymak bilmeyen bir açlıkla doğmuştur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethargic Dragon", "Uyuşuk Ejderha", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proud lion, a courageous soul able to empower its kin.", "Gururlu Aslan, türdeşlerini güçlendirebilen cesur bir ruhtur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobster Claw", "Istakoz Kıskacı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lynx attacks with its sharp claws and teeth.", "Yalnız Vaşak, keskin pençeleri ve dişleriyle saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Pup", "Mako Köpekbalığı Yavrusu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The juvenile Mako pup, its no less crafty in it's childlike state.", "Mako köpekbalığı yavrusu, genç yaşına rağmen hiç de daha az kurnaz değildir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mandrill", "Mandril", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mandrill, an aggressive and hefty old-world monkey.", "Mandril, saldırgan ve iri bir Eski Dünya maymunudur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nessie", "Nessie", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remorseless creature, born from a long-forgotten era.", "Çoktan unutulmuş bir çağda doğmuş, acımasız bir yaratık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightcrawlers", "Gece Gezginleri", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such weird creatures they are, acting as one.", "Ne tuhaf yaratıklar; tek bir varlık gibi hareket ediyorlar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not Jerma", "Jerma Değil", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... Don't really know what to say about this one.", "Ben... bunun hakkında ne diyeceğimi gerçekten bilmiyorum.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Golem", "Eski Golem", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a long deactivated protector, born with sentience but no heartbeat.", "Uzun süre önce kapatılmış bir koruyucu; bilinci var ama kalbi atmıyor.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osprey", "Balık Kartalı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Piscivorous Osprey, with claws tailored to catch its prey in the water.", "Balık yiyen Balık Kartalı'nın pençeleri sudaki avları yakalamaya uygundur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owl", "Baykuş", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The predatory Owl grows vicious against other birds, cutting their wings.", "Avcı Baykuş, diğer kuşlara karşı vahşileşir ve kanatlarını keser.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "Parazit", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Penguin", "Penguen", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flightless penguin. An agile swimmer.", "Uçamayan penguen. Çevik bir yüzücü.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom", "Hayalet", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"The dead shall never rest\" is a statement that rings true for the phantom.", "“Ölüler asla dinlenmez” sözü bu hayalet için doğrudur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging Dragon", "Öfkeli Ejderha", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He has risen.", "O ayağa kalktı.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging King Dragon", "Öfkeli Ejderha Kral", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenger", "Çöpçü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the resourceful scavenger, what little consciousness is left is spent on bone collecting.", "Becerikli leşçi, kalan azıcık bilincini kemik toplamaya harcar.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorpion", "Akrep", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rancorous Scorpion. With a potent venom capable of slaying most prey.", "Kin dolu Akrep. Güçlü zehri çoğu avı öldürebilir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shark Fin", "Köpekbalığı Yüzgeci", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrike", "Örümcek Kuşu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gruesome Shrike uses spiked branches to its advantage.", "Korkunç Örümcek Kuşu, dikenli dalları kendi yararına kullanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siguanaba", "Siguanaba", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorrowful spirit that wanders near lakes, luring unwary souls to their demise.", "Göllerin yakınında dolaşan, dikkatsiz ruhları ölüme sürükleyen hüzünlü bir ruh.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Silbon", "El Silbón", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A greedy miscreant. I wonder which bones are from his ascendant?", "Açgözlü bir alçak. Acaba kemiklerden hangileri atasına ait?", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "Deri Gezen", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the malevolent shapeshifter, able to take form of any animal it kills.", "Öldürdüğü her hayvanın biçimine bürünebilen kötü niyetli bir şekil değiştirici.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sleeping Dragon", "Uyuyan Ejderha", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May the gods have mercy on any sorrowful soul who wakes it.", "Onu uyandıran kederli ruha tanrılar merhamet etsin.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Dragon", "Rahatsız Edilmiş Ejderha", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sloth Bear", "Tembel Ayı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The docile sloth bear, it swipes wildly when it feels threatened.", "Uysal Tembel Ayı kendini tehdit altında hissettiğinde çılgınca pençe savurur.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Branches", "Dikenli Dallar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalker", "İz Sürücü", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a husk of a human, doomed to an infernal punishment.", "Cehennem azabına mahkûm, içi boş bir insan bedeni.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strigoi", "Strigoi", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Blood-hungry beast of hell, the Strigoi is evil incarnate.", "Kana susamış bir cehennem canavarı olan Strigoi, kötülüğün ta kendisidir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "superstar", "süperstar", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he gets a lot of money, and drives fancy cars.", "Çok para kazanır ve gösterişli arabalar sürer.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Dragon", "Dikenli Ejder", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Thorny Dragon uses its spikes to deterr predators.", "Dikenli Ejder, avcıları korkutmak için dikenlerini kullanır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thresher Shark", "Sapan Köpekbalığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty Thresher, it uses its tail to attack prey.", "Kurnaz sapan köpekbalığı avına kuyruğuyla saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thunderbird", "Gök Gürültüsü Kuşu", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "born from the mad skies, This Terrorbird dwarves the largest of known creatures.", "Çılgın göklerden doğan bu dehşet kuşu, bilinen en büyük yaratıkları bile cüce gibi gösterir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiger", "Kaplan", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Frightful apex predator, the tiger attacks the weak first.", "Korkunç bir tepe avcısı olan kaplan önce zayıflara saldırır.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuna", "Ton Balığı", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fish that is a lot larger than you may believe.", "Sandığından çok daha büyük bir balık.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the solitary vampire works best when alone.", "Yalnız vampir, tek başına olduğunda en iyi hâlindedir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "Düğmeli Domuz", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the savage warthog, it's attack style is unpredictable.", "Vahşi Düğmeli Domuz'un saldırı tarzı öngörülemezdir.", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigoon", "Wendigoon", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this... is not one of my deathcards...", "Bu... benim Ölüm Kartlarımdan biri değil...", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey there. ", "Merhaba. ", Language.Turkish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how's it going?", "Nasıl gidiyor?", Language.Turkish);
